"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import {
  CheckCircle2,
  Calendar,
  AlertCircle,
  Sparkles,
  Check,
  X,
  Clock,
  ArrowLeft,
  Users,
  Save,
} from "lucide-react";

type SectionOption = { id: string; name: string; class: { name: string } };
type StudentData = { id: string; fullName: string; admissionNo: string };

const STATUSES = ["PRESENT", "ABSENT", "LATE", "HALF_DAY", "LEAVE"] as const;
const STATUS_COLORS: Record<string, string> = {
  PRESENT: "badge-success",
  ABSENT: "badge-danger",
  LATE: "badge-warning",
  HALF_DAY: "badge-warning",
  LEAVE: "badge-info",
};

export default function AdminAttendancePage() {
  const [sections, setSections] = useState<SectionOption[]>([]);
  const [sectionId, setSectionId] = useState("");
  const [date, setDate] = useState(new Date().toISOString().split("T")[0]);
  const [students, setStudents] = useState<StudentData[]>([]);
  const [attendance, setAttendance] = useState<Record<string, string>>({});
  const [existing, setExisting] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    fetch("/api/sections")
      .then((r) => r.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setSections(data);
          if (data.length > 0) setSectionId(data[0].id);
        }
      })
      .catch((err) => console.error("Failed to load sections", err));
  }, []);

  useEffect(() => {
    if (!sectionId) return;
    setLoading(true);
    setMessage("");
    setError("");

    Promise.all([
      fetch(`/api/students?sectionId=${sectionId}`).then((r) => r.json()),
      fetch(`/api/attendance?sectionId=${sectionId}&date=${date}`).then((r) => r.json()),
    ])
      .then(([studentsData, attendanceData]) => {
        const studentList = Array.isArray(studentsData) ? studentsData : [];
        setStudents(studentList);

        const att: Record<string, string> = {};
        const ex = new Set<string>();
        if (Array.isArray(attendanceData)) {
          for (const rec of attendanceData) {
            att[rec.studentId] = rec.status;
            ex.add(rec.studentId);
          }
        }
        for (const s of studentList) {
          if (!att[s.id]) att[s.id] = "PRESENT";
        }
        setAttendance(att);
        setExisting(ex);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to load attendance", err);
        setError("Failed to load attendance data for selected section");
        setLoading(false);
      });
  }, [sectionId, date]);

  const handleSave = async () => {
    setSaving(true);
    setMessage("");
    setError("");

    const records = Object.entries(attendance).map(([studentId, status]) => ({
      studentId,
      status,
    }));

    try {
      const res = await fetch("/api/attendance", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sectionId, date, records }),
      });

      if (res.ok) {
        setMessage(`Attendance saved successfully for ${records.length} students!`);
        const updatedExisting = new Set<string>();
        for (const r of records) updatedExisting.add(r.studentId);
        setExisting(updatedExisting);
      } else {
        const data = await res.json();
        setError(data.error || "Failed to save attendance");
      }
    } catch {
      setError("Network error while saving attendance");
    } finally {
      setSaving(false);
    }
  };

  const markAll = (status: string) => {
    const updated: Record<string, string> = {};
    for (const s of students) {
      updated[s.id] = status;
    }
    setAttendance(updated);
  };

  const presentCount = Object.values(attendance).filter((s) => s === "PRESENT").length;
  const absentCount = Object.values(attendance).filter((s) => s === "ABSENT").length;
  const otherCount = students.length - presentCount - absentCount;

  return (
    <div>
      {/* Breadcrumb Navigation */}
      <div className="breadcrumbs">
        <Link href="/admin/dashboard">Admin</Link>
        <span className="breadcrumb-separator">/</span>
        <span className="breadcrumb-current">Take Attendance</span>
      </div>

      {/* Page Header */}
      <div className="page-header" style={{ marginBottom: "20px" }}>
        <div>
          <h1 className="page-title">Take Class Attendance</h1>
          <p className="page-subtitle">
            Select a class section and date to mark daily student presence records.
          </p>
        </div>
        <Link href="/admin/dashboard" className="btn btn-secondary">
          <ArrowLeft size={16} />
          <span>Back to Dashboard</span>
        </Link>
      </div>

      {/* Notification Alerts */}
      {message && (
        <div className="alert alert-success" style={{ marginBottom: "20px" }}>
          <Check size={18} />
          <span>{message}</span>
        </div>
      )}
      {error && (
        <div className="alert alert-error" style={{ marginBottom: "20px" }}>
          <AlertCircle size={18} />
          <span>{error}</span>
        </div>
      )}

      {/* Filter & Controls Card */}
      <div className="card" style={{ marginBottom: "20px", padding: "18px 20px" }}>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
            gap: "16px",
            alignItems: "flex-end",
          }}
        >
          <div className="form-group" style={{ marginBottom: 0 }}>
            <label className="form-label">
              Select Class &amp; Section <span style={{ color: "var(--danger)" }}>*</span>
            </label>
            <select
              className="form-input"
              value={sectionId}
              onChange={(e) => setSectionId(e.target.value)}
            >
              {sections.length === 0 ? (
                <option value="">No sections available</option>
              ) : (
                sections.map((sec) => (
                  <option key={sec.id} value={sec.id}>
                    {sec.class.name} - Section {sec.name}
                  </option>
                ))
              )}
            </select>
          </div>

          <div className="form-group" style={{ marginBottom: 0 }}>
            <label className="form-label">
              Attendance Date <span style={{ color: "var(--danger)" }}>*</span>
            </label>
            <input
              type="date"
              className="form-input"
              value={date}
              onChange={(e) => setDate(e.target.value)}
            />
          </div>

          <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={() => markAll("PRESENT")}
              disabled={loading || students.length === 0}
            >
              Mark All Present
            </button>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={() => markAll("ABSENT")}
              disabled={loading || students.length === 0}
            >
              Mark All Absent
            </button>
          </div>
        </div>
      </div>

      {/* Roster & Attendance Table */}
      {loading ? (
        <div className="card" style={{ padding: "40px", textAlign: "center" }}>
          <Sparkles size={24} className="animate-spin" style={{ margin: "0 auto 12px" }} />
          <p style={{ color: "var(--text-muted)", margin: 0 }}>Loading student roster...</p>
        </div>
      ) : students.length === 0 ? (
        <div className="card" style={{ padding: "40px", textAlign: "center" }}>
          <Users size={32} style={{ color: "#94a3b8", margin: "0 auto 12px" }} />
          <h3 style={{ fontSize: "16px", fontWeight: 600, color: "var(--text-primary)", marginBottom: "6px" }}>
            No Students Enrolled
          </h3>
          <p style={{ color: "var(--text-muted)", fontSize: "13px", marginBottom: "16px" }}>
            There are no active students in the selected class section.
          </p>
          <Link href="/admin/students/new" className="btn btn-primary btn-sm">
            + Enroll Student
          </Link>
        </div>
      ) : (
        <div className="card">
          <div
            style={{
              padding: "16px 20px",
              borderBottom: "1px solid var(--border-color)",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "10px",
            }}
          >
            <div style={{ display: "flex", gap: "12px", alignItems: "center" }}>
              <span style={{ fontSize: "13.5px", fontWeight: 700, color: "var(--text-primary)" }}>
                Total: {students.length}
              </span>
              <span className="badge badge-success" style={{ fontSize: "11px" }}>
                Present: {presentCount}
              </span>
              <span className="badge badge-danger" style={{ fontSize: "11px" }}>
                Absent: {absentCount}
              </span>
              {otherCount > 0 && (
                <span className="badge badge-warning" style={{ fontSize: "11px" }}>
                  Other: {otherCount}
                </span>
              )}
            </div>

            <button
              onClick={handleSave}
              disabled={saving}
              className="btn btn-primary"
              style={{ padding: "8px 18px" }}
            >
              <Save size={16} />
              <span>{saving ? "Saving..." : "Save Attendance"}</span>
            </button>
          </div>

          <div style={{ overflowX: "auto" }}>
            <table className="table" style={{ width: "100%", margin: 0 }}>
              <thead>
                <tr>
                  <th style={{ width: "50px" }}>#</th>
                  <th>Admission No</th>
                  <th>Student Name</th>
                  <th style={{ width: "380px" }}>Attendance Status</th>
                </tr>
              </thead>
              <tbody>
                {students.map((student, idx) => {
                  const currentStatus = attendance[student.id] || "PRESENT";
                  return (
                    <tr key={student.id}>
                      <td style={{ color: "var(--text-muted)" }}>{idx + 1}</td>
                      <td>
                        <span style={{ fontWeight: 600 }}>{student.admissionNo}</span>
                      </td>
                      <td>
                        <span style={{ fontWeight: 600, color: "var(--text-primary)" }}>
                          {student.fullName}
                        </span>
                      </td>
                      <td>
                        <div style={{ display: "flex", gap: "4px", flexWrap: "wrap" }}>
                          {STATUSES.map((status) => {
                            const isSelected = currentStatus === status;
                            return (
                              <button
                                key={status}
                                type="button"
                                onClick={() =>
                                  setAttendance((prev) => ({ ...prev, [student.id]: status }))
                                }
                                style={{
                                  padding: "4px 10px",
                                  fontSize: "11.5px",
                                  fontWeight: isSelected ? 700 : 500,
                                  borderRadius: "6px",
                                  border: isSelected
                                    ? "1.5px solid var(--primary)"
                                    : "1px solid var(--border-color)",
                                  background: isSelected ? "var(--primary-light)" : "var(--bg-surface)",
                                  color: isSelected ? "var(--primary)" : "var(--text-secondary)",
                                  cursor: "pointer",
                                  transition: "all 0.12s ease",
                                }}
                              >
                                {status === "PRESENT"
                                  ? "Present"
                                  : status === "ABSENT"
                                  ? "Absent"
                                  : status === "LATE"
                                  ? "Late"
                                  : status === "HALF_DAY"
                                  ? "Half Day"
                                  : "Leave"}
                              </button>
                            );
                          })}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div
            style={{
              padding: "16px 20px",
              borderTop: "1px solid var(--border-color)",
              display: "flex",
              justifyContent: "flex-end",
            }}
          >
            <button
              onClick={handleSave}
              disabled={saving}
              className="btn btn-primary"
              style={{ padding: "10px 22px" }}
            >
              <Save size={16} />
              <span>{saving ? "Saving..." : "Save Attendance"}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { FileCheck, Sparkles, Calendar, FileText, Search, User } from "lucide-react";

type TCLog = {
  id: string;
  tcNumber: string;
  issueDate: string;
  reasonForLeaving: string;
  lastAttendanceDate: string;
  conductRemark: string;
  createdAt: string;
  student: {
    fullName: string;
    admissionNo: string;
    section: { name: string; class: { name: string } } | null;
  };
  generatedByUser: { email: string };
};

export default function CertificatesPage() {
  const [logs, setLogs] = useState<TCLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    fetch("/api/certificates/generate")
      .then((r) => r.json())
      .then((data) => {
        setLogs(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const filteredLogs = logs.filter(
    (l) =>
      l.student.fullName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      l.tcNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
      l.student.admissionNo.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (loading) {
    return (
      <div className="office-page-container" style={{ padding: "60px 20px", textAlign: "center" }}>
        <Sparkles size={22} className="animate-spin" color="#1e3a8a" style={{ margin: "0 auto 8px" }} />
        <div style={{ color: "#64748b", fontSize: "14px" }}>Loading TC Register records...</div>
      </div>
    );
  }

  return (
    <div className="office-page-container">
      {/* ─── Header ─── */}
      <div className="office-header">
        <div>
          <h1 className="office-title">Transfer Certificates (TC) Register</h1>
          <p className="office-subtitle">
            Permanent school registry of all issued Transfer, Leaving, and Bonafide Certificates
          </p>
        </div>
        <div className="office-actions-bar">
          <Link href="/admin/students" className="office-btn office-btn-secondary">
            <User size={14} />
            <span>Generate from Student Profile</span>
          </Link>
        </div>
      </div>

      {/* ─── Search Bar ─── */}
      <div
        style={{
          background: "#ffffff",
          border: "1px solid #e2e8f0",
          borderRadius: "10px",
          padding: "14px 18px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: "14px",
          marginBottom: "20px",
        }}
      >
        <div className="office-search-wrapper" style={{ flex: 1, minWidth: "240px", maxWidth: "380px" }}>
          <Search size={16} className="office-search-icon" />
          <input
            type="text"
            placeholder="Search by student name or TC number..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="office-input office-search-input"
            style={{ width: "100%" }}
          />
        </div>

        <div style={{ fontSize: "13px", color: "#64748b" }}>
          Total Issued: <strong>{logs.length}</strong> certificates
        </div>
      </div>

      {logs.length === 0 ? (
        <div className="office-card" style={{ padding: "48px 20px", textAlign: "center" }}>
          <FileText size={36} color="#94a3b8" style={{ margin: "0 auto 8px" }} />
          <div style={{ fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>No Transfer Certificates Issued Yet</div>
          <p style={{ fontSize: "13px", color: "#64748b", margin: "4px 0 16px 0" }}>
            When a Transfer Certificate is generated from a student&apos;s profile, it is permanently logged here.
          </p>
          <Link href="/admin/students" className="office-btn office-btn-primary office-btn-sm">
            <span>Go to Student Directory</span>
          </Link>
        </div>
      ) : (
        <div className="office-table-wrapper">
          <table className="office-table">
            <thead>
              <tr>
                <th style={{ width: "140px" }}>TC Number</th>
                <th>Student Name</th>
                <th>Class & Section</th>
                <th>Issue Date</th>
                <th>Reason for Leaving</th>
                <th>Conduct</th>
                <th>Issued By</th>
              </tr>
            </thead>
            <tbody>
              {filteredLogs.map((log) => (
                <tr key={log.id}>
                  <td style={{ fontFamily: "monospace", fontWeight: 700, color: "#1e3a8a", fontSize: "13px" }}>
                    {log.tcNumber}
                  </td>
                  <td>
                    <div style={{ fontWeight: 600, color: "#0f172a" }}>{log.student.fullName}</div>
                    <div style={{ fontSize: "12px", color: "#64748b" }}>{log.student.admissionNo}</div>
                  </td>
                  <td style={{ color: "#334155" }}>
                    {log.student.section
                      ? `${log.student.section.class.name} — ${log.student.section.name}`
                      : "—"}
                  </td>
                  <td style={{ color: "#475569", fontSize: "13px" }}>
                    {new Date(log.issueDate).toLocaleDateString("en-IN", {
                      day: "2-digit",
                      month: "short",
                      year: "numeric",
                    })}
                  </td>
                  <td style={{ maxWidth: "220px", fontSize: "13px", color: "#334155" }}>
                    {log.reasonForLeaving}
                  </td>
                  <td>
                    <span className="office-pill office-pill-green">
                      {log.conductRemark}
                    </span>
                  </td>
                  <td style={{ fontSize: "12.5px", color: "#64748b" }}>
                    {log.generatedByUser.email}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  School,
  Plus,
  AlertCircle,
  Sparkles,
  ChevronDown,
  ChevronRight,
  Users,
  Pencil,
  Trash2,
  Check,
  X,
} from "lucide-react";

/* ─── Types ─── */
type TeacherOption = { id: string; fullName: string };

type SectionData = {
  id: string;
  name: string;
  academicYear: string;
  classTeacher?: { id: string; fullName: string } | null;
  classTeacherId?: string | null;
  _count: { students: number };
};

type ClassData = {
  id: string;
  name: string;
  order: number;
  sections: SectionData[];
};

type SectionDraft = {
  name: string;
  classTeacherId: string;
};

const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

function generateDefaultSections(count: number): SectionDraft[] {
  return Array.from({ length: count }, (_, i) => ({
    name: LETTERS[i] || `S${i + 1}`,
    classTeacherId: "",
  }));
}

export default function ClassesPage() {
  const [classes, setClasses] = useState<ClassData[]>([]);
  const [teachers, setTeachers] = useState<TeacherOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [expandedClassId, setExpandedClassId] = useState<string | null>(null);

  // Creation form state
  const [className, setClassName] = useState("");
  const [sectionCount, setSectionCount] = useState(1);
  const [sectionDrafts, setSectionDrafts] = useState<SectionDraft[]>(generateDefaultSections(1));
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const fetchClasses = async () => {
    const res = await fetch("/api/classes");
    const data = await res.json();
    setClasses(Array.isArray(data) ? data : []);
    setLoading(false);
  };

  useEffect(() => {
    Promise.all([
      fetch("/api/classes").then((r) => r.json()),
      fetch("/api/teachers").then((r) => r.json()),
    ])
      .then(([classesData, teachersData]) => {
        setClasses(Array.isArray(classesData) ? classesData : []);
        setTeachers(Array.isArray(teachersData) ? teachersData : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const handleSectionCountChange = (count: number) => {
    const clamped = Math.max(1, Math.min(26, count));
    setSectionCount(clamped);
    setSectionDrafts((prev) => {
      if (clamped > prev.length) {
        return [
          ...prev,
          ...Array.from({ length: clamped - prev.length }, (_, i) => ({
            name: LETTERS[prev.length + i] || `S${prev.length + i + 1}`,
            classTeacherId: "",
          })),
        ];
      }
      return prev.slice(0, clamped);
    });
  };

  const updateDraftName = (idx: number, name: string) => {
    setSectionDrafts((prev) => prev.map((d, i) => (i === idx ? { ...d, name } : d)));
  };

  const updateDraftTeacher = (idx: number, classTeacherId: string) => {
    setSectionDrafts((prev) => prev.map((d, i) => (i === idx ? { ...d, classTeacherId } : d)));
  };

  const resetForm = () => {
    setClassName("");
    setSectionCount(1);
    setSectionDrafts(generateDefaultSections(1));
    setError("");
    setShowForm(false);
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSubmitting(true);

    try {
      const res = await fetch("/api/classes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: className,
          sections: sectionDrafts.map((d) => ({
            name: d.name,
            classTeacherId: d.classTeacherId || undefined,
          })),
        }),
      });

      setSubmitting(false);

      if (!res.ok) {
        const data = await res.json();
        setError(data.error || "Failed to create class");
        return;
      }

      resetForm();
      fetchClasses();
    } catch (err: any) {
      setSubmitting(false);
      setError(err.message || "Failed to create class");
    }
  };

  if (loading) {
    return (
      <div className="office-page-container" style={{ padding: "60px 20px", textAlign: "center" }}>
        <Sparkles size={22} className="animate-spin" color="#1e3a8a" style={{ margin: "0 auto 8px" }} />
        <div style={{ color: "#64748b", fontSize: "14px" }}>Loading classes & sections...</div>
      </div>
    );
  }

  return (
    <div className="office-page-container">
      {/* ─── Header ─── */}
      <div className="office-header">
        <div>
          <h1 className="office-title">Classes & Sections</h1>
          <p className="office-subtitle">
            Configure academic grade levels, classroom sections, and class teacher allocations
          </p>
        </div>
        <div className="office-actions-bar">
          <button
            className="office-btn office-btn-primary"
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? <X size={16} /> : <Plus size={16} />}
            <span>{showForm ? "Cancel" : "Add Class"}</span>
          </button>
        </div>
      </div>

      {/* ─── Add Class Form ─── */}
      {showForm && (
        <div className="office-card" style={{ border: "2px solid #bfdbfe", background: "#f8fafc" }}>
          <div className="office-card-header">
            <h3 className="office-card-title">Create Class & Allocate Sections</h3>
          </div>
          {error && (
            <div style={{ color: "#dc2626", fontSize: "13px", marginBottom: "12px" }}>
              {error}
            </div>
          )}
          <form onSubmit={handleCreate}>
            <div className="office-form-grid-2">
              <div className="office-form-group">
                <label className="office-form-label">
                  Class / Grade Name <span style={{ color: "#dc2626" }}>*</span>
                </label>
                <input
                  type="text"
                  placeholder="e.g. Class 1, Grade 10"
                  value={className}
                  onChange={(e) => setClassName(e.target.value)}
                  className="office-input"
                  style={{ width: "100%" }}
                  required
                />
              </div>

              <div className="office-form-group">
                <label className="office-form-label">
                  Number of Sections <span style={{ color: "#dc2626" }}>*</span>
                </label>
                <input
                  type="number"
                  min="1"
                  max="26"
                  value={sectionCount}
                  onChange={(e) => handleSectionCountChange(Number(e.target.value))}
                  className="office-input"
                  style={{ width: "100%" }}
                  required
                />
              </div>
            </div>

            {/* Section preview cards */}
            <div style={{ marginTop: "14px", marginBottom: "14px" }}>
              <label className="office-form-label" style={{ marginBottom: "8px", display: "block" }}>
                Section Assignments
              </label>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
                  gap: "12px",
                }}
              >
                {sectionDrafts.map((draft, idx) => (
                  <div
                    key={idx}
                    style={{
                      background: "#ffffff",
                      border: "1px solid #cbd5e1",
                      borderRadius: "8px",
                      padding: "12px",
                    }}
                  >
                    <div style={{ fontSize: "12px", fontWeight: 700, color: "#1e3a8a", marginBottom: "6px" }}>
                      Section {idx + 1}
                    </div>
                    <div style={{ marginBottom: "8px" }}>
                      <input
                        className="office-input"
                        value={draft.name}
                        onChange={(e) => updateDraftName(idx, e.target.value)}
                        placeholder="A"
                        required
                        style={{ height: "32px", fontSize: "13px", fontWeight: 600, textAlign: "center", width: "100%" }}
                      />
                    </div>
                    <div>
                      <select
                        className="office-select"
                        value={draft.classTeacherId}
                        onChange={(e) => updateDraftTeacher(idx, e.target.value)}
                        style={{ height: "32px", fontSize: "12px", width: "100%" }}
                      >
                        <option value="">— Unassigned —</option>
                        {teachers.map((t) => (
                          <option key={t.id} value={t.id}>
                            {t.fullName}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ display: "flex", gap: "10px", marginTop: "16px" }}>
              <button className="office-btn office-btn-primary" type="submit" disabled={submitting}>
                {submitting ? "Creating..." : "Create Class & Sections"}
              </button>
              <button className="office-btn office-btn-secondary" type="button" onClick={resetForm}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {/* ─── Class List ─── */}
      {classes.length === 0 ? (
        <div className="office-card" style={{ padding: "48px 20px", textAlign: "center" }}>
          <School size={36} color="#94a3b8" style={{ margin: "0 auto 8px" }} />
          <div style={{ fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>No Classes Configured</div>
          <p style={{ fontSize: "13px", color: "#64748b", margin: "4px 0 16px 0" }}>
            Add your school grade levels (e.g. Class 1 to 12) to start assigning students and sections.
          </p>
          <button className="office-btn office-btn-primary office-btn-sm" onClick={() => setShowForm(true)}>
            <Plus size={14} />
            <span>Add First Class</span>
          </button>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          {classes.map((cls) => {
            const isExpanded = expandedClassId === cls.id;
            const totalStudents = cls.sections.reduce((acc, s) => acc + s._count.students, 0);

            return (
              <div key={cls.id} className="office-card" style={{ padding: 0, overflow: "hidden" }}>
                <div
                  onClick={() => setExpandedClassId(isExpanded ? null : cls.id)}
                  style={{
                    padding: "16px 20px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    cursor: "pointer",
                    background: isExpanded ? "#f8fafc" : "#ffffff",
                    borderBottom: isExpanded ? "1px solid #e2e8f0" : "none",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
                    <div style={{ color: "#64748b" }}>
                      {isExpanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
                    </div>
                    <div>
                      <div style={{ fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>{cls.name}</div>
                      <div style={{ fontSize: "12.5px", color: "#64748b" }}>
                        Level {cls.order} • {cls.sections.length} section{cls.sections.length !== 1 ? "s" : ""}
                      </div>
                    </div>
                  </div>
                  <span className="office-pill office-pill-blue">
                    <Users size={12} />
                    <span>{totalStudents} student{totalStudents !== 1 ? "s" : ""}</span>
                  </span>
                </div>

                {isExpanded && (
                  <ExpandedSections
                    cls={cls}
                    teachers={teachers}
                    onRefresh={fetchClasses}
                  />
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ExpandedSections({
  cls,
  teachers,
  onRefresh,
}: {
  cls: ClassData;
  teachers: TeacherOption[];
  onRefresh: () => void;
}) {
  const [addingSection, setAddingSection] = useState(false);
  const [newSectionName, setNewSectionName] = useState("");
  const [newSectionTeacher, setNewSectionTeacher] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [editTeacher, setEditTeacher] = useState("");
  const [error, setError] = useState("");
  const [actionLoading, setActionLoading] = useState(false);

  const handleAddSection = async () => {
    if (!newSectionName.trim()) return;
    setActionLoading(true);
    setError("");

    try {
      const res = await fetch("/api/sections", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          classId: cls.id,
          name: newSectionName.trim(),
          academicYear: "2026-27",
          classTeacherId: newSectionTeacher || undefined,
        }),
      });

      setActionLoading(false);
      if (!res.ok) {
        const data = await res.json();
        setError(data.error || "Failed to add section");
        return;
      }

      setAddingSection(false);
      setNewSectionName("");
      setNewSectionTeacher("");
      onRefresh();
    } catch (err: any) {
      setActionLoading(false);
      setError(err.message || "Failed to add section");
    }
  };

  const startEdit = (section: SectionData) => {
    setEditingId(section.id);
    setEditName(section.name);
    setEditTeacher(section.classTeacherId || section.classTeacher?.id || "");
    setError("");
  };

  const handleSaveEdit = async () => {
    if (!editingId || !editName.trim()) return;
    setActionLoading(true);
    setError("");

    try {
      const res = await fetch("/api/sections", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          id: editingId,
          name: editName.trim(),
          classTeacherId: editTeacher || null,
        }),
      });

      setActionLoading(false);
      if (!res.ok) {
        const data = await res.json();
        setError(data.error || "Failed to update section");
        return;
      }

      setEditingId(null);
      onRefresh();
    } catch (err: any) {
      setActionLoading(false);
      setError(err.message || "Failed to update section");
    }
  };

  const handleDelete = async (section: SectionData) => {
    if (section._count.students > 0) {
      setError(
        `Cannot delete Section ${section.name} — ${section._count.students} student(s) enrolled. Reassign them first.`
      );
      return;
    }

    if (!confirm(`Delete Section ${section.name}? This cannot be undone.`)) return;

    setActionLoading(true);
    setError("");

    try {
      const res = await fetch("/api/sections", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: section.id }),
      });

      setActionLoading(false);
      if (!res.ok) {
        const data = await res.json();
        setError(data.error || "Failed to delete section");
        return;
      }

      onRefresh();
    } catch (err: any) {
      setActionLoading(false);
      setError(err.message || "Failed to delete section");
    }
  };

  return (
    <div style={{ padding: "16px 20px", background: "#f8fafc" }}>
      {error && (
        <div style={{ color: "#dc2626", fontSize: "13px", marginBottom: "12px" }}>
          {error}
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: "8px", marginBottom: "14px" }}>
        {cls.sections.map((section) => {
          const isEditingThis = editingId === section.id;
          return (
            <div
              key={section.id}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "10px 14px",
                background: "#ffffff",
                border: "1px solid #e2e8f0",
                borderRadius: "8px",
                flexWrap: "wrap",
                gap: "10px",
              }}
            >
              {isEditingThis ? (
                <div style={{ display: "flex", alignItems: "center", gap: "10px", flex: 1 }}>
                  <input
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    className="office-input"
                    style={{ width: "70px", height: "32px", fontSize: "13px" }}
                  />
                  <select
                    value={editTeacher}
                    onChange={(e) => setEditTeacher(e.target.value)}
                    className="office-select"
                    style={{ height: "32px", fontSize: "12.5px" }}
                  >
                    <option value="">— Unassigned —</option>
                    {teachers.map((t) => (
                      <option key={t.id} value={t.id}>
                        {t.fullName}
                      </option>
                    ))}
                  </select>
                  <button
                    onClick={handleSaveEdit}
                    disabled={actionLoading}
                    className="office-btn office-btn-primary office-btn-sm"
                  >
                    <Check size={12} />
                  </button>
                  <button
                    onClick={() => setEditingId(null)}
                    className="office-btn office-btn-secondary office-btn-sm"
                  >
                    <X size={12} />
                  </button>
                </div>
              ) : (
                <>
                  <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
                    <span style={{ fontWeight: 700, fontSize: "14px", color: "#0f172a" }}>
                      Section {section.name}
                    </span>
                    <span style={{ fontSize: "12.5px", color: "#64748b" }}>
                      Teacher:{" "}
                      <strong style={{ color: "#334155" }}>
                        {section.classTeacher?.fullName || "Unassigned"}
                      </strong>
                    </span>
                    <span style={{ fontSize: "12px", color: "#94a3b8" }}>
                      ({section._count.students} students)
                    </span>
                  </div>

                  <div style={{ display: "flex", gap: "6px" }}>
                    <button
                      onClick={() => startEdit(section)}
                      className="office-btn office-btn-secondary office-btn-sm"
                    >
                      <Pencil size={12} />
                      <span>Edit</span>
                    </button>
                    <button
                      onClick={() => handleDelete(section)}
                      className="office-btn office-btn-secondary office-btn-sm"
                      style={{ color: "#dc2626" }}
                    >
                      <Trash2 size={12} />
                    </button>
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>

      {addingSection ? (
        <div style={{ display: "flex", gap: "10px", alignItems: "center", flexWrap: "wrap" }}>
          <input
            placeholder="Section Name (e.g. C)"
            value={newSectionName}
            onChange={(e) => setNewSectionName(e.target.value)}
            className="office-input"
            style={{ width: "160px", height: "34px", fontSize: "13px" }}
          />
          <select
            value={newSectionTeacher}
            onChange={(e) => setNewSectionTeacher(e.target.value)}
            className="office-select"
            style={{ height: "34px", fontSize: "12.5px" }}
          >
            <option value="">-- Assign Teacher --</option>
            {teachers.map((t) => (
              <option key={t.id} value={t.id}>
                {t.fullName}
              </option>
            ))}
          </select>
          <button
            onClick={handleAddSection}
            disabled={actionLoading || !newSectionName.trim()}
            className="office-btn office-btn-primary office-btn-sm"
          >
            Save Section
          </button>
          <button
            onClick={() => setAddingSection(false)}
            className="office-btn office-btn-secondary office-btn-sm"
          >
            Cancel
          </button>
        </div>
      ) : (
        <button
          onClick={() => setAddingSection(true)}
          className="office-btn office-btn-secondary office-btn-sm"
        >
          <Plus size={13} />
          <span>Add Section to {cls.name}</span>
        </button>
      )}
    </div>
  );
}

