"use client";

import { useEffect, useState } from "react";
import { CreditCard, Printer, Sparkles, CheckSquare, Square } from "lucide-react";

interface Student {
  id: string;
  fullName: string;
  admissionNo: string;
  rollNumber: string | null;
  dob: string | null;
  gender: string;
  bloodGroup: string | null;
  emergencyContactPhone: string | null;
  address: string | null;
  photoUrl: string | null;
  section?: {
    id: string;
    name: string;
    class: {
      id: string;
      name: string;
    };
  };
  parents?: Array<{
    parent: {
      fullName: string;
      phone: string;
    };
  }>;
}

interface ClassItem {
  id: string;
  name: string;
  sections: Array<{ id: string; name: string }>;
}

export default function IdCardsPage() {
  const [classes, setClasses] = useState<ClassItem[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<string>("");
  const [selectedSectionId, setSelectedSectionId] = useState<string>("");
  const [selectedStudentIds, setSelectedStudentIds] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);
  const [schoolInfo, setSchoolInfo] = useState<{ name: string; boardType: string; affiliationNumber?: string }>({
    name: "",
    boardType: "CBSE",
    affiliationNumber: "",
  });
  const [schoolLoading, setSchoolLoading] = useState(true);

  useEffect(() => {
    fetch("/api/schools/settings")
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (data?.name) {
          setSchoolInfo({
            name: data.name,
            boardType: data.boardType || "CBSE",
            affiliationNumber: data.affiliationNumber || "",
          });
        }
      })
      .catch((err) => console.error("Error loading school branding:", err))
      .finally(() => setSchoolLoading(false));
  }, []);

  useEffect(() => {
    fetch("/api/classes")
      .then((r) => r.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setClasses(data);
          if (data.length > 0) {
            setSelectedClassId(data[0].id);
          }
        }
      });
  }, []);

  useEffect(() => {
    if (!selectedClassId) return;
    setLoading(true);
    let url = `/api/students?classId=${selectedClassId}`;
    if (selectedSectionId) {
      url += `&sectionId=${selectedSectionId}`;
    }

    fetch(url)
      .then((r) => r.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setStudents(data);
          setSelectedStudentIds(new Set(data.map((s) => s.id)));
        } else {
          setStudents([]);
          setSelectedStudentIds(new Set());
        }
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [selectedClassId, selectedSectionId]);

  const toggleSelectAll = () => {
    if (selectedStudentIds.size === students.length) {
      setSelectedStudentIds(new Set());
    } else {
      setSelectedStudentIds(new Set(students.map((s) => s.id)));
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const currentClass = classes.find((c) => c.id === selectedClassId);
  const selectedStudents = students.filter((s) => selectedStudentIds.has(s.id));

  return (
    <div>
      {/* Screen Only Controls */}
      <div className="no-print">
        <div className="page-header">
          <div>
            <h1 className="page-title">Student Identity Cards Studio</h1>
            <p className="page-subtitle">Generate and batch print high-resolution biometric student ID cards.</p>
          </div>
          <button
            onClick={handlePrint}
            className="btn btn-primary"
            disabled={selectedStudents.length === 0}
          >
            <Printer size={16} />
            <span>Print {selectedStudents.length} ID Cards</span>
          </button>
        </div>

        {/* Filters and Selection Bar */}
        <div className="card" style={{ marginBottom: "24px" }}>
          <div style={{ display: "flex", gap: "16px", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between" }}>
            <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", alignItems: "center" }}>
              <div>
                <label className="label" style={{ fontSize: "0.8rem", marginBottom: "4px" }}>Class</label>
                <select
                  className="input"
                  value={selectedClassId}
                  onChange={(e) => {
                    setSelectedClassId(e.target.value);
                    setSelectedSectionId("");
                  }}
                  style={{ minWidth: "160px" }}
                >
                  {classes.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="label" style={{ fontSize: "0.8rem", marginBottom: "4px" }}>Section</label>
                <select
                  className="input"
                  value={selectedSectionId}
                  onChange={(e) => setSelectedSectionId(e.target.value)}
                  style={{ minWidth: "140px" }}
                >
                  <option value="">All Sections</option>
                  {currentClass?.sections.map((sec) => (
                    <option key={sec.id} value={sec.id}>
                      Section {sec.name}
