                <div style={{ marginTop: "16px", paddingTop: "14px", borderTop: "1px solid var(--border-subtle)" }}>
                  <div style={{ fontSize: "12px", fontWeight: 600, color: "var(--text-muted)", marginBottom: "8px" }}>
                    LINKED PARENT PORTAL ACCOUNTS
                  </div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
                    {student.parents.map((p) => (
                      <div key={p.parent.id} className="badge badge-teal" style={{ padding: "6px 12px", fontSize: "12px" }}>
                        <span>{p.parent.fullName}</span>
                        <span style={{ opacity: 0.7 }}>({p.relationship})</span>
                        <span>• {p.parent.user.email}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Section 4: Previous School & Medical */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "24px" }}>
              {/* Previous School */}
              <div className="card">
                <div className="card-header" style={{ borderBottom: "1px solid var(--border-subtle)", paddingBottom: "12px", marginBottom: "16px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                    <BookOpen size={18} color="#2dd4bf" />
                    <h3 className="card-title" style={{ margin: 0, fontSize: "15px" }}>Prior Academic Record</h3>
                  </div>
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: "10px", fontSize: "13.5px" }}>
                  <div>
                    <span style={{ color: "var(--text-muted)", fontSize: "12px" }}>Previous School: </span>
                    <div style={{ fontWeight: 600, color: "var(--text-primary)" }}>
                      {student.previousSchoolName || "No previous school recorded"}
                    </div>
                  </div>
                  <div>
                    <span style={{ color: "var(--text-muted)", fontSize: "12px" }}>Last Class Attended: </span>
                    <div style={{ color: "var(--text-secondary)" }}>{student.previousClass || "—"}</div>
                  </div>
                  <div>
                    <span style={{ color: "var(--text-muted)", fontSize: "12px" }}>Transfer Certificate (TC) No: </span>
                    <div style={{ color: "var(--text-secondary)", fontFamily: "monospace" }}>
                      {student.transferCertificateNumber || "—"}
                    </div>
                  </div>
                </div>
              </div>

              {/* Emergency & Medical */}
              <div className="card">
                <div className="card-header" style={{ borderBottom: "1px solid var(--border-subtle)", paddingBottom: "12px", marginBottom: "16px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                    <HeartPulse size={18} color="#f43f5e" />
                    <h3 className="card-title" style={{ margin: 0, fontSize: "15px" }}>Emergency & Medical</h3>
                  </div>
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: "10px", fontSize: "13.5px" }}>
                  <div>
                    <span style={{ color: "var(--text-muted)", fontSize: "12px" }}>Emergency Contact: </span>
                    <div style={{ fontWeight: 600, color: "var(--text-primary)" }}>
                      {student.emergencyContactName || "Not specified"}
                    </div>
                    {student.emergencyContactPhone && (
                      <div style={{ fontSize: "12.5px", color: "var(--text-secondary)", display: "flex", alignItems: "center", gap: "4px", marginTop: "2px" }}>
                        <Phone size={12} />
                        <span>{student.emergencyContactPhone}</span>
                      </div>
                    )}
                  </div>
                  <div>
                    <span style={{ color: "var(--text-muted)", fontSize: "12px" }}>Medical Conditions & Allergies: </span>
                    <div style={{ color: "var(--text-secondary)", lineHeight: 1.4, marginTop: "2px" }}>
                      {student.medicalConditions || "No chronic conditions or allergies noted"}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Section 5: Fee Invoices & Payment Ledger (Admin & Accountant Record Payment Power) */}
            <div className="card">
              <div
                className="card-header"
                style={{
                  borderBottom: "1px solid var(--border-subtle)",
                  paddingBottom: "12px",
                  marginBottom: "16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                  <Receipt size={18} color="#fbbf24" />
                  <h3 className="card-title" style={{ margin: 0, fontSize: "15px" }}>Fee Statement & Invoices</h3>
                </div>
              </div>

              <div className="table-container">
                <table>
                  <thead>
                    <tr>
                      <th>Fee Description</th>
                      <th>Due Date</th>
                      <th>Amount Due</th>
                      <th>Discount</th>
                      <th>Status</th>
                      <th>Payments Made</th>
                      <th style={{ textAlign: "right" }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {student.invoices.length === 0 ? (
                      <tr>
                        <td colSpan={7}>
                          <div className="empty-state" style={{ padding: "24px" }}>
                            <Receipt size={24} color="#fbbf24" />
                            <div className="empty-state-title" style={{ fontSize: "14px" }}>No fee invoices issued</div>
                            <p className="empty-state-text">No invoices were generated during student admission.</p>
                          </div>
                        </td>
                      </tr>
                    ) : (
                      student.invoices.map((inv) => {
                        const paid = inv.payments.reduce((s, p) => s + parseFloat(p.amount), 0);
                        const isPayable = inv.status === "UNPAID" || inv.status === "PARTIALLY_PAID" || inv.status === "OVERDUE";
                        return (
                          <tr key={inv.id}>
                            <td style={{ fontWeight: 600, color: "var(--text-primary)" }}>{inv.feeStructure.name}</td>
                            <td style={{ color: "var(--text-muted)" }}>{formatDate(inv.dueDate)}</td>
                            <td className="num-cell">₹{inv.amountDue}</td>
                            <td className="num-cell" style={{ color: "var(--text-muted)" }}>
                              {inv.discountAmount !== "0.00" ? `₹${inv.discountAmount}` : "—"}
                            </td>
                            <td>
                              <span className={`badge ${STATUS_BADGE[inv.status] || "badge-info"}`}>
                                <span className="badge-dot" />
                                <span>{inv.status.replace("_", " ")}</span>
                              </span>
                            </td>
                            <td>
                              {inv.payments.length === 0 ? (
                                <span style={{ color: "var(--text-muted)", fontSize: "12.5px" }}>Unpaid</span>
                              ) : (
                                <div style={{ display: "flex", flexDirection: "column", gap: "2px" }}>
                                  <span style={{ color: "#34d399", fontWeight: 600 }}>₹{paid.toFixed(2)}</span>
                                  <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
                                    {inv.payments.map((p) => (
                                      <a
                                        key={p.id}
                                        href={`/api/receipt/${p.id}`}
                                        target="_blank"
                                        rel="noreferrer"
                                        style={{ fontSize: "11px", color: "#818cf8", textDecoration: "none", display: "inline-flex", alignItems: "center", gap: "3px" }}
                                        title="Download / View Receipt"
                                      >
                                        <FileText size={10} />
                                        <span>Receipt #{p.receiptNumber}</span>
                                      </a>
                                    ))}
                                  </div>
                                </div>
                              )}
                            </td>
                            <td style={{ textAlign: "right" }}>
                              {isPayable ? (
                                <button
                                  type="button"
                                  className="btn btn-secondary btn-sm"
                                  onClick={() => openRecordPaymentModal(inv)}
                                  style={{ gap: "5px", fontSize: "12px" }}
                                >
                                  <CreditCard size={13} />
                                  <span>Record Payment</span>
                                </button>
                              ) : (
                                <span className="badge badge-success" style={{ fontSize: "11px" }}>
                                  Settled
                                </span>
                              )}
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Section 6: Attendance History (Last 30 Days) */}
            <div className="card">
              <div className="card-header" style={{ borderBottom: "1px solid var(--border-subtle)", paddingBottom: "12px", marginBottom: "16px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                  <Calendar size={18} color="#818cf8" />
                  <h3 className="card-title" style={{ margin: 0, fontSize: "15px" }}>Recent Attendance History (Last 30 Records)</h3>
                </div>
                {totalAttendance > 0 && (
                  <div style={{ display: "flex", gap: "8px", fontSize: "12px" }}>
                    <span className="badge badge-success">{presentDays} Present</span>
                    <span className="badge badge-danger">{absentDays} Absent</span>
                    {lateDays > 0 && <span className="badge badge-warning">{lateDays} Late</span>}
                  </div>
                )}
              </div>

              <div className="table-container">
                <table>
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Attendance Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {student.attendance.length === 0 ? (
                      <tr>
                        <td colSpan={2}>
                          <div className="empty-state" style={{ padding: "24px" }}>
                            <Calendar size={24} color="#818cf8" />
                            <div className="empty-state-title" style={{ fontSize: "14px" }}>No attendance logs yet</div>
                            <p className="empty-state-text">Attendance logs will appear as class teachers take attendance.</p>
                          </div>
                        </td>
                      </tr>
                    ) : (
                      student.attendance.map((a) => (
                        <tr key={a.id}>
                          <td style={{ color: "var(--text-primary)", fontWeight: 500 }}>
                            {formatDate(a.date)}
                          </td>
                          <td>
                            <span className={`badge ${STATUS_BADGE[a.status] || "badge-info"}`}>
                              <span className="badge-dot" />
                              <span>{a.status.replace("_", " ")}</span>
                            </span>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </>
      )}

      {/* ─── LIVE REPORT CARD MODAL ─── */}
      {showReportCardModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0, 0, 0, 0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
            padding: "20px",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowReportCardModal(false)}
        >
          <div
            style={{
              maxWidth: "850px",
              width: "100%",
              maxHeight: "92vh",
              overflowY: "auto",
              borderRadius: "8px",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {loadingReportCard ? (
              <div className="card" style={{ padding: "40px", textAlign: "center" }}>
                <div className="loading">
                  <Sparkles size={18} className="animate-spin" /> Generating official report card...
                </div>
              </div>
            ) : reportCardData ? (
              <ReportCardView
                data={reportCardData}
                onClose={() => setShowReportCardModal(false)}
                showCloseButton={true}
              />
            ) : (
              <div className="card" style={{ padding: "40px", textAlign: "center" }}>
                <div className="empty-state-title">Unable to generate report card</div>
                <button
                  className="btn btn-secondary btn-sm"
                  style={{ marginTop: "12px" }}
                  onClick={() => setShowReportCardModal(false)}
                >
                  Close
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ─── CERTIFICATE GENERATION & PREVIEW MODAL ─── */}
      {showCertModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0, 0, 0, 0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
            padding: "20px",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowCertModal(false)}
        >
          <div
            style={{
              maxWidth: certData ? "850px" : "540px",
              width: "100%",
              maxHeight: "92vh",
              overflowY: "auto",
              borderRadius: "8px",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {certData ? (
              <CertificateView
                data={certData}
                onClose={() => {
                  setCertData(null);
                  setShowCertModal(false);
                }}
              />
            ) : (
              <div className="card" style={{ padding: "24px" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "16px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                    <Award size={18} color="#818cf8" />
                    <h3 className="card-title" style={{ margin: 0, fontSize: "16px" }}>Generate Certificate</h3>
                  </div>
                  <button
                    type="button"
                    className="btn btn-secondary btn-sm"
                    onClick={() => setShowCertModal(false)}
                    style={{ padding: "4px" }}
                  >
                    <X size={16} />
                  </button>
                </div>

                <p style={{ fontSize: "13px", color: "var(--text-secondary)", marginBottom: "16px" }}>
                  Select the certificate type and fill the required details for <strong>{student.fullName}</strong>.
                </p>

                {certError && (
                  <div className="alert alert-error" style={{ marginBottom: "16px" }}>
                    <AlertCircle size={15} />
                    <span>{certError}</span>
                  </div>
                )}

                <form onSubmit={handleGenerateCertificate} style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
                  <div className="form-group">
                    <label className="form-label">Certificate Type *</label>
                    <select
                      className="form-select"
                      value={certType}
                      onChange={(e) => setCertType(e.target.value as any)}
                    >
                      <option value="BONAFIDE">Bonafide Certificate</option>
                      <option value="TC">Transfer Certificate (TC - Persisted in TC Register)</option>
                      <option value="CHARACTER">Character Certificate</option>
                    </select>
                  </div>

                  {certType === "BONAFIDE" && (
                    <div className="form-group">
                      <label className="form-label">Purpose of Certificate</label>
                      <input
                        type="text"
                        className="form-input"
                        placeholder="e.g. Passport Application / Bank Account / Higher Studies"
                        value={certPurpose}
                        onChange={(e) => setCertPurpose(e.target.value)}
                      />
                    </div>
                  )}

                  {certType === "TC" && (
                    <>
                      <div className="form-group">
                        <label className="form-label">TC Certificate Number *</label>
                        <input
                          type="text"
                          className="form-input"
                          value={certTcNumber}
                          onChange={(e) => setCertTcNumber(e.target.value)}
                          required
                        />
                      </div>
                      <div className="form-group">
                        <label className="form-label">Reason for Leaving School *</label>
                        <input
                          type="text"
                          className="form-input"
                          placeholder="e.g. Relocation to another city / Course Completion"
                          value={certReason}
                          onChange={(e) => setCertReason(e.target.value)}
                          required
                        />
                      </div>
                      <div className="form-row">
                        <div className="form-group">
                          <label className="form-label">Last Attendance Date</label>
                          <input
                            type="date"
                            className="form-input"
                            value={certLastDate}
                            onChange={(e) => setCertLastDate(e.target.value)}
                          />
                        </div>
                        <div className="form-group">
                          <label className="form-label">Conduct &amp; Behavior</label>
                          <select
                            className="form-select"
                            value={certConduct}
                            onChange={(e) => setCertConduct(e.target.value)}
                          >
                            <option value="Exemplary">Exemplary</option>
                            <option value="Good">Good</option>
                            <option value="Satisfactory">Satisfactory</option>
                          </select>
                        </div>
                      </div>
                    </>
                  )}

                  {certType === "CHARACTER" && (
                    <div className="form-group">
                      <label className="form-label">General Conduct Remark</label>
                      <select
                        className="form-select"
                        value={certConduct}
                        onChange={(e) => setCertConduct(e.target.value)}
                      >
                        <option value="Exemplary">Exemplary</option>
                        <option value="Good">Good</option>
                        <option value="Satisfactory">Satisfactory</option>
                      </select>
                    </div>
                  )}

                  <div className="form-group">
                    <label className="form-label">Date of Issue</label>
                    <input
                      type="date"
                      className="form-input"
                      value={certIssueDate}
                      onChange={(e) => setCertIssueDate(e.target.value)}
                    />
                  </div>

                  <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "10px" }}>
                    <button
                      type="button"
                      className="btn btn-secondary"
                      onClick={() => setShowCertModal(false)}
                      disabled={generatingCert}
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      className="btn btn-primary"
                      disabled={generatingCert}
                      style={{ gap: "6px" }}
                    >
                      {generatingCert ? (
                        <>
                          <Sparkles size={14} className="animate-spin" />
                          <span>Generating...</span>
                        </>
                      ) : (
                        <>
                          <Award size={14} />
                          <span>Generate &amp; Preview</span>
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ─── RECORD PAYMENT MODAL (Admin & Accountant) ─── */}
      {showPaymentModal && targetInvoice && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0, 0, 0, 0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
            padding: "20px",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowPaymentModal(false)}
        >
          <div
            className="card"
            style={{ maxWidth: "480px", width: "100%", padding: "24px" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "16px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <CreditCard size={18} color="#34d399" />
                <h3 className="card-title" style={{ margin: 0, fontSize: "16px" }}>Record Fee Payment</h3>
              </div>
              <button
                type="button"
                className="btn btn-secondary btn-sm"
                onClick={() => setShowPaymentModal(false)}
                style={{ padding: "4px" }}
              >
                <X size={16} />
              </button>
            </div>

            <div
              style={{
                padding: "12px",
                background: "var(--bg-surface)",
                borderRadius: "var(--radius-sm)",
                border: "1px solid var(--border-subtle)",
                marginBottom: "16px",
                fontSize: "13px",
              }}
            >
              <div><strong>Fee Item:</strong> {targetInvoice.feeStructure.name}</div>
              <div style={{ marginTop: "4px", color: "var(--text-muted)" }}>
                Total Invoiced: ₹{targetInvoice.amountDue} | Due: {formatDate(targetInvoice.dueDate)}
              </div>
            </div>

            {paymentError && (
              <div className="alert alert-error" style={{ marginBottom: "16px" }}>
                <AlertCircle size={16} />
                <span>{paymentError}</span>
              </div>
            )}

            <form onSubmit={handleRecordPayment} style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
              <div className="form-group">
                <label className="form-label">
                  Payment Amount (₹) <span style={{ color: "var(--danger)" }}>*</span>
                </label>
                <input
                  className="form-input"
                  type="number"
                  min="1"
                  step="0.01"
                  value={paymentAmount}
                  onChange={(e) => setPaymentAmount(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Payment Method</label>
                <select
                  className="form-select"
                  value={paymentMethod}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                >
                  <option value="CASH">Cash</option>
                  <option value="ONLINE">Online / UPI / NetBanking</option>
                  <option value="CHEQUE">Cheque / Demand Draft</option>
                  <option value="BANK_TRANSFER">Bank Transfer (NEFT/RTGS)</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">
                  Receipt Number <span style={{ color: "var(--danger)" }}>*</span>
                </label>
                <input
                  className="form-input"
                  type="text"
                  value={paymentReceiptNumber}
                  onChange={(e) => setPaymentReceiptNumber(e.target.value)}
                  required
                />
              </div>

              <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "8px" }}>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowPaymentModal(false)}
                  disabled={recordingPayment}
                >
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary" disabled={recordingPayment} style={{ gap: "6px" }}>
                  {recordingPayment ? <Sparkles size={14} className="animate-spin" /> : <CreditCard size={14} />}
                  <span>{recordingPayment ? "Recording..." : "Record Payment & Generate Receipt"}</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  ArrowLeft,
  User,
  MapPin,
  Users,
  BookOpen,
  HeartPulse,
  Receipt,
  AlertCircle,
  Sparkles,
  CheckCircle2,
  Calendar,
  Camera,
  Upload,
  Trash2,
} from "lucide-react";

export default function NewStudentPage() {
  const router = useRouter();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  // Student Photo (Optional)
  const [photoUrl, setPhotoUrl] = useState("");
  const [photoUploading, setPhotoUploading] = useState(false);
  const [photoError, setPhotoError] = useState("");

  // Student Details
  const [fullName, setFullName] = useState("");
  const [rollNumber, setRollNumber] = useState("");
  const [dob, setDob] = useState("");
  const [gender, setGender] = useState("");
  const [bloodGroup, setBloodGroup] = useState("");
  const [aadharNumber, setAadharNumber] = useState("");
  const [category, setCategory] = useState("");

  // Address
  const [currentAddress, setCurrentAddress] = useState("");
  const [sameAsCurrent, setSameAsCurrent] = useState(false);
  const [permanentAddress, setPermanentAddress] = useState("");

  // Parent & Guardian Details
  const [fatherName, setFatherName] = useState("");
  const [fatherOccupation, setFatherOccupation] = useState("");
  const [fatherPhone, setFatherPhone] = useState("");

  const [motherName, setMotherName] = useState("");
  const [motherOccupation, setMotherOccupation] = useState("");
  const [motherPhone, setMotherPhone] = useState("");

  const [guardianName, setGuardianName] = useState("");
  const [guardianRelation, setGuardianRelation] = useState("");
  const [guardianPhone, setGuardianPhone] = useState("");

  // Previous School
  const [previousSchoolName, setPreviousSchoolName] = useState("");
  const [previousClass, setPreviousClass] = useState("");
  const [transferCertificateNumber, setTransferCertificateNumber] = useState("");

  // Emergency & Medical
  const [emergencyContactName, setEmergencyContactName] = useState("");
  const [emergencyContactPhone, setEmergencyContactPhone] = useState("");
  const [medicalConditions, setMedicalConditions] = useState("");

  // Fee Details (Optional)
  const [totalFees, setTotalFees] = useState("");
  const [amountPaidNow, setAmountPaidNow] = useState("0");
  const [dueDate, setDueDate] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("CASH");

  // Computed Remaining Fees
  const totalFeesNum = Math.max(0, parseFloat(totalFees) || 0);
  const amountPaidNum = Math.max(0, parseFloat(amountPaidNow) || 0);
  const remainingFeesNum = Math.max(0, totalFeesNum - amountPaidNum);

  const handleSameAddressChange = (checked: boolean) => {
    setSameAsCurrent(checked);
    if (checked) {
      setPermanentAddress(currentAddress);
    }
  };

  const handleCurrentAddressChange = (value: string) => {
    setCurrentAddress(value);
    if (sameAsCurrent) {
      setPermanentAddress(value);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    setPhotoError("");
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      setPhotoError("Image size exceeds 5MB limit. Please upload a smaller image.");
      return;
    }

    const validTypes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    if (!validTypes.includes(file.type.toLowerCase())) {
      setPhotoError("Invalid image format. Allowed formats: JPG, PNG, WebP.");
      return;
    }

    setPhotoUploading(true);
    const formData = new FormData();
    formData.append("photo", file);

    try {
      const res = await fetch("/api/upload/student-photo", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      setPhotoUploading(false);

      if (res.ok) {
        setPhotoUrl(data.url);
      } else {
        setPhotoError(data.error || "Failed to upload photo");
      }
    } catch (err: any) {
      setPhotoUploading(false);
      setPhotoError(err.message || "Failed to upload photo");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!fullName.trim()) {
      setError("Full name is required");
      return;
    }
    if (!dob) {
      setError("Date of birth is required");
      return;
    }
    if (totalFees && Number(totalFees) < 0) {
      setError("Total fees cannot be negative");
      return;
    }
    if (amountPaidNow && Number(amountPaidNow) < 0) {
      setError("Amount paid now cannot be negative");
      return;
    }
    if (totalFees && amountPaidNow && Number(amountPaidNow) > Number(totalFees)) {
      setError("Amount paid now cannot exceed total fees");
      return;
    }
    if (totalFeesNum > 0 && remainingFeesNum > 0 && !dueDate) {
      setError("Please select a due date for the remaining fees balance");
      return;
    }

    setSubmitting(true);

    try {
      const res = await fetch("/api/students", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fullName: fullName.trim().toUpperCase(),
          rollNumber: rollNumber?.trim() || undefined,
          dob,
          photoUrl: photoUrl || undefined,
          gender: gender || undefined,
          bloodGroup: bloodGroup || undefined,
          aadharNumber: aadharNumber.trim() || undefined,
          category: category || undefined,
          currentAddress: currentAddress.trim() || undefined,
          permanentAddress: (sameAsCurrent ? currentAddress : permanentAddress).trim() || undefined,
          previousSchoolName: previousSchoolName.trim() || undefined,
          previousClass: previousClass.trim() || undefined,
          transferCertificateNumber: transferCertificateNumber.trim() || undefined,
          fatherName: fatherName.trim() || undefined,
          fatherOccupation: fatherOccupation.trim() || undefined,
          fatherPhone: fatherPhone.trim() || undefined,
          motherName: motherName.trim() || undefined,
          motherOccupation: motherOccupation.trim() || undefined,
          motherPhone: motherPhone.trim() || undefined,
          guardianName: guardianName.trim() || undefined,
          guardianRelation: guardianRelation.trim() || undefined,
          guardianPhone: guardianPhone.trim() || undefined,
          emergencyContactName: emergencyContactName.trim() || undefined,
          emergencyContactPhone: emergencyContactPhone.trim() || undefined,
          medicalConditions: medicalConditions.trim() || undefined,
          totalFees: totalFees.trim() ? totalFees.trim() : undefined,
          amountPaidNow: amountPaidNow.trim() ? amountPaidNow.trim() : undefined,
          dueDate: remainingFeesNum > 0 && dueDate ? dueDate : undefined,
          paymentMethod: Number(amountPaidNow) > 0 ? paymentMethod : undefined,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        setError(data.error || "Failed to complete student admission");
        setSubmitting(false);
        return;
      }

      router.push("/admin/students");
      router.refresh();
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred");
      setSubmitting(false);
    }
  };

  return (
    <div className="office-page-container" style={{ maxWidth: "900px" }}>
      {/* Back Link */}
      <div style={{ marginBottom: "16px" }}>
        <Link
          href="/admin/students"
          className="office-btn office-btn-secondary office-btn-sm"
        >
          <ArrowLeft size={14} />
          <span>Back to Students</span>
        </Link>
      </div>

      {/* Header */}
      <div className="office-header">
        <div>
          <h1 className="office-title">New Student Admission</h1>
          <p className="office-subtitle">
            Fill in the student details to register a new enrollment. Class and section can be allocated now or later.
          </p>
        </div>
      </div>

      {error && (
        <div
          style={{
            background: "#fef2f2",
            border: "1px solid #fecaca",
            color: "#991b1b",
            borderRadius: "8px",
            padding: "12px 16px",
            marginBottom: "20px",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "13.5px",
            fontWeight: 500,
          }}
        >
          <AlertCircle size={18} />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit}>
        {/* ─── 1. Student Personal Details ─── */}
        <div className="office-card">
          <div className="office-card-header">
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div
                style={{
                  width: "32px",
                  height: "32px",
                  borderRadius: "6px",
                  background: "#eff6ff",
                  color: "#1e3a8a",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <User size={18} />
              </div>
              <h3 className="office-card-title">1. Student Information</h3>
            </div>
          </div>

          {/* Photo Upload */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "18px",
              padding: "16px",
              background: "#f8fafc",
              border: "1px dashed #cbd5e1",
              borderRadius: "8px",
              marginBottom: "20px",
              flexWrap: "wrap",
            }}
          >
            <div
              style={{
                width: "70px",
                height: "70px",
                borderRadius: "8px",
                background: "#ffffff",
                border: "1px solid #e2e8f0",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                color: "#94a3b8",
                flexShrink: 0,
              }}
            >
              {photoUrl ? (
                <img src={photoUrl} alt="Student" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <Camera size={26} />
              )}
            </div>
            <div style={{ flex: 1, minWidth: "220px" }}>
              <div style={{ fontSize: "13.5px", fontWeight: 600, color: "#0f172a" }}>
                Student Photo <span style={{ fontSize: "11px", color: "#64748b", fontWeight: 400 }}>(Optional)</span>
              </div>
              <p style={{ fontSize: "12px", color: "#64748b", margin: "4px 0 10px 0" }}>
                Clear portrait photo in JPG, PNG or WebP format (max 5MB).
              </p>
              <div style={{ display: "flex", alignItems: "center", gap: "10px", flexWrap: "wrap" }}>
                <label className="office-btn office-btn-secondary office-btn-sm" style={{ cursor: "pointer" }}>
                  <Upload size={13} />
                  <span>{photoUploading ? "Uploading..." : photoUrl ? "Change Photo" : "Upload Photo"}</span>
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    onChange={handlePhotoUpload}
                    style={{ display: "none" }}
                    disabled={photoUploading}
                  />
                </label>
                {photoUrl && (
                  <button
                    type="button"
                    onClick={() => setPhotoUrl("")}
                    className="office-btn office-btn-secondary office-btn-sm"
                    style={{ color: "#dc2626" }}
                  >
                    <Trash2 size={13} />
                    <span>Remove</span>
                  </button>
                )}
              </div>
              {photoError && <div style={{ fontSize: "12px", color: "#dc2626", marginTop: "6px" }}>{photoError}</div>}
            </div>
          </div>

          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">
                Full Name <span style={{ color: "#dc2626" }}>*</span>
              </label>
              <input
                type="text"
                placeholder="e.g. AARAV SHARMA"
                value={fullName}
                onChange={(e) => setFullName(e.target.value.toUpperCase())}
                className="office-input"
                style={{ width: "100%" }}
                required
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">
                Date of Birth <span style={{ color: "#dc2626" }}>*</span>
              </label>
              <input
                type="date"
                value={dob}
                onChange={(e) => setDob(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
                required
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Roll Number</label>
              <input
                type="text"
                placeholder="e.g. 01, 15, A-10"
                value={rollNumber}
                onChange={(e) => setRollNumber(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
          </div>

          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">Gender</label>
              <select
                className="office-select"
                value={gender}
                onChange={(e) => setGender(e.target.value)}
                style={{ width: "100%" }}
              >
                <option value="">Select Gender</option>
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Blood Group</label>
              <select
                className="office-select"
                value={bloodGroup}
                onChange={(e) => setBloodGroup(e.target.value)}
                style={{ width: "100%" }}
              >
                <option value="">Select Blood Group</option>
                <option value="A+">A+</option>
                <option value="A-">A-</option>
                <option value="B+">B+</option>
                <option value="B-">B-</option>
                <option value="O+">O+</option>
                <option value="O-">O-</option>
                <option value="AB+">AB+</option>
                <option value="AB-">AB-</option>
              </select>
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Category</label>
              <select
                className="office-select"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                style={{ width: "100%" }}
              >
                <option value="">Select Category</option>
                <option value="General">General</option>
                <option value="OBC">OBC</option>
                <option value="SC">SC</option>
                <option value="ST">ST</option>
                <option value="EWS">EWS</option>
              </select>
            </div>
          </div>

          <div className="office-form-group">
            <label className="office-form-label">Aadhar / Government Identity Number</label>
            <input
              type="text"
              placeholder="12-digit UIDAI Aadhar number"
              value={aadharNumber}
              onChange={(e) => setAadharNumber(e.target.value)}
              className="office-input"
              style={{ width: "100%", maxWidth: "340px" }}
            />
          </div>
        </div>

        {/* ─── 2. Address & Residence ─── */}
        <div className="office-card">
          <div className="office-card-header">
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div
                style={{
                  width: "32px",
                  height: "32px",
                  borderRadius: "6px",
                  background: "#eff6ff",
                  color: "#1e3a8a",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <MapPin size={18} />
              </div>
              <h3 className="office-card-title">2. Residential Address</h3>
            </div>
          </div>

          <div className="office-form-group">
            <label className="office-form-label">Current Address</label>
            <textarea
              className="office-input"
              style={{ width: "100%", height: "70px", resize: "vertical" }}
              placeholder="Street name, apartment, locality, city, pincode"
              value={currentAddress}
              onChange={(e) => handleCurrentAddressChange(e.target.value)}
            />
          </div>

          <div style={{ marginBottom: "14px", display: "flex", alignItems: "center", gap: "8px" }}>
            <input
              type="checkbox"
              id="sameAddress"
              checked={sameAsCurrent}
              onChange={(e) => handleSameAddressChange(e.target.checked)}
              style={{ width: "16px", height: "16px", cursor: "pointer" }}
            />
            <label htmlFor="sameAddress" style={{ fontSize: "13px", color: "#334155", cursor: "pointer" }}>
              Permanent address is same as current address
            </label>
          </div>

          {!sameAsCurrent && (
            <div className="office-form-group">
              <label className="office-form-label">Permanent Address</label>
              <textarea
                className="office-input"
                style={{ width: "100%", height: "70px", resize: "vertical" }}
                placeholder="Native place or permanent residence address"
                value={permanentAddress}
                onChange={(e) => setPermanentAddress(e.target.value)}
              />
            </div>
          )}
        </div>

        {/* ─── 3. Parents & Guardians ─── */}
        <div className="office-card">
          <div className="office-card-header">
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div
                style={{
                  width: "32px",
                  height: "32px",
                  borderRadius: "6px",
                  background: "#eff6ff",
                  color: "#1e3a8a",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Users size={18} />
              </div>
              <h3 className="office-card-title">3. Parent & Guardian Details</h3>
            </div>
          </div>

          <div style={{ fontSize: "13px", fontWeight: 700, color: "#1e3a8a", marginBottom: "10px" }}>
            Father&apos;s Information
          </div>
          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">Father&apos;s Full Name</label>
              <input
                type="text"
                placeholder="Father full name"
                value={fatherName}
                onChange={(e) => setFatherName(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Occupation</label>
              <input
                type="text"
                placeholder="e.g. Civil Engineer, Business"
                value={fatherOccupation}
                onChange={(e) => setFatherOccupation(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Phone Number</label>
              <input
                type="tel"
                placeholder="10-digit mobile number"
                value={fatherPhone}
                onChange={(e) => setFatherPhone(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
          </div>

          <div style={{ fontSize: "13px", fontWeight: 700, color: "#1e3a8a", margin: "14px 0 10px 0" }}>
            Mother&apos;s Information
          </div>
          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">Mother&apos;s Full Name</label>
              <input
                type="text"
                placeholder="Mother full name"
                value={motherName}
                onChange={(e) => setMotherName(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Occupation</label>
              <input
                type="text"
                placeholder="e.g. Teacher, Homemaker"
                value={motherOccupation}
                onChange={(e) => setMotherOccupation(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Phone Number</label>
              <input
                type="tel"
                placeholder="10-digit mobile number"
                value={motherPhone}
                onChange={(e) => setMotherPhone(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
          </div>
        </div>

        {/* ─── 4. Previous School & Medical ─── */}
        <div className="office-card">
          <div className="office-card-header">
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div
                style={{
                  width: "32px",
                  height: "32px",
                  borderRadius: "6px",
                  background: "#eff6ff",
                  color: "#1e3a8a",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <BookOpen size={18} />
              </div>
              <h3 className="office-card-title">4. Previous School & Health Information</h3>
            </div>
          </div>

          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">Previous School Name</label>
              <input
                type="text"
                placeholder="Previous institution attended"
                value={previousSchoolName}
                onChange={(e) => setPreviousSchoolName(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Previous Class</label>
              <input
                type="text"
                placeholder="e.g. Grade 4"
                value={previousClass}
                onChange={(e) => setPreviousClass(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">TC Certificate Number</label>
              <input
                type="text"
                placeholder="Transfer certificate reference"
                value={transferCertificateNumber}
                onChange={(e) => setTransferCertificateNumber(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
          </div>

          <div className="office-form-grid-2">
            <div className="office-form-group">
              <label className="office-form-label">Emergency Contact Name & Phone</label>
              <input
                type="text"
                placeholder="Emergency contact person and contact number"
                value={emergencyContactName}
                onChange={(e) => setEmergencyContactName(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Medical Conditions / Allergies</label>
              <input
                type="text"
                placeholder="None or list allergies / special care instructions"
                value={medicalConditions}
                onChange={(e) => setMedicalConditions(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
          </div>
        </div>

        {/* ─── 5. Admission Fee Schedule (Optional) ─── */}
        <div className="office-card">
          <div className="office-card-header">
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div
                style={{
                  width: "32px",
                  height: "32px",
                  borderRadius: "6px",
                  background: "#eff6ff",
                  color: "#1e3a8a",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Receipt size={18} />
              </div>
              <div>
                <h3 className="office-card-title">5. Admission Fee Schedule</h3>
                <span style={{ fontSize: "12px", color: "#64748b" }}>
                  Optional: Generate initial fee invoice and record admission fee payment
                </span>
              </div>
            </div>
          </div>

          <div className="office-form-grid-3">
            <div className="office-form-group">
              <label className="office-form-label">Total Annual / Admission Fee (₹)</label>
              <input
                type="number"
                placeholder="e.g. 45000"
                value={totalFees}
                onChange={(e) => setTotalFees(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Initial Amount Paid Today (₹)</label>
              <input
                type="number"
                placeholder="e.g. 15000 (0 if unpaid)"
                value={amountPaidNow}
                onChange={(e) => setAmountPaidNow(e.target.value)}
                className="office-input"
                style={{ width: "100%" }}
              />
            </div>
            <div className="office-form-group">
              <label className="office-form-label">Payment Method</label>
              <select
                className="office-select"
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
                style={{ width: "100%" }}
              >
                <option value="CASH">Cash Payment</option>
                <option value="UPI">UPI / QR Code</option>
                <option value="BANK_TRANSFER">Bank Transfer / NEFT</option>
                <option value="CHEQUE">Cheque</option>
                <option value="CARD">Debit / Credit Card</option>
              </select>
            </div>
          </div>

          {remainingFeesNum > 0 && totalFeesNum > 0 && (
            <div className="office-form-grid-2" style={{ marginTop: "10px" }}>
              <div
                style={{
                  background: "#fffbeb",
                  border: "1px solid #fde68a",
                  borderRadius: "8px",
                  padding: "12px 16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                }}
              >
                <span style={{ fontSize: "13px", color: "#92400e", fontWeight: 600 }}>
                  Remaining Balance Due:
                </span>
                <span style={{ fontSize: "16px", color: "#b45309", fontWeight: 700 }}>
                  ₹{remainingFeesNum.toLocaleString()}
                </span>
              </div>

              <div className="office-form-group">
                <label className="office-form-label">
                  Balance Due Date <span style={{ color: "#dc2626" }}>*</span>
                </label>
                <input
                  type="date"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  className="office-input"
                  style={{ width: "100%" }}
                />
              </div>
            </div>
          )}
        </div>

        {/* ─── Submit Actions Bar ─── */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            gap: "12px",
            padding: "20px 0",
          }}
        >
          <Link href="/admin/students" className="office-btn office-btn-secondary">
            Cancel
          </Link>
          <button type="submit" disabled={submitting} className="office-btn office-btn-primary">
            {submitting ? (
              <>
                <Sparkles size={16} className="animate-spin" />
                <span>Enrolling Student...</span>
              </>
            ) : (
              <>
                <CheckCircle2 size={16} />
                <span>Complete Student Admission</span>
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

