"use client";

import { Suspense, useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import {
  Receipt,
  CreditCard,
  Sparkles,
  CheckCircle2,
  Clock,
  Printer,
  ShieldCheck,
  X,
  AlertCircle,
} from "lucide-react";
import Link from "next/link";
import { useToast } from "@/components/ui/Toast";

interface Invoice {
  id: string;
  studentId: string;
  amountDue: string;
  discountAmount: string;
  dueDate: string;
  status: "UNPAID" | "PARTIALLY_PAID" | "PAID" | "OVERDUE" | "WAIVED";
  createdAt: string;
  feeStructure: {
    name: string;
    amount: string;
    frequency: string;
    academicYear: string;
  };
  payments: Array<{
    id: string;
    amount: string;
    method: string;
    receiptNumber: string;
    paidAt: string;
  }>;
}

interface Student {
  id: string;
  fullName: string;
  admissionNo: string;
  section?: { name: string; class: { name: string } };
}

function FeesContent() {
  const searchParams = useSearchParams();
  const initialStudentId = searchParams.get("studentId") || "";
  const { addToast } = useToast();

  const [students, setStudents] = useState<Student[]>([]);
  const [selectedStudentId, setSelectedStudentId] = useState<string>(initialStudentId);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState(true);

  // Payment Modal state
  const [payingInvoice, setPayingInvoice] = useState<Invoice | null>(null);
  const [payAmount, setPayAmount] = useState<number>(0);
  const [isProcessing, setIsProcessing] = useState(false);

  const fetchInvoices = (studentId: string) => {
    setLoading(true);
    fetch(`/api/parent/students/${studentId}/invoices`)
      .then((r) => r.json())
      .then((data) => {
        setInvoices(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetch("/api/parent/students")
      .then((r) => r.json())
      .then((data: Student[]) => {
        if (Array.isArray(data)) {
          setStudents(data);
          if (!selectedStudentId && data.length > 0) {
            setSelectedStudentId(data[0].id);
          }
        }
      });
  }, [selectedStudentId]);

  useEffect(() => {
    if (!selectedStudentId) {
      setLoading(false);
      return;
    }
    fetchInvoices(selectedStudentId);
  }, [selectedStudentId]);

  const selectedStudent = students.find((s) => s.id === selectedStudentId);

  // Financial summary
  const totalInvoiced = invoices.reduce((sum, inv) => sum + parseFloat(inv.amountDue), 0);
  const totalPaid = invoices.reduce(
    (sum, inv) =>
      sum + inv.payments.reduce((pSum, p) => pSum + parseFloat(p.amount), 0),
    0
  );
  const totalOutstanding = Math.max(0, totalInvoiced - totalPaid);

  const initiatePayment = (inv: Invoice) => {
    const paidForThisInv = inv.payments.reduce((s, p) => s + parseFloat(p.amount), 0);
    const balance = Math.max(0, parseFloat(inv.amountDue) - paidForThisInv);
    setPayingInvoice(inv);
    setPayAmount(balance);
  };

  const loadRazorpayScript = (): Promise<boolean> => {
    return new Promise((resolve) => {
      if (typeof window !== "undefined" && (window as any).Razorpay) {
        resolve(true);
        return;
      }
      const script = document.createElement("script");
      script.src = "https://checkout.razorpay.com/v1/checkout.js";
      script.onload = () => resolve(true);
      script.onerror = () => resolve(false);
      document.body.appendChild(script);
    });
  };

  const handleProcessPayment = async () => {
    if (!payingInvoice || payAmount <= 0) return;
    setIsProcessing(true);

    try {
      // 1. Create Razorpay order on server
      const orderRes = await fetch("/api/payments/razorpay/create-order", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          invoiceId: payingInvoice.id,
          amount: payAmount,
        }),
      });

      const orderData = await orderRes.json();
      if (!orderRes.ok) {
        throw new Error(orderData.error || "Failed to create payment order");
      }

      // Sandbox fallback if server has mock mode
      if (orderData.isMock) {
        const mockPaymentId = `pay_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
        const mockSignature = `mock_sig_${mockPaymentId}`;

        const verifyRes = await fetch("/api/payments/razorpay/verify", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            orderId: orderData.orderId,
            paymentId: mockPaymentId,
            signature: mockSignature,
            invoiceId: payingInvoice.id,
            amount: payAmount,
          }),
        });

        const verifyData = await verifyRes.json();
        if (!verifyRes.ok) {
          throw new Error(verifyData.error || "Payment verification failed");
        }

        addToast("info", "Development Mode: Sandbox payment recorded successfully.");
        setPayingInvoice(null);
        if (selectedStudentId) {
          fetchInvoices(selectedStudentId);
        }
        setIsProcessing(false);
        return;
      }

      // 2. Load official Razorpay Checkout SDK
      const scriptLoaded = await loadRazorpayScript();
      if (!scriptLoaded) {
        throw new Error("Unable to load Razorpay payment gateway. Please check your internet connection.");
      }

      const options = {
        key: orderData.keyId,
        amount: orderData.amount,
        currency: orderData.currency || "INR",
        name: "School ERP",
        description: `Fee Payment - ${payingInvoice.feeStructure.name}`,
        order_id: orderData.orderId,
        handler: async function (response: {
          razorpay_payment_id: string;
          razorpay_order_id: string;
          razorpay_signature: string;
        }) {
          try {
            setIsProcessing(true);
            const verifyRes = await fetch("/api/payments/razorpay/verify", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                orderId: response.razorpay_order_id,
                paymentId: response.razorpay_payment_id,
                signature: response.razorpay_signature,
                invoiceId: payingInvoice.id,
                amount: payAmount,
              }),
            });

            const verifyData = await verifyRes.json();
            if (!verifyRes.ok) {
              throw new Error(verifyData.error || "Payment signature verification failed");
            }

            addToast("success", `Payment of ₹${payAmount.toLocaleString("en-IN")} successful!`);
            setPayingInvoice(null);
            if (selectedStudentId) {
              fetchInvoices(selectedStudentId);
            }
          } catch (verifyErr: any) {
            addToast("error", verifyErr.message || "Payment verification failed");
          } finally {
            setIsProcessing(false);
          }
        },
        prefill: {
          name: selectedStudent?.fullName || "",
        },
        theme: {
          color: "#1e3a8a",
        },
        modal: {
          ondismiss: function () {
            setIsProcessing(false);
          },
        },
      };

