      rzp.on("payment.failed", function (response: any) {
        setIsProcessing(false);
        addToast("error", response.error?.description || "Payment failed");
      });
      rzp.open();
    } catch (err: any) {
      addToast("error", err.message || "Payment transaction failed");
      setIsProcessing(false);
    }
  };

  return (
