"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import {
  GraduationCap,
  ArrowRight,
  Sparkles,
  User,
  Calendar,
  MapPin,
  HeartHandshake,
  CheckCircle2,
  Receipt,
  Award,
  UserPlus,
  Clock,
  AlertCircle,
  X,
  School,
} from "lucide-react";

type StudentData = {
  id: string;
  fullName: string;
  admissionNo: string;
  rollNumber?: string;
  academicYear: string;
  relationship: string;
  gender?: string;
  bloodGroup?: string;
  dob?: string;
  photoUrl?: string;
  currentAddress?: string;
  fatherName?: string;
  motherName?: string;
  emergencyContactPhone?: string;
  section?: {
    name: string;
    class: { name: string };
    classTeacher?: { fullName: string };
  } | null;
};

type LinkRequest = {
  id: string;
  admissionNo: string;
  relationship: string;
  status: "PENDING" | "APPROVED" | "REJECTED";
  rejectionReason?: string;
  createdAt: string;
  school: { id: string; name: string };
  student?: { fullName: string };
};

export default function ParentStudentsPage() {
  const [students, setStudents] = useState<StudentData[]>([]);
  const [linkRequests, setLinkRequests] = useState<LinkRequest[]>([]);
  const [schools, setSchools] = useState<{ id: string; name: string }[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [notification, setNotification] = useState<{ type: "success" | "error"; text: string } | null>(null);

  const [formData, setFormData] = useState({
    schoolId: "",
    admissionNo: "",
    studentDob: "",
    relationship: "Father",
    notes: "",
  });

  const loadData = async () => {
    try {
      setLoading(true);
      const [studentsRes, reqsRes, schoolsRes] = await Promise.all([
        fetch("/api/parent/students"),
        fetch("/api/parent/link-requests"),
        fetch("/api/schools"),
      ]);

      if (studentsRes.ok) {
        const data = await studentsRes.json();
        setStudents(Array.isArray(data) ? data : []);
      }
      if (reqsRes.ok) {
        const data = await reqsRes.json();
        setLinkRequests(data.requests || []);
      }
      if (schoolsRes.ok) {
        const schoolsData = await schoolsRes.json();
        setSchools(Array.isArray(schoolsData) ? schoolsData : []);
        if (schoolsData.length > 0 && !formData.schoolId) {
          setFormData((prev) => ({ ...prev, schoolId: schoolsData[0].id }));
        }
      }
    } catch (err: any) {
      console.error("Error loading parent students:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleLinkSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification(null);
    setSubmitting(true);

    try {
      const res = await fetch("/api/parent/link-requests", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to submit student link request");
      }

      setNotification({
        type: "success",
        text: "Student link request submitted successfully. The school administration has been notified.",
      });
      setIsModalOpen(false);
      setFormData({
        schoolId: schools[0]?.id || "",
        admissionNo: "",
        studentDob: "",
        relationship: "Father",
        notes: "",
      });
      await loadData();
    } catch (err: any) {
      setNotification({ type: "error", text: err.message || "Failed to submit request" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="office-page-container" style={{ padding: "60px 20px", textAlign: "center" }}>
        <Sparkles size={22} className="animate-spin" color="#1e3a8a" style={{ margin: "0 auto 8px" }} />
        <div style={{ color: "#64748b", fontSize: "14px" }}>Loading children&apos;s profiles...</div>
      </div>
    );
  }

  const pendingRequests = linkRequests.filter((r) => r.status === "PENDING");

  return (
    <div className="office-page-container">
      {/* ─── Header ─── */}
      <div className="office-header">
        <div>
          <h1 className="office-title">My Children</h1>
          <p className="office-subtitle">
            Enrolled student profiles, classroom sections, and quick links to academic records
          </p>
        </div>

        <button
          onClick={() => setIsModalOpen(true)}
          className="btn btn-primary"
          style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
        >
          <UserPlus size={16} />
          <span>Link Another Child</span>
        </button>
      </div>

      {notification && (
        <div
          style={{
            padding: "12px 16px",
            borderRadius: "8px",
            marginBottom: "20px",
            fontSize: "13.5px",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            backgroundColor: notification.type === "success" ? "#ecfdf5" : "#fef2f2",
            border: `1px solid ${notification.type === "success" ? "#a7f3d0" : "#fecaca"}`,
            color: notification.type === "success" ? "#065f46" : "#b91c1c",
          }}
        >
          {notification.type === "success" ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span>{notification.text}</span>
        </div>
      )}

      {/* ─── Pending Verification Requests Banner ─── */}
      {pendingRequests.length > 0 && (
        <div
          className="office-card"
          style={{
            marginBottom: "24px",
            padding: "16px 20px",
            backgroundColor: "#fffbeb",
            border: "1px solid #fcd34d",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "8px" }}>
            <Clock size={16} color="#d97706" />
            <span style={{ fontWeight: 700, fontSize: "13.5px", color: "#92400e" }}>
              Pending School Link Requests ({pendingRequests.length})
            </span>
          </div>
          <p style={{ margin: "0 0 12px 0", fontSize: "12.5px", color: "#78350f" }}>
            The following student connection requests are currently being reviewed by the school office:
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
            {pendingRequests.map((r) => (
              <div
                key={r.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "8px 12px",
                  borderRadius: "6px",
                  backgroundColor: "#fff",
                  border: "1px solid #fef3c7",
                  fontSize: "13px",
                }}
              >
                <div>
                  <span style={{ fontWeight: 600, color: "#0f172a" }}>
                    Admission No: {r.admissionNo}
                  </span>
                  {r.student?.fullName && (
                    <span style={{ color: "#475569" }}> ({r.student.fullName})</span>
                  )}
                  <span style={{ color: "#64748b", fontSize: "12px" }}> • {r.school.name}</span>
                </div>
                <span className="office-pill office-pill-blue">Awaiting Approval</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {students.length === 0 && pendingRequests.length === 0 ? (
        <div className="office-card" style={{ padding: "48px 20px", textAlign: "center" }}>
          <HeartHandshake size={36} color="#94a3b8" style={{ margin: "0 auto 8px" }} />
          <div style={{ fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>No Children Linked Yet</div>
          <p style={{ fontSize: "13px", color: "#64748b", margin: "6px 0 16px 0" }}>
            Link your child&apos;s admission number and school to access report cards, daily attendance, and online fee payments.
          </p>
          <button
            onClick={() => setIsModalOpen(true)}
            className="btn btn-primary"
            style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
          >
            <UserPlus size={16} />
            <span>Link Your Child Now</span>
          </button>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(360px, 1fr))", gap: "20px" }}>
          {students.map((s) => (
            <div key={s.id} className="office-card" style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
              <div style={{ display: "flex", gap: "16px", alignItems: "flex-start" }}>
                <div
                  style={{
                    width: "56px",
                    height: "56px",
                    borderRadius: "50%",
                    background: s.photoUrl ? `url(${s.photoUrl}) center/cover no-repeat` : "#eff6ff",
                    color: "#1e3a8a",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                    border: "2px solid #bfdbfe",
                    fontWeight: 700,
                    fontSize: "18px",
                  }}
                >
                  {!s.photoUrl && s.fullName.charAt(0)}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <h3 style={{ margin: 0, fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>{s.fullName}</h3>
                    <span className="office-pill office-pill-blue">
                      {s.relationship || "Student"}
                    </span>
                  </div>
                  <div style={{ fontSize: "13px", color: "#64748b", marginTop: "2px" }}>
                    Admission: <span style={{ fontWeight: 600, color: "#0f172a" }}>{s.admissionNo}</span>
                    {s.rollNumber && <> • Roll: {s.rollNumber}</>}
                  </div>
                  <div style={{ fontSize: "13px", color: "#1e3a8a", fontWeight: 600, marginTop: "2px" }}>
                    {s.section ? `${s.section.class.name} - ${s.section.name}` : "Not Assigned"}
                  </div>
                </div>
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: "10px",
                  padding: "12px",
                  background: "#f8fafc",
                  borderRadius: "8px",
                  fontSize: "12.5px",
                }}
              >
                <div>
                  <div style={{ color: "#64748b" }}>Academic Year</div>
                  <div style={{ fontWeight: 600, color: "#0f172a" }}>{s.academicYear}</div>
                </div>
                <div>
                  <div style={{ color: "#64748b" }}>Class Teacher</div>
                  <div style={{ fontWeight: 600, color: "#0f172a" }}>
                    {s.section?.classTeacher?.fullName || "Not Assigned"}
                  </div>
                </div>
                {s.dob && (
                  <div>
                    <div style={{ color: "#64748b" }}>Date of Birth</div>
                    <div style={{ fontWeight: 600, color: "#0f172a" }}>
                      {new Date(s.dob).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {s.bloodGroup && (
                  <div>
                    <div style={{ color: "#64748b" }}>Blood Group</div>
                    <div style={{ fontWeight: 600, color: "#0f172a" }}>{s.bloodGroup}</div>
                  </div>
                )}
              </div>

              {/* Navigation Shortcuts */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px", marginTop: "auto" }}>
                <Link
                  href={`/parent/attendance?studentId=${s.id}`}
                  className="btn btn-secondary"
                  style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontSize: "12px" }}
                >
                  <Calendar size={14} />
                  <span>Attendance</span>
                </Link>
                <Link
                  href={`/parent/report-cards?studentId=${s.id}`}
                  className="btn btn-secondary"
                  style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontSize: "12px" }}
                >
                  <Award size={14} />
                  <span>Report Card</span>
                </Link>
                <Link
                  href={`/parent/fees?studentId=${s.id}`}
                  className="btn btn-secondary"
                  style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontSize: "12px" }}
                >
                  <Receipt size={14} />
                  <span>Fee Invoices</span>
                </Link>
                <Link
                  href={`/parent/students/${s.id}`}
                  className="btn btn-primary"
                  style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontSize: "12px" }}
                >
                  <span>Full Profile</span>
                  <ArrowRight size={14} />
                </Link>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ─── Link Request Modal ─── */}
      {isModalOpen && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            backgroundColor: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(4px)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
            padding: "16px",
          }}
        >
          <div
            className="office-card"
            style={{
              width: "100%",
              maxWidth: "480px",
              padding: "24px",
              position: "relative",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <div
                  style={{
                    width: "36px",
                    height: "36px",
                    borderRadius: "8px",
                    backgroundColor: "#eff6ff",
                    color: "#1e3a8a",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <UserPlus size={18} />
                </div>
                <h2 style={{ margin: 0, fontSize: "17px", fontWeight: 700, color: "#0f172a" }}>
                  Link Student to Parent Portal
                </h2>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                style={{ background: "none", border: "none", cursor: "pointer", color: "#94a3b8" }}
              >
                <X size={20} />
              </button>
            </div>

            <p style={{ margin: "0 0 20px 0", fontSize: "13px", color: "#64748b" }}>
              Submit your child&apos;s admission details. The school administrative office will verify and authorize access.
            </p>

            <form onSubmit={handleLinkSubmit} style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
              <div>
                <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                  Select Enrolled School *
                </label>
                <select
                  required
                  className="form-input"
                  value={formData.schoolId}
                  onChange={(e) => setFormData({ ...formData, schoolId: e.target.value })}
                >
                  {schools.map((sch) => (
                    <option key={sch.id} value={sch.id}>
                      {sch.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                  Student Admission Number *
                </label>
                <input
                  type="text"
                  required
                  placeholder="e.g. ADM-2026-0042"
                  className="form-input"
                  value={formData.admissionNo}
                  onChange={(e) => setFormData({ ...formData, admissionNo: e.target.value })}
                />
              </div>

              <div>
                <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                  Student Date of Birth (for verification)
                </label>
                <input
                  type="date"
                  className="form-input"
                  value={formData.studentDob}
                  onChange={(e) => setFormData({ ...formData, studentDob: e.target.value })}
                />
              </div>

              <div>
                <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                  Relationship to Student *
                </label>
                <select
                  className="form-input"
                  value={formData.relationship}
                  onChange={(e) => setFormData({ ...formData, relationship: e.target.value })}
                >
                  <option value="Father">Father</option>
                  <option value="Mother">Mother</option>
                  <option value="Guardian">Legal Guardian</option>
                </select>
              </div>

              <div>
                <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                  Additional Notes (Optional)
                </label>
                <input
                  type="text"
                  placeholder="e.g. Registered with father phone number"
                  className="form-input"
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                />
              </div>

              <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="btn btn-secondary"
                  style={{ flex: 1 }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submitting}
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                >
                  {submitting ? "Submitting..." : "Submit Request"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { BookOpen, CheckCircle2, Sparkles } from "lucide-react";

type Subject = { id: string; name: string };
type Topic = { id: string; topicTitle: string; description: string | null; order: number; isCompleted: boolean; completedDate: string | null };

export default function ParentSyllabusPage() {
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [classId, setClassId] = useState("");
  const [className, setClassName] = useState("");
  const [selectedSubject, setSelectedSubject] = useState("");
  const [topics, setTopics] = useState<Topic[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingTopics, setLoadingTopics] = useState(false);

  useEffect(() => {
    // Get child's class from parent's students
    Promise.all([
      fetch("/api/parent/students").then((r) => r.json()),
      fetch("/api/subjects").then((r) => r.json()),
    ]).then(([students, subs]) => {
      setSubjects(Array.isArray(subs) ? subs : []);
      if (students.length > 0 && students[0].section?.class) {
        setClassId(students[0].section.class.id);
        setClassName(students[0].section.class.name);
      }
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (!classId || !selectedSubject) { setTopics([]); return; }
    setLoadingTopics(true);
    fetch(`/api/syllabus?classId=${classId}&subjectId=${selectedSubject}&academicYear=2026-27`)
      .then((r) => r.json())
      .then((data) => { setTopics(Array.isArray(data) ? data : []); setLoadingTopics(false); });
  }, [classId, selectedSubject]);

  const completed = topics.filter((t) => t.isCompleted).length;
  const total = topics.length;
  const pct = total > 0 ? Math.round((completed / total) * 100) : 0;

  if (loading) return <div className="loading"><Sparkles size={18} className="animate-spin" /> Loading syllabus...</div>;

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Syllabus Progress</h1>
          <p className="page-subtitle">{className ? `${className} curriculum completion tracker` : "Track your child's syllabus progress"}</p>
        </div>
      </div>

      <div className="card" style={{ marginBottom: "20px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <BookOpen size={18} color="#fb7185" />
          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label" style={{ fontSize: "11px" }}>Subject</label>
            <select className="form-select" value={selectedSubject} onChange={(e) => setSelectedSubject(e.target.value)} style={{ width: "220px" }}>
              <option value="">— Select Subject —</option>
              {subjects.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>
        </div>
      </div>

      {selectedSubject && (
        <>
          {loadingTopics ? (
            <div className="loading"><Sparkles size={16} className="animate-spin" /> Loading topics...</div>
          ) : topics.length === 0 ? (
            <div className="card">
              <div className="empty-state">
                <div className="empty-state-icon-wrap"><BookOpen size={26} color="#fb7185" /></div>
                <div className="empty-state-title">No syllabus topics available</div>
                <p className="empty-state-text">The teacher has not added syllabus topics for this subject yet.</p>
              </div>
            </div>
          ) : (
            <>
              <div className="card" style={{ marginBottom: "16px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "10px" }}>
                  <CheckCircle2 size={16} color="#34d399" />
                  <span style={{ fontSize: "14px", fontWeight: 600 }}>
                    {completed} of {total} topics covered ({pct}%)
                  </span>
                </div>
                <div className="progress-bar">
                  <div className="progress-fill" style={{ width: `${pct}%` }} />
                </div>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                {topics.map((topic, i) => (
                  <div key={topic.id} className={`syllabus-topic-row ${topic.isCompleted ? "syllabus-topic-completed" : ""}`}>
                    <div className={`syllabus-check ${topic.isCompleted ? "syllabus-check-done" : ""}`} style={{ cursor: "default" }}>
                      {topic.isCompleted && <CheckCircle2 size={14} />}
                    </div>
                    <div style={{ flex: 1 }}>
                      <div style={{
                        fontSize: "13.5px", fontWeight: 600,
                        color: topic.isCompleted ? "var(--text-muted)" : "var(--text-primary)",
                        textDecoration: topic.isCompleted ? "line-through" : "none",
                      }}>
                        <span style={{ color: "var(--text-muted)", fontSize: "11px", marginRight: "8px" }}>#{i + 1}</span>
                        {topic.topicTitle}
                      </div>
                      {topic.description && (
                        <div style={{ fontSize: "12px", color: "var(--text-muted)", marginTop: "2px" }}>{topic.description}</div>
                      )}
                      {topic.isCompleted && topic.completedDate && (
                        <div style={{ fontSize: "11px", color: "#34d399", marginTop: "2px" }}>
                          ✓ Completed {new Date(topic.completedDate).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import React from "react";
import { CalendarClock, Sparkles } from "lucide-react";

type Period = { id: string; periodNumber: number; label: string; startTime: string; endTime: string; isBreak: boolean };
type Slot = {
  id: string; dayOfWeek: string; periodId: string;
  period: Period;
  subject: { id: string; name: string } | null;
  teacher: { id: string; fullName: string } | null;
};

const DAYS = ["MON", "TUE", "WED", "THU", "FRI", "SAT"];
const DAY_LABELS: Record<string, string> = { MON: "Mon", TUE: "Tue", WED: "Wed", THU: "Thu", FRI: "Fri", SAT: "Sat" };

export default function ParentTimetablePage() {
  const [periods, setPeriods] = useState<Period[]>([]);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [sectionId, setSectionId] = useState("");
  const [childName, setChildName] = useState("");

  useEffect(() => {
    // First, get parent's children to find the section
    fetch("/api/parent/students")
      .then((r) => r.json())
      .then((students: any[]) => {
        if (students.length > 0 && students[0].section?.id) {
          setSectionId(students[0].section.id);
          setChildName(students[0].fullName);
        }
        return fetch("/api/periods").then((r) => r.json());
      })
      .then((p) => {
        setPeriods(Array.isArray(p) ? p : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (!sectionId) return;
    fetch(`/api/timetable?sectionId=${sectionId}&academicYear=2026-27`)
      .then((r) => r.json())
      .then((data) => setSlots(Array.isArray(data) ? data : []));
  }, [sectionId]);

  const getSlot = (day: string, periodId: string) => slots.find((s) => s.dayOfWeek === day && s.periodId === periodId);

  if (loading) return <div className="loading"><Sparkles size={18} className="animate-spin" /> Loading timetable...</div>;

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Weekly Timetable</h1>
          <p className="page-subtitle">
            {childName ? `${childName}'s class schedule` : "Your child's weekly class schedule"}
          </p>
        </div>
      </div>

      {!sectionId ? (
        <div className="card">
          <div className="empty-state">
            <div className="empty-state-icon-wrap"><CalendarClock size={26} color="#fb7185" /></div>
            <div className="empty-state-title">No section assigned</div>
            <p className="empty-state-text">Your child is not currently assigned to a section with a timetable.</p>
          </div>
        </div>
      ) : periods.length === 0 ? (
        <div className="card">
          <div className="empty-state">
            <div className="empty-state-icon-wrap"><CalendarClock size={26} color="#fb7185" /></div>
            <div className="empty-state-title">No periods configured</div>
            <p className="empty-state-text">The school has not set up a period structure yet.</p>
          </div>
        </div>
      ) : (
        <div
          className="timetable-grid"
          style={{ gridTemplateColumns: `130px repeat(${DAYS.length}, 1fr)` }}
        >
          <div className="tt-header-cell">Period</div>
          {DAYS.map((d) => <div key={d} className="tt-header-cell">{DAY_LABELS[d]}</div>)}

          {periods.map((period) => (
            <React.Fragment key={period.id}>
              <div className="tt-period-label">
                <span>{period.label}</span>
                <span className="tt-period-time">{period.startTime} – {period.endTime}</span>
              </div>
              {DAYS.map((day) => {
                if (period.isBreak) {
                  return <div key={day} className="tt-break-cell">{period.label}</div>;
                }
                const slot = getSlot(day, period.id);
                return (
                  <div key={day} className="tt-cell" style={{ cursor: "default" }}>
                    {slot?.subject ? (
                      <>
                        <span className="tt-cell-subject">{slot.subject.name}</span>
                        {slot.teacher && <span className="tt-cell-teacher">{slot.teacher.fullName}</span>}
                      </>
                    ) : (
                      <span className="tt-cell-empty">—</span>
                    )}
                  </div>
                );
              })}
            </React.Fragment>
          ))}
        </div>
      )}
    </div>
  );
}

