"use client";

import { useState, useEffect } from "react";
import {
  ShieldCheck,
  ShieldAlert,
  Key,
  Copy,
  Check,
  RefreshCw,
  AlertTriangle,
  Lock,
  ArrowLeft,
} from "lucide-react";
import Link from "next/link";

export default function SuperAdminMfaSetupPage() {
  const [statusLoading, setStatusLoading] = useState(true);
  const [mfaEnabled, setMfaEnabled] = useState(false);
  const [email, setEmail] = useState("");
  const [remainingCodes, setRemainingCodes] = useState(0);

  // Setup state
  const [setupData, setSetupData] = useState<{
    secret: string;
    otpAuthUrl: string;
    recoveryCodes: string[];
  } | null>(null);
  const [setupLoading, setSetupLoading] = useState(false);
  const [verifyCode, setVerifyCode] = useState("");
  const [verifying, setVerifying] = useState(false);
  const [copiedKey, setCopiedKey] = useState(false);
  const [copiedCodes, setCopiedCodes] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  // Disable state
  const [disableModalOpen, setDisableModalOpen] = useState(false);
  const [disablePassword, setDisablePassword] = useState("");
  const [disableCode, setDisableCode] = useState("");
  const [disabling, setDisabling] = useState(false);

  const fetchStatus = async () => {
    setStatusLoading(true);
    try {
      const res = await fetch("/api/super-admin/mfa");
      if (res.ok) {
        const data = await res.json();
        setMfaEnabled(data.mfaEnabled);
        setEmail(data.email);
        setRemainingCodes(data.remainingRecoveryCodes);
      }
    } catch {
      // Ignore
    } finally {
      setStatusLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
  }, []);

  const handleStartSetup = async () => {
    setSetupLoading(true);
    setError("");
    setSuccess("");
    try {
      const res = await fetch("/api/super-admin/mfa", { method: "POST" });
      const data = await res.json();
      if (res.ok) {
        setSetupData({
          secret: data.secret,
          otpAuthUrl: data.otpAuthUrl,
          recoveryCodes: data.recoveryCodes,
        });
      } else {
        setError(data.error || "Failed to initialize MFA setup");
      }
    } catch {
      setError("Network error initializing MFA setup");
    } finally {
      setSetupLoading(false);
    }
  };

  const handleVerifyAndActivate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!verifyCode || verifyCode.trim().length !== 6) {
      setError("Please enter a valid 6-digit code.");
      return;
    }

    setVerifying(true);
    setError("");
    setSuccess("");

    try {
      const res = await fetch("/api/super-admin/mfa/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: verifyCode.trim() }),
      });
      const data = await res.json();
      if (res.ok) {
        setSuccess("Multi-Factor Authentication has been successfully activated!");
        setMfaEnabled(true);
        setSetupData(null);
        setVerifyCode("");
        fetchStatus();
      } else {
        setError(data.error || "Failed to activate MFA");
      }
    } catch {
      setError("Network error activating MFA");
    } finally {
      setVerifying(false);
    }
  };

  const handleDisableMfa = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!disablePassword || !disableCode) {
      setError("Password and 6-digit code are required.");
      return;
    }

    setDisabling(true);
    setError("");

    try {
      const res = await fetch("/api/super-admin/mfa", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          password: disablePassword,
          code: disableCode.trim(),
        }),
      });
      const data = await res.json();
      if (res.ok) {
        setSuccess("MFA has been disabled.");
        setDisableModalOpen(false);
        setDisablePassword("");
        setDisableCode("");
        fetchStatus();
      } else {
        setError(data.error || "Failed to disable MFA");
      }
    } catch {
      setError("Network error disabling MFA");
    } finally {
      setDisabling(false);
    }
  };

  const copyToClipboard = (text: string, setCopied: (v: boolean) => void) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div style={{ padding: "24px", maxWidth: "800px", margin: "0 auto" }}>
      <div style={{ marginBottom: "20px" }}>
        <Link
          href="/super-admin/dashboard"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: "6px",
            fontSize: "13px",
            color: "#64748b",
            textDecoration: "none",
            marginBottom: "12px",
          }}
        >
          <ArrowLeft size={14} /> Back to Super Admin Dashboard
        </Link>
        <h1 style={{ fontSize: "22px", fontWeight: 700, color: "#0f172a", margin: 0 }}>
          Platform Admin Multi-Factor Authentication (MFA)
        </h1>
        <p style={{ fontSize: "13px", color: "#64748b", marginTop: "4px" }}>
          Mandatory two-factor security for Super Admin platform governance
        </p>
      </div>

      {error && (
        <div
          style={{
            padding: "12px 16px",
            backgroundColor: "#fef2f2",
            border: "1px solid #fecaca",
            borderRadius: "8px",
            color: "#b91c1c",
            fontSize: "13px",
            marginBottom: "16px",
            display: "flex",
            alignItems: "center",
            gap: "8px",
          }}
        >
          <AlertTriangle size={16} />
          <span>{error}</span>
        </div>
      )}

      {success && (
        <div
          style={{
            padding: "12px 16px",
            backgroundColor: "#f0fdf4",
            border: "1px solid #bbf7d0",
            borderRadius: "8px",
            color: "#15803d",
            fontSize: "13px",
            marginBottom: "16px",
            display: "flex",
            alignItems: "center",
            gap: "8px",
          }}
        >
          <Check size={16} />
          <span>{success}</span>
        </div>
      )}

      {/* Status Card */}
      <div
        style={{
          background: "#ffffff",
          border: "1px solid #e2e8f0",
          borderRadius: "12px",
          padding: "24px",
          marginBottom: "24px",
          boxShadow: "0 1px 3px rgba(0,0,0,0.05)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <div
              style={{
                width: "44px",
                height: "44px",
                borderRadius: "10px",
                backgroundColor: mfaEnabled ? "#ecfdf5" : "#fff7ed",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: mfaEnabled ? "#059669" : "#ea580c",
              }}
            >
              {mfaEnabled ? <ShieldCheck size={24} /> : <ShieldAlert size={24} />}
            </div>
            <div>
              <div style={{ fontSize: "15px", fontWeight: 600, color: "#0f172a" }}>
                {statusLoading
                  ? "Checking status..."
                  : mfaEnabled
                  ? "MFA Protection Active"
                  : "MFA Not Configured"}
              </div>
              <div style={{ fontSize: "12px", color: "#64748b", marginTop: "2px" }}>
                Account: {email || "Super Admin"}
                {mfaEnabled && ` • ${remainingCodes} recovery code(s) remaining`}
              </div>
            </div>
          </div>

          <div>
            {!statusLoading && (
              <>
                {mfaEnabled ? (
                  <button
                    onClick={() => setDisableModalOpen(true)}
                    style={{
                      padding: "8px 14px",
                      borderRadius: "6px",
                      border: "1px solid #e2e8f0",
                      background: "#f8fafc",
                      fontSize: "12px",
                      fontWeight: 600,
                      color: "#dc2626",
                      cursor: "pointer",
                    }}
                  >
                    Disable MFA
                  </button>
                ) : (
                  <button
                    onClick={handleStartSetup}
                    disabled={setupLoading}
                    style={{
                      padding: "9px 18px",
                      borderRadius: "8px",
                      border: "none",
                      background: "#2563eb",
                      fontSize: "13px",
                      fontWeight: 600,
                      color: "#ffffff",
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                    }}
                  >
                    {setupLoading ? <RefreshCw size={14} className="animate-spin" /> : <Key size={14} />}
                    <span>Begin MFA Setup</span>
                  </button>
                )}
              </>
            )}
          </div>
        </div>
      </div>

      {/* Setup Wizard */}
      {setupData && !mfaEnabled && (
        <div
          style={{
            background: "#ffffff",
            border: "1px solid #3b82f6",
            borderRadius: "12px",
            padding: "24px",
            marginBottom: "24px",
            boxShadow: "0 4px 12px rgba(37,99,235,0.08)",
          }}
        >
          <h2 style={{ fontSize: "17px", fontWeight: 700, color: "#1e3a8a", marginBottom: "16px" }}>
            Step 1: Configure Authenticator App
          </h2>

          <p style={{ fontSize: "13px", color: "#475569", lineHeight: 1.5, marginBottom: "16px" }}>
            Open Google Authenticator, Microsoft Authenticator, 1Password, or any RFC 6238 compatible app. Select
            <strong> Add Account</strong> &gt; <strong>Enter setup key</strong>, and paste the key below:
          </p>

          {/* Secret Key Box */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              background: "#f1f5f9",
              padding: "12px 16px",
              borderRadius: "8px",
              fontFamily: "monospace",
              fontSize: "15px",
              fontWeight: 700,
              letterSpacing: "1px",
              color: "#0f172a",
              marginBottom: "20px",
            }}
          >
            <span>{setupData.secret}</span>
            <button
              onClick={() => copyToClipboard(setupData.secret, setCopiedKey)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "4px",
                border: "none",
                background: "#ffffff",
                padding: "6px 10px",
                borderRadius: "6px",
                fontSize: "12px",
                fontWeight: 600,
                color: "#2563eb",
                cursor: "pointer",
                boxShadow: "0 1px 2px rgba(0,0,0,0.05)",
              }}
            >
              {copiedKey ? <Check size={14} /> : <Copy size={14} />}
              <span>{copiedKey ? "Copied" : "Copy Key"}</span>
            </button>
          </div>

          {/* Recovery Codes Section */}
          <h2 style={{ fontSize: "17px", fontWeight: 700, color: "#1e3a8a", marginBottom: "8px" }}>
            Step 2: Save Emergency Recovery Codes
          </h2>
          <p style={{ fontSize: "12px", color: "#64748b", marginBottom: "12px" }}>
            If you ever lose access to your authenticator phone, each of these 8 codes can be used once as a backup login code. Store them in your secure password manager now:
          </p>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(2, 1fr)",
              gap: "8px",
              background: "#f8fafc",
              border: "1px dashed #cbd5e1",
              padding: "16px",
              borderRadius: "8px",
              marginBottom: "16px",
            }}
          >
            {setupData.recoveryCodes.map((code, i) => (
              <div
                key={i}
                style={{
                  fontFamily: "monospace",
                  fontSize: "13px",
                  fontWeight: 600,
                  color: "#334155",
                }}
              >
                {i + 1}. {code}
              </div>
            ))}
          </div>

          <button
            onClick={() => copyToClipboard(setupData.recoveryCodes.join("\n"), setCopiedCodes)}
            style={{
              padding: "7px 14px",
              borderRadius: "6px",
              border: "1px solid #cbd5e1",
              background: "#ffffff",
              fontSize: "12px",
              fontWeight: 600,
              color: "#334155",
              cursor: "pointer",
              marginBottom: "24px",
              display: "inline-flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            {copiedCodes ? <Check size={14} /> : <Copy size={14} />}
            <span>{copiedCodes ? "Copied All Codes!" : "Copy All Recovery Codes"}</span>
          </button>

          {/* Verification Code Input */}
          <h2 style={{ fontSize: "17px", fontWeight: 700, color: "#1e3a8a", marginBottom: "8px" }}>
            Step 3: Confirm 6-Digit Code
          </h2>
          <p style={{ fontSize: "12px", color: "#64748b", marginBottom: "12px" }}>
            Enter the 6-digit number shown on your authenticator app to verify setup and activate protection:
          </p>

          <form onSubmit={handleVerifyAndActivate} style={{ display: "flex", gap: "10px", alignItems: "center" }}>
            <input
              type="text"
              placeholder="e.g. 123456"
              maxLength={6}
              value={verifyCode}
              onChange={(e) => setVerifyCode(e.target.value)}
              style={{
                padding: "10px 14px",
                border: "2px solid #3b82f6",
                borderRadius: "8px",
                fontSize: "16px",
                fontWeight: 700,
                letterSpacing: "3px",
                width: "160px",
                textAlign: "center",
                outline: "none",
              }}
              required
            />
            <button
              type="submit"
              disabled={verifying}
              style={{
                padding: "11px 20px",
                borderRadius: "8px",
                border: "none",
                background: "#2563eb",
                color: "#ffffff",
                fontSize: "13px",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              {verifying ? "Verifying..." : "Verify & Enable MFA"}
            </button>
          </form>
        </div>
      )}

      {/* Disable Modal */}
      {disableModalOpen && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
            padding: "16px",
          }}
        >
          <div
            style={{
              background: "#ffffff",
              borderRadius: "12px",
              padding: "24px",
              maxWidth: "420px",
              width: "100%",
              boxShadow: "0 20px 25px -5px rgba(0,0,0,0.2)",
            }}
          >
            <h3 style={{ fontSize: "17px", fontWeight: 700, color: "#dc2626", marginBottom: "8px" }}>
              Disable Multi-Factor Authentication
            </h3>
            <p style={{ fontSize: "12px", color: "#64748b", marginBottom: "16px", lineHeight: 1.4 }}>
              Disabling MFA reduces your Super Admin account security. Enter your password and current 6-digit authenticator code to proceed.
            </p>

            <form onSubmit={handleDisableMfa}>
              <div style={{ marginBottom: "14px" }}>
                <label style={{ display: "block", fontSize: "12px", fontWeight: 600, color: "#334155", marginBottom: "4px" }}>
                  Current Password
                </label>
                <input
                  type="password"
                  placeholder="Enter your account password"
                  value={disablePassword}
                  onChange={(e) => setDisablePassword(e.target.value)}
                  style={{
                    width: "100%",
                    padding: "9px 12px",
                    borderRadius: "6px",
                    border: "1px solid #cbd5e1",
                    fontSize: "13px",
                  }}
                  required
                />
              </div>

              <div style={{ marginBottom: "20px" }}>
                <label style={{ display: "block", fontSize: "12px", fontWeight: 600, color: "#334155", marginBottom: "4px" }}>
                  6-Digit Authenticator Code
                </label>
                <input
                  type="text"
                  placeholder="123456"
                  maxLength={6}
                  value={disableCode}
                  onChange={(e) => setDisableCode(e.target.value)}
                  style={{
                    width: "100%",
                    padding: "9px 12px",
                    borderRadius: "6px",
                    border: "1px solid #cbd5e1",
                    fontSize: "15px",
                    letterSpacing: "2px",
                    fontWeight: 700,
                  }}
                  required
                />
              </div>

              <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px" }}>
                <button
                  type="button"
                  onClick={() => setDisableModalOpen(false)}
                  style={{
                    padding: "8px 14px",
                    borderRadius: "6px",
                    border: "1px solid #cbd5e1",
                    background: "#ffffff",
                    fontSize: "13px",
                    cursor: "pointer",
                  }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={disabling}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "6px",
                    border: "none",
                    background: "#dc2626",
                    color: "#ffffff",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  {disabling ? "Disabling..." : "Confirm Disable"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { BookOpen, Plus, FileText, Calendar, Upload, Trash2, Edit2, Download, AlertCircle, Sparkles, X, Save, Paperclip } from "lucide-react";

type Section = { id: string; name: string; class: { id: string; name: string } };
type Subject = { id: string; name: string };
type Assignment = {
  id: string;
  title: string;
  description: string;
  dueDate: string | null;
  attachmentUrl: string | null;
  createdAt: string;
  section: { id: string; name: string; class: { id: string; name: string } };
  subject: { id: string; name: string };
  teacher: { id: string; fullName: string };
};

export default function TeacherAssignmentsPage() {
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [loading, setLoading] = useState(true);

  // Modal State
  const [showModal, setShowModal] = useState(false);
  const [editingAssignment, setEditingAssignment] = useState<Assignment | null>(null);
  const [sectionId, setSectionId] = useState("");
  const [subjectId, setSubjectId] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [attachmentUrl, setAttachmentUrl] = useState("");
  const [uploadingFile, setUploadingFile] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const fetchData = () => {
    Promise.all([
      fetch("/api/assignments").then((r) => r.json()),
      fetch("/api/sections").then((r) => r.json()),
      fetch("/api/subjects").then((r) => r.json()),
    ])
      .then(([ass, sec, sub]) => {
        setAssignments(Array.isArray(ass) ? ass : []);
        setSections(Array.isArray(sec) ? sec : []);
        setSubjects(Array.isArray(sub) ? sub : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchData();
  }, []);

  const openCreateModal = () => {
    setEditingAssignment(null);
    setSectionId(sections.length > 0 ? sections[0].id : "");
    setSubjectId(subjects.length > 0 ? subjects[0].id : "");
    setTitle("");
    setDescription("");
    setDueDate("");
    setAttachmentUrl("");
    setError("");
    setShowModal(true);
  };

  const openEditModal = (a: Assignment) => {
    setEditingAssignment(a);
    setSectionId(a.section.id);
    setSubjectId(a.subject.id);
    setTitle(a.title);
    setDescription(a.description);
    setDueDate(a.dueDate ? a.dueDate.slice(0, 10) : "");
    setAttachmentUrl(a.attachmentUrl || "");
    setError("");
    setShowModal(true);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 10 * 1024 * 1024) {
      setError("File size exceeds 10MB limit.");
      return;
    }

    setUploadingFile(true);
    setError("");
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("/api/upload/assignment", {
        method: "POST",
        body: formData,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to upload attachment");
      setAttachmentUrl(data.url);
    } catch (err: any) {
      setError(err.message || "Failed to upload file");
    } finally {
      setUploadingFile(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !sectionId || !subjectId) {
      setError("Title, Section, and Subject are required");
      return;
    }
    setSaving(true);
    setError("");

    try {
      const payload: any = {
        sectionId,
        subjectId,
        title: title.trim(),
        description: description.trim(),
        dueDate: dueDate || null,
        attachmentUrl: attachmentUrl || null,
      };
      if (editingAssignment) payload.id = editingAssignment.id;

      const res = await fetch("/api/assignments", {
        method: editingAssignment ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to save assignment");

      setShowModal(false);
      fetchData();
    } catch (err: any) {
      setError(err.message || "Failed to save assignment");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this assignment?")) return;
    try {
      const res = await fetch(`/api/assignments?id=${id}`, { method: "DELETE" });
      if (res.ok) fetchData();
    } catch (err) {
      console.error(err);
    }
  };

  const formatDisplayDate = (d: string | null) => {
    if (!d) return "No Due Date";
    const date = new Date(d);
    return isNaN(date.getTime())
      ? d
      : date.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  };

  if (loading) {
    return (
      <div className="loading">
        <Sparkles size={18} className="animate-spin" /> Loading assignments...
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Assignments &amp; Study Notes</h1>
          <p className="page-subtitle">Publish homework, syllabus notes, and study materials for your classes</p>
        </div>
        <button className="btn btn-primary" onClick={openCreateModal} style={{ gap: "6px" }}>
          <Plus size={16} />
          <span>Post Assignment / Note</span>
        </button>
      </div>

      {assignments.length === 0 ? (
        <div className="card empty-state" style={{ padding: "40px 20px" }}>
          <BookOpen size={36} color="var(--text-muted)" style={{ marginBottom: "12px" }} />
          <div className="empty-state-title">No Assignments Posted Yet</div>
          <p style={{ color: "var(--text-secondary)", marginBottom: "16px" }}>
            Create assignments, upload homework sheets, or share study notes with students and parents.
          </p>
          <button className="btn btn-primary btn-sm" onClick={openCreateModal}>
            <Plus size={14} /> Post First Assignment
          </button>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(340px, 1fr))", gap: "16px" }}>
          {assignments.map((item) => {
            const isPastDue = item.dueDate ? new Date(item.dueDate).getTime() < new Date().setHours(0, 0, 0, 0) : false;

            return (
              <div
                key={item.id}
                className="card"
                style={{
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                  borderLeft: `4px solid ${isPastDue ? "var(--border-color)" : "#818cf8"}`,
                }}
              >
                <div>
                  <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: "8px" }}>
                    <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
                      <span className="badge badge-teal">{item.section.class.name} — {item.section.name}</span>
                      <span className="badge badge-warning">{item.subject.name}</span>
                    </div>
                    <div style={{ display: "flex", gap: "4px" }}>
                      <button className="btn-icon" onClick={() => openEditModal(item)} title="Edit">
                        <Edit2 size={14} />
                      </button>
                      <button className="btn-icon danger" onClick={() => handleDelete(item.id)} title="Delete">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>

                  <h3 style={{ fontSize: "16px", fontWeight: 700, margin: "6px 0 8px 0" }}>{item.title}</h3>
                  <p style={{ fontSize: "13px", color: "var(--text-secondary)", whiteSpace: "pre-wrap", marginBottom: "14px", lineHeight: "1.5" }}>
                    {item.description || "No additional instructions provided."}
                  </p>
                </div>

                <div>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-between",
                      paddingTop: "10px",
                      borderTop: "1px solid var(--border-subtle)",
                      fontSize: "12px",
                    }}
                  >
                    <div style={{ display: "flex", alignItems: "center", gap: "5px", color: isPastDue ? "var(--text-muted)" : "var(--text-primary)" }}>
                      <Calendar size={14} color={isPastDue ? "var(--text-muted)" : "#818cf8"} />
                      <span>Due: {formatDisplayDate(item.dueDate)}</span>
                    </div>

                    {item.attachmentUrl && (
                      <a
                        href={item.attachmentUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="btn btn-secondary btn-sm"
                        style={{ padding: "3px 8px", fontSize: "11.5px", gap: "4px" }}
                      >
                        <Download size={12} />
                        <span>Attachment</span>
                      </a>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ─── Create/Edit Assignment Modal ─── */}
      {showModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0,0,0,0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
            padding: "20px",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            className="card"
            style={{ maxWidth: "540px", width: "100%", maxHeight: "90vh", overflowY: "auto", padding: "24px" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "16px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <BookOpen size={18} color="#818cf8" />
                <h3 className="card-title" style={{ margin: 0, fontSize: "16px" }}>
                  {editingAssignment ? "Edit Assignment / Note" : "Post New Assignment or Study Note"}
                </h3>
              </div>
              <button className="btn-icon" onClick={() => setShowModal(false)}><X size={16} /></button>
            </div>

            {error && (
              <div className="alert alert-error" style={{ marginBottom: "14px" }}>
                <AlertCircle size={15} /> <span>{error}</span>
              </div>
            )}

            <form onSubmit={handleSave} style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Class &amp; Section *</label>
                  <select
                    className="form-select"
                    value={sectionId}
                    onChange={(e) => setSectionId(e.target.value)}
                    required
                  >
                    <option value="">— Select Section —</option>
                    {sections.map((s) => (
                      <option key={s.id} value={s.id}>
                        {s.class.name} — Section {s.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label">Subject *</label>
                  <select
                    className="form-select"
                    value={subjectId}
                    onChange={(e) => setSubjectId(e.target.value)}
                    required
                  >
                    <option value="">— Select Subject —</option>
                    {subjects.map((s) => (
                      <option key={s.id} value={s.id}>{s.name}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Title *</label>
                <input
                  type="text"
                  className="form-input"
                  placeholder="e.g. Chapter 4 Practice Questions / Formula Sheet"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Description / Instructions</label>
                <textarea
                  className="form-input"
                  rows={3}
                  placeholder="Describe homework tasks, reference textbook page numbers, or guidelines..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Submission Due Date (Optional)</label>
                <input
                  type="date"
                  className="form-input"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Document / File Attachment (Optional)</label>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <input
                    type="file"
                    id="assignmentFile"
                    style={{ display: "none" }}
                    onChange={handleFileUpload}
                  />
                  <label
                    htmlFor="assignmentFile"
                    className="btn btn-secondary btn-sm"
                    style={{ cursor: "pointer", gap: "6px" }}
                  >
                    <Upload size={14} />
                    <span>{uploadingFile ? "Uploading..." : "Upload File / PDF"}</span>
                  </label>

                  {attachmentUrl && (
                    <div style={{ display: "flex", alignItems: "center", gap: "6px", fontSize: "12px", color: "var(--text-secondary)" }}>
                      <Paperclip size={13} color="#34d399" />
                      <span>File attached</span>
                      <button
                        type="button"
                        className="btn-icon danger"
                        onClick={() => setAttachmentUrl("")}
                        style={{ padding: "2px" }}
                        title="Remove attachment"
                      >
                        <X size={12} />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "10px" }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)} disabled={saving}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary" disabled={saving || uploadingFile} style={{ gap: "6px" }}>
                  {saving ? <Sparkles size={14} className="animate-spin" /> : <Save size={14} />}
                  <span>{saving ? "Publishing..." : "Publish to Class"}</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

