"use client";

import { useEffect, useState, useMemo } from "react";
import {
  CheckCircle2,
  Calendar,
  AlertCircle,
  Sparkles,
  Check,
  X,
  Clock,
  School,
  Save,
  Users,
} from "lucide-react";

type SectionOption = { id: string; name: string; class: { name: string } };
type StudentData = { id: string; fullName: string; admissionNo: string };

const STATUSES = [
  { key: "PRESENT", label: "Present", color: "green" },
  { key: "ABSENT", label: "Absent", color: "red" },
  { key: "LATE", label: "Late", color: "amber" },
  { key: "HALF_DAY", label: "Half Day", color: "amber" },
  { key: "LEAVE", label: "On Leave", color: "blue" },
];

export default function AttendancePage() {
  const [sections, setSections] = useState<SectionOption[]>([]);
  const [sectionId, setSectionId] = useState("");
  const [date, setDate] = useState(new Date().toISOString().split("T")[0]);
  const [students, setStudents] = useState<StudentData[]>([]);
  const [attendance, setAttendance] = useState<Record<string, string>>({});
  const [existing, setExisting] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [isError, setIsError] = useState(false);

  useEffect(() => {
    fetch("/api/sections").then((r) => r.json()).then((data) => {
      setSections(Array.isArray(data) ? data : []);
      if (Array.isArray(data) && data.length > 0 && !sectionId) {
        setSectionId(data[0].id);
      }
    });
  }, []);

  useEffect(() => {
    if (!sectionId) return;
    setLoading(true);
    setMessage("");

    Promise.all([
      fetch(`/api/students?sectionId=${sectionId}`).then((r) => r.json()),
      fetch(`/api/attendance?sectionId=${sectionId}&date=${date}`).then((r) => r.json()),
    ]).then(([studentsData, attendanceData]) => {
      const validStudents = Array.isArray(studentsData) ? studentsData : [];
      setStudents(validStudents);

      const att: Record<string, string> = {};
      const ex = new Set<string>();
      if (Array.isArray(attendanceData)) {
        for (const rec of attendanceData) {
          att[rec.studentId] = rec.status;
          ex.add(rec.studentId);
        }
      }
      for (const s of validStudents) {
        if (!att[s.id]) att[s.id] = "PRESENT";
      }
      setAttendance(att);
      setExisting(ex);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [sectionId, date]);

  const handleSave = async () => {
    setSaving(true);
    setMessage("");
    setIsError(false);

    const records = students.map((s) => ({
      studentId: s.id,
      status: attendance[s.id] || "PRESENT",
    }));

    try {
      const res = await fetch("/api/attendance", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sectionId, date, records }),
      });

      const data = await res.json();
      setSaving(false);

      if (res.ok) {
        setMessage(data.message || `Attendance saved successfully for ${records.length} students.`);
        setIsError(false);
        setExisting(new Set(students.map((s) => s.id)));
      } else {
        setMessage(data.error || "Failed to save attendance");
        setIsError(true);
      }
    } catch (err: any) {
      setSaving(false);
      setMessage(err.message || "An unexpected error occurred");
      setIsError(true);
    }
  };

  const markAll = (status: string) => {
    const updated: Record<string, string> = {};
    for (const s of students) {
      updated[s.id] = status;
    }
    setAttendance(updated);
  };

  const setStudentStatus = (studentId: string, status: string) => {
    setAttendance((prev) => ({ ...prev, [studentId]: status }));
  };

  // Count summaries
  const presentCount = students.filter((s) => (attendance[s.id] || "PRESENT") === "PRESENT").length;
  const absentCount = students.filter((s) => (attendance[s.id] || "PRESENT") === "ABSENT").length;

  return (
    <div className="office-page-container">
      {/* ─── Page Header ─── */}
      <div className="office-header">
        <div>
          <h1 className="office-title">Daily Attendance Register</h1>
          <p className="office-subtitle">
            Select classroom section, set attendance date, and mark student status with 1-click controls
          </p>
        </div>
      </div>

      {/* ─── Classroom & Date Selector Card ─── */}
      <div className="office-card" style={{ marginBottom: "20px" }}>
        <div className="office-form-grid-2">
          <div className="office-form-group">
            <label className="office-form-label">Select Class & Section</label>
            <select
              className="office-select"
              value={sectionId}
              onChange={(e) => setSectionId(e.target.value)}
              style={{ width: "100%" }}
            >
              <option value="">-- Choose Classroom --</option>
              {sections.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.class.name} — Section {s.name}
                </option>
              ))}
            </select>
          </div>

          <div className="office-form-group">
            <label className="office-form-label">Attendance Date</label>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="office-input"
              style={{ width: "100%" }}
            />
          </div>
        </div>
      </div>

      {message && (
        <div
          style={{
            background: isError ? "#fef2f2" : "#ecfdf5",
            border: `1px solid ${isError ? "#fecaca" : "#a7f3d0"}`,
            color: isError ? "#991b1b" : "#065f46",
            borderRadius: "8px",
            padding: "14px 18px",
            marginBottom: "20px",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "14px",
            fontWeight: 500,
          }}
        >
          {isError ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />}
          <span>{message}</span>
        </div>
      )}

      {loading ? (
        <div className="office-card" style={{ padding: "60px 20px", textAlign: "center" }}>
          <Sparkles size={22} className="animate-spin" color="#1e3a8a" style={{ margin: "0 auto 8px" }} />
          <div style={{ color: "#64748b", fontSize: "14px" }}>Loading students for this classroom...</div>
        </div>
      ) : !sectionId ? (
        <div className="office-card" style={{ padding: "48px 20px", textAlign: "center", color: "#64748b" }}>
          Please select a classroom section to load the daily student attendance register.
        </div>
      ) : students.length === 0 ? (
        <div className="office-card" style={{ padding: "48px 20px", textAlign: "center", color: "#64748b" }}>
          No enrolled students found in this section.
        </div>
      ) : (
        <div className="office-card" style={{ padding: 0, overflow: "hidden" }}>
          {/* Card Action Header */}
          <div
            style={{
              padding: "18px 22px",
              background: "#f8fafc",
              borderBottom: "1px solid #e2e8f0",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              flexWrap: "wrap",
              gap: "14px",
            }}
          >
            <div>
              <div style={{ fontSize: "16px", fontWeight: 700, color: "#0f172a" }}>
                Class Roster ({students.length} Students)
              </div>
              <div style={{ fontSize: "12.5px", color: "#64748b", marginTop: "2px" }}>
                Present: <strong style={{ color: "#059669" }}>{presentCount}</strong> • Absent:{" "}
                <strong style={{ color: "#dc2626" }}>{absentCount}</strong>
                {existing.size > 0 && " • Previously recorded"}
              </div>
            </div>

            <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
              <button
                type="button"
                onClick={() => markAll("PRESENT")}
                className="office-btn office-btn-secondary office-btn-sm"
              >
                <Check size={14} color="#059669" />
                <span>Mark All Present</span>
              </button>
              <button
                type="button"
                onClick={() => markAll("ABSENT")}
                className="office-btn office-btn-secondary office-btn-sm"
              >
                <X size={14} color="#dc2626" />
                <span>Mark All Absent</span>
              </button>
            </div>
          </div>

          {/* Student Attendance Rows Table */}
          <div className="office-table-wrapper" style={{ border: "none", borderRadius: 0 }}>
            <table className="office-table">
              <thead>
                <tr>
                  <th style={{ width: "60px" }}>#</th>
                  <th style={{ width: "130px" }}>Adm. No.</th>
                  <th>Student Full Name</th>
                  <th style={{ textAlign: "right" }}>Attendance Status</th>
                </tr>
              </thead>
              <tbody>
                {students.map((s, index) => {
                  const currentStatus = attendance[s.id] || "PRESENT";
                  return (
                    <tr key={s.id}>
                      <td style={{ color: "#94a3b8", fontSize: "13px" }}>{index + 1}</td>
                      <td style={{ fontFamily: "monospace", fontSize: "13px", fontWeight: 600, color: "#1e3a8a" }}>
                        {s.admissionNo}
                      </td>
                      <td>
                        <span style={{ fontWeight: 600, color: "#0f172a" }}>{s.fullName}</span>
                      </td>
                      <td style={{ textAlign: "right" }}>
                        <div style={{ display: "inline-flex", gap: "6px", flexWrap: "wrap", justifyContent: "flex-end" }}>
                          {STATUSES.map((status) => {
                            const isSelected = currentStatus === status.key;
                            let activeStyle: React.CSSProperties = {};
                            if (isSelected) {
                              if (status.color === "green") {
                                activeStyle = { background: "#059669", color: "#ffffff", borderColor: "#059669", fontWeight: 700 };
                              } else if (status.color === "red") {
                                activeStyle = { background: "#dc2626", color: "#ffffff", borderColor: "#dc2626", fontWeight: 700 };
                              } else if (status.color === "amber") {
                                activeStyle = { background: "#d97706", color: "#ffffff", borderColor: "#d97706", fontWeight: 700 };
                              } else {
                                activeStyle = { background: "#1e3a8a", color: "#ffffff", borderColor: "#1e3a8a", fontWeight: 700 };
                              }
                            }

                            return (
                              <button
                                key={status.key}
                                type="button"
                                onClick={() => setStudentStatus(s.id, status.key)}
                                style={{
                                  padding: "5px 12px",
                                  borderRadius: "6px",
                                  border: "1px solid #cbd5e1",
                                  background: "#ffffff",
                                  color: "#334155",
                                  fontSize: "12px",
                                  fontWeight: 500,
                                  cursor: "pointer",
                                  transition: "all 0.12s ease",
                                  ...activeStyle,
                                }}
                              >
                                {status.label}
                              </button>
                            );
                          })}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Bottom Save Action Bar */}
          <div
            style={{
              padding: "20px 24px",
              background: "#ffffff",
              borderTop: "1px solid #e2e8f0",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "14px",
            }}
          >
            <div style={{ fontSize: "13px", color: "#64748b" }}>
              Total: <strong>{students.length}</strong> students | Present: <strong>{presentCount}</strong> | Absent: <strong>{absentCount}</strong>
            </div>

            <button
              type="button"
              onClick={handleSave}
              disabled={saving}
              className="office-btn office-btn-success"
              style={{ minWidth: "220px", height: "44px" }}
            >
              {saving ? (
                <>
                  <Sparkles size={16} className="animate-spin" />
                  <span>Saving Attendance...</span>
                </>
              ) : (
                <>
                  <Save size={16} />
                  <span>Save Attendance Register</span>
                </>
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Calendar, Plus, Clock, CheckCircle2, XCircle, AlertCircle, Sparkles, X, Save, FileText } from "lucide-react";

type LeaveRequest = {
  id: string;
  leaveType: string;
  startDate: string;
  endDate: string;
  reason: string;
  status: "PENDING" | "APPROVED" | "REJECTED";
  adminRemark: string | null;
  createdAt: string;
};

export default function TeacherLeavePage() {
  const [requests, setRequests] = useState<LeaveRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // Application Modal State
  const [showModal, setShowModal] = useState(false);
  const [leaveType, setLeaveType] = useState("Casual");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [successMsg, setSuccessMsg] = useState("");

  const fetchMyLeaves = () => {
    fetch("/api/leave")
      .then((r) => r.json())
      .then((data) => {
        setRequests(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchMyLeaves();
  }, []);

  const openApplyModal = () => {
    setLeaveType("Casual");
    const today = new Date().toISOString().slice(0, 10);
    setStartDate(today);
    setEndDate(today);
    setReason("");
    setError("");
    setShowModal(true);
  };

  const handleApply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!startDate || !endDate || !reason.trim()) {
      setError("Please complete all required fields");
      return;
    }
    setSubmitting(true);
    setError("");

    try {
      const res = await fetch("/api/leave", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          leaveType,
          startDate,
          endDate,
          reason: reason.trim(),
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to submit leave request");
      }

      setShowModal(false);
      setSuccessMsg("Leave application submitted successfully for administrator review.");
      setTimeout(() => setSuccessMsg(""), 4000);
      fetchMyLeaves();
    } catch (err: any) {
      setError(err.message || "Failed to submit leave application");
    } finally {
      setSubmitting(false);
    }
  };

  const formatDisplayDate = (d: string) => {
    const date = new Date(d);
    return isNaN(date.getTime())
      ? d
      : date.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  };

  const calcDays = (startStr: string, endStr: string) => {
    const s = new Date(startStr);
    const e = new Date(endStr);
    const diffTime = Math.abs(e.getTime() - s.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
    return diffDays;
  };

  if (loading) {
    return (
      <div className="loading">
        <Sparkles size={18} className="animate-spin" /> Loading your leave history...
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">My Leave Applications</h1>
          <p className="page-subtitle">Apply for time off, view approval status, and check past leave history</p>
        </div>
        <button className="btn btn-primary" onClick={openApplyModal} style={{ gap: "6px" }}>
          <Plus size={16} />
          <span>Apply for Leave</span>
        </button>
      </div>

      {successMsg && (
        <div className="alert alert-success" style={{ marginBottom: "16px" }}>
          <CheckCircle2 size={16} /> <span>{successMsg}</span>
        </div>
      )}

      {requests.length === 0 ? (
        <div className="card empty-state" style={{ padding: "40px 20px" }}>
          <Calendar size={36} color="var(--text-muted)" style={{ marginBottom: "12px" }} />
          <div className="empty-state-title">No Leave Applications on Record</div>
          <p style={{ color: "var(--text-secondary)", marginBottom: "16px" }}>
            You have not submitted any leave requests yet.
          </p>
          <button className="btn btn-primary btn-sm" onClick={openApplyModal}>
            <Plus size={14} /> Submit First Application
          </button>
        </div>
      ) : (
        <div className="card" style={{ padding: 0, overflow: "hidden" }}>
          <div className="table-responsive">
            <table className="table">
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Date Range</th>
                  <th>Days</th>
                  <th>Reason</th>
                  <th>Applied On</th>
                  <th>Status</th>
                  <th>Admin Remarks</th>
                </tr>
              </thead>
              <tbody>
                {requests.map((req) => {
                  const days = calcDays(req.startDate, req.endDate);

                  return (
                    <tr key={req.id}>
                      <td>
                        <span className="badge badge-teal">{req.leaveType}</span>
                      </td>
                      <td style={{ fontSize: "13px" }}>
                        <div>{formatDisplayDate(req.startDate)} to</div>
                        <div style={{ color: "var(--text-muted)" }}>{formatDisplayDate(req.endDate)}</div>
                      </td>
                      <td style={{ fontWeight: 600 }}>{days} {days === 1 ? "day" : "days"}</td>
                      <td style={{ maxWidth: "240px", fontSize: "13px" }}>{req.reason}</td>
                      <td style={{ fontSize: "12px", color: "var(--text-muted)" }}>
                        {formatDisplayDate(req.createdAt)}
                      </td>
                      <td>
                        {req.status === "PENDING" && <span className="badge badge-warning">Pending Review</span>}
                        {req.status === "APPROVED" && <span className="badge badge-success">Approved</span>}
                        {req.status === "REJECTED" && <span className="badge badge-danger">Rejected</span>}
                      </td>
                      <td style={{ fontSize: "12px", color: "var(--text-secondary)", maxWidth: "180px" }}>
                        {req.adminRemark || "—"}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ─── Apply Leave Modal ─── */}
      {showModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0,0,0,0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999,
            padding: "20px",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            className="card"
            style={{ maxWidth: "480px", width: "100%", padding: "24px" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "16px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <Calendar size={18} color="#818cf8" />
                <h3 className="card-title" style={{ margin: 0, fontSize: "16px" }}>Apply for Leave</h3>
              </div>
              <button className="btn-icon" onClick={() => setShowModal(false)}><X size={16} /></button>
            </div>

            {error && (
              <div className="alert alert-error" style={{ marginBottom: "14px" }}>
                <AlertCircle size={15} /> <span>{error}</span>
              </div>
            )}

            <form onSubmit={handleApply} style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
              <div className="form-group">
                <label className="form-label">Leave Type *</label>
                <select
                  className="form-select"
                  value={leaveType}
                  onChange={(e) => setLeaveType(e.target.value)}
                >
                  <option value="Casual">Casual Leave (CL)</option>
                  <option value="Sick">Medical / Sick Leave (ML)</option>
                  <option value="Earned">Earned Leave (EL)</option>
                  <option value="Maternity">Maternity / Paternity Leave</option>
                  <option value="Duty">On Duty / Official Duty</option>
                  <option value="Other">Other Reason</option>
                </select>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Start Date *</label>
                  <input
                    type="date"
                    className="form-input"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">End Date *</label>
                  <input
                    type="date"
                    className="form-input"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    required
                  />
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Reason / Explanation *</label>
                <textarea
                  className="form-input"
                  rows={3}
                  placeholder="Provide reason for time off..."
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  required
                />
              </div>

              <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "8px" }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)} disabled={submitting}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary" disabled={submitting} style={{ gap: "6px" }}>
                  {submitting ? <Sparkles size={14} className="animate-spin" /> : <Save size={14} />}
                  <span>{submitting ? "Submitting..." : "Submit Application"}</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

