import { NextResponse } from "next/server";
import { getTenantDb, unauthorized } from "@/lib/utils";

export async function GET() {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const role = ctx.session.user.role;
  if (role !== "ADMIN" && role !== "PRINCIPAL") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const now = new Date();
  // End of today in local/UTC time to catch all invoices due today or earlier
  const endOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);

  // Fetch all pending / overdue fee invoices due on or before today
  const invoices = await ctx.db.feeInvoice.findMany({
    where: {
      dueDate: { lte: endOfToday },
      status: { in: ["UNPAID", "PARTIALLY_PAID", "OVERDUE"] },
      student: { isActive: true },
    },
    include: {
      student: {
        include: {
          section: {
            include: { class: true },
          },
          parents: {
            include: {
              parent: true,
            },
            orderBy: [{ isPrimary: "desc" }],
          },
        },
      },
      feeStructure: true,
      payments: {
        orderBy: { paidAt: "desc" },
      },
    },
    orderBy: { dueDate: "asc" },
  });

  const alerts = [];

  for (const inv of invoices) {
    const amountDueNum = parseFloat(inv.amountDue.toString());
    const discountNum = parseFloat(inv.discountAmount.toString());
    const totalPaidNum = inv.payments.reduce(
      (sum: number, p: any) => sum + parseFloat(p.amount.toString()),
      0
    );
    const remainingNum = Math.max(0, amountDueNum - totalPaidNum);

    // Only alert if there is an actual remaining balance
    if (remainingNum <= 0) continue;

    // Pick primary parent contact (isPrimary=true prioritized by orderBy, otherwise first linked parent)
    const primaryParentLink = inv.student.parents.find((sp: any) => sp.isPrimary) || inv.student.parents[0];
    const primaryContact = primaryParentLink
      ? {
          name: primaryParentLink.parent.fullName,
          phone: primaryParentLink.parent.phone,
          relationship: primaryParentLink.relationship,
          isPrimary: primaryParentLink.isPrimary,
        }
      : null;

    const dueDateObj = new Date(inv.dueDate);
    const diffTime = now.getTime() - dueDateObj.getTime();
    const daysOverdue = Math.max(0, Math.floor(diffTime / (1000 * 60 * 60 * 24)));

    alerts.push({
      invoiceId: inv.id,
      studentId: inv.student.id,
      studentName: inv.student.fullName,
      admissionNo: inv.student.admissionNo,
      photoUrl: inv.student.photoUrl,
      className: inv.student.section?.class?.name || null,
      sectionName: inv.student.section?.name || null,
      feeDescription: inv.feeStructure.name,
      amountDue: amountDueNum.toFixed(2),
      amountPaid: totalPaidNum.toFixed(2),
      amountRemaining: remainingNum.toFixed(2),
      dueDate: inv.dueDate.toISOString(),
      status: inv.status,
      daysOverdue,
      primaryContact,
    });
  }

  // Ensure sorted by most overdue first
  alerts.sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());

  return NextResponse.json({
    totalAlerts: alerts.length,
    totalOverdueAmount: alerts.reduce((sum, a) => sum + parseFloat(a.amountRemaining), 0).toFixed(2),
    alerts,
  });
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest } from "@/lib/utils";

/**
 * GET /api/assignments
 * Query assignments.
 * Query params: ?sectionId=..., ?subjectId=...
 */
export async function GET(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const { searchParams } = new URL(request.url);
  const sectionId = searchParams.get("sectionId") || "";
  const subjectId = searchParams.get("subjectId") || "";

  const whereClause: any = {};
  if (sectionId) whereClause.sectionId = sectionId;
  if (subjectId) whereClause.subjectId = subjectId;

  // If teacher with no filters, show their own assignments
  if (!sectionId && !subjectId && ctx.session.user.role === "TEACHER") {
    const teacher = await ctx.db.teacher.findUnique({
      where: { userId: ctx.session.user.id },
    });
    if (teacher) {
      whereClause.teacherId = teacher.id;
    }
  }

  const assignments = await ctx.db.assignment.findMany({
    where: whereClause,
    include: {
      section: {
        select: {
          id: true,
          name: true,
          class: { select: { id: true, name: true } },
        },
      },
      subject: { select: { id: true, name: true } },
      teacher: { select: { id: true, fullName: true } },
    },
    orderBy: [
      { dueDate: "asc" },
      { createdAt: "desc" },
    ],
  });

  return NextResponse.json(assignments);
}

/**
 * POST /api/assignments
 * Create a new assignment or study note.
 */
export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (
    ctx.session.user.role !== "ADMIN" &&
    ctx.session.user.role !== "PRINCIPAL" &&
    ctx.session.user.role !== "TEACHER"
  ) {
    return unauthorized();
  }

  const body = await request.json().catch(() => ({}));
  const sectionId = typeof body.sectionId === "string" ? body.sectionId.trim() : "";
  const subjectId = typeof body.subjectId === "string" ? body.subjectId.trim() : "";
  const title = typeof body.title === "string" ? body.title.trim() : "";
  const description = typeof body.description === "string" ? body.description.trim() : "";
  const dueDateStr = typeof body.dueDate === "string" ? body.dueDate.trim() : "";
  const attachmentUrl = typeof body.attachmentUrl === "string" && body.attachmentUrl.trim()
    ? body.attachmentUrl.trim()
    : null;

  if (!sectionId) return badRequest("Section is required");
  if (!subjectId) return badRequest("Subject is required");
  if (!title) return badRequest("Title is required");

  // Determine teacherId
  let teacherId = typeof body.teacherId === "string" ? body.teacherId.trim() : "";
  if (!teacherId && ctx.session.user.role === "TEACHER") {
    const t = await ctx.db.teacher.findUnique({
      where: { userId: ctx.session.user.id },
    });
    if (t) teacherId = t.id;
  }

  if (!teacherId) {
    // If admin creating, use first teacher or HOD or require teacherId
    const firstTeacher = await ctx.db.teacher.findFirst();
    if (firstTeacher) teacherId = firstTeacher.id;
    else return badRequest("A valid teacher is required to associate with the assignment");
  }

  let dueDate: Date | null = null;
  if (dueDateStr) {
    const d = new Date(dueDateStr);
    if (!isNaN(d.getTime())) dueDate = d;
  }

  const assignment = await ctx.db.assignment.create({
    data: {
      sectionId,
      subjectId,
      teacherId,
      title,
      description,
      dueDate,
      attachmentUrl,
    } as any,
    include: {
      section: {
        select: {
          id: true,
          name: true,
          class: { select: { id: true, name: true } },
        },
      },
      subject: { select: { id: true, name: true } },
      teacher: { select: { id: true, fullName: true } },
    },
  });

  return NextResponse.json(assignment, { status: 201 });
}

/**
 * PATCH /api/assignments
 * Update assignment details.
 */
export async function PATCH(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (
    ctx.session.user.role !== "ADMIN" &&
    ctx.session.user.role !== "PRINCIPAL" &&
    ctx.session.user.role !== "TEACHER"
  ) {
    return unauthorized();
  }

  const body = await request.json().catch(() => ({}));
  const id = typeof body.id === "string" ? body.id.trim() : "";
  if (!id) return badRequest("Assignment ID is required");

  const existing = await ctx.db.assignment.findUnique({ where: { id } });
  if (!existing) return badRequest("Assignment not found");

  const updateData: any = {};
  if (typeof body.title === "string" && body.title.trim()) {
    updateData.title = body.title.trim();
  }
  if (typeof body.description === "string") {
    updateData.description = body.description.trim();
  }
  if (body.dueDate !== undefined) {
    if (body.dueDate) {
      const d = new Date(body.dueDate);
      updateData.dueDate = isNaN(d.getTime()) ? null : d;
    } else {
      updateData.dueDate = null;
    }
  }
  if (body.attachmentUrl !== undefined) {
    updateData.attachmentUrl = body.attachmentUrl || null;
  }
  if (typeof body.sectionId === "string" && body.sectionId.trim()) {
    updateData.sectionId = body.sectionId.trim();
  }
  if (typeof body.subjectId === "string" && body.subjectId.trim()) {
    updateData.subjectId = body.subjectId.trim();
  }

  const updated = await ctx.db.assignment.update({
    where: { id },
    data: updateData,
    include: {
      section: {
        select: {
          id: true,
          name: true,
          class: { select: { id: true, name: true } },
        },
      },
      subject: { select: { id: true, name: true } },
      teacher: { select: { id: true, fullName: true } },
    },
  });

  return NextResponse.json(updated);
}

/**
