}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { unauthorized, forbidden } from "@/lib/utils";
import { generateSignedFileUrl, getSecureDownloadUrl } from "@/lib/storage";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user) {
      return unauthorized();
    }

    const { id } = await params;
    if (!id) {
      return NextResponse.json({ error: "Document ID is required" }, { status: 400 });
    }

    const isSuperAdmin = session.user.role === "SUPER_ADMIN";
    const where: any = { id };
    if (!isSuperAdmin) {
      if (!session.user.schoolId) {
        return forbidden();
      }
      where.schoolId = session.user.schoolId;
    }

    const doc = await prisma.document.findFirst({
      where,
    });

    if (!doc) {
      return NextResponse.json({ error: "Document not found" }, { status: 404 });
    }

    // Generate signed download URL valid for 30 minutes (1800s)
    const downloadUrl = await getSecureDownloadUrl(doc.fileKey, 1800);

    const { searchParams } = new URL(request.url);
    if (searchParams.get("redirect") === "true") {
      return NextResponse.redirect(new URL(downloadUrl, request.url));
    }

    return NextResponse.json({
      success: true,
      document: {
        id: doc.id,
        title: doc.title,
        fileName: doc.fileName,
        category: doc.category,
        downloadUrl,
      },
    });
  } catch (error: unknown) {
    console.error("[DOCUMENT_ID_DOWNLOAD] Error:", error);
    return NextResponse.json({ error: "Failed to generate document download link" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest, forbidden, hasRole } from "@/lib/utils";
import { getOrCreateExamSlots } from "@/lib/exam-slots";

/**
 * GET /api/exam-slots?academicYear=2026-27
 * Returns the structured exam slots (UT1, UT2, TERM1, UT3, UT4, TERM2) for the school & academic year.
 * Auto-seeds them if they don't exist yet so teachers never hit a dead end.
 */
export async function GET(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const { searchParams } = new URL(request.url);
  const academicYear = searchParams.get("academicYear") || "2026-27";

  const slots = await getOrCreateExamSlots(ctx.session.user.schoolId, academicYear);

  return NextResponse.json(slots);
}

/**
 * POST /api/exam-slots
 * Creates a new custom exam slot for the school & academic year (e.g. UT5, Practical 1).
 */
export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const rawCode = typeof body.code === "string" ? body.code.trim() : "";
  const rawName = typeof body.name === "string" ? body.name.trim() : "";
  const term = body.term === "TERM2" ? "TERM2" : "TERM1";
  const academicYear = typeof body.academicYear === "string" && body.academicYear.trim() ? body.academicYear.trim() : "2026-27";

  if (!rawCode) {
    return badRequest("Exam slot code is required (e.g. UT5, Practical 1)");
  }

  const cleanCode = rawCode.toUpperCase().replace(/\s+/g, "");
  const displayName = rawName || rawCode;

  // Duplicate check: case-insensitive match for code within the same school & academicYear
  const existing = await ctx.db.examSlot.findFirst({
    where: {
      academicYear,
      code: {
        equals: cleanCode,
        mode: "insensitive",
      },
    },
  });

  if (existing) {
    return badRequest(`An exam slot with code "${existing.code}" already exists for academic year ${academicYear}.`);
  }

  // Determine next order
  const lastSlot = await ctx.db.examSlot.findFirst({
    where: { academicYear },
    orderBy: { order: "desc" },
  });
  const order = (lastSlot?.order ?? 0) + 1;

  // Create slot tenant-scoped
  const newSlot = await ctx.db.examSlot.create({
    data: {
      academicYear,
      term,
      code: cleanCode,
      name: displayName,
      maxScore: 30, // sensible default
      order,
    } as any,
  });

  return NextResponse.json(newSlot, { status: 201 });
}

export async function PATCH(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const id = typeof body.id === "string" ? body.id.trim() : "";
  const rawName = typeof body.name === "string" ? body.name.trim() : "";
  const term = body.term === "TERM2" ? "TERM2" : body.term === "TERM1" ? "TERM1" : undefined;

  if (!id) {
    return badRequest("Exam slot ID is required");
  }

  // Verify slot exists in this tenant
  const current = await ctx.db.examSlot.findUnique({
    where: { id },
  });
  if (!current) {
    return badRequest("Exam slot not found");
  }

  const displayName = rawName || current.name;

  const updateData: any = {
    name: displayName,
  };
  if (term) {
    updateData.term = term;
  }

  const updated = await ctx.db.examSlot.update({
    where: { id },
    data: updateData,
  });

  return NextResponse.json(updated);
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function GET() {
  const startTime = Date.now();
  let dbStatus = "healthy";
  let dbLatency = 0;

  try {
    const pingStart = Date.now();
    await prisma.$queryRaw`SELECT 1`;
    dbLatency = Date.now() - pingStart;
  } catch (error: unknown) {
    dbStatus = "unhealthy";
  }

  const isProd = process.env.NODE_ENV === "production";

  if (isProd) {
    return NextResponse.json(
      {
        status: dbStatus === "healthy" ? "ok" : "degraded",
        timestamp: new Date().toISOString(),
      },
      { status: dbStatus === "healthy" ? 200 : 503 }
    );
  }

  const memoryUsage = process.memoryUsage();

  return NextResponse.json(
    {
      status: dbStatus === "healthy" ? "ok" : "degraded",
      timestamp: new Date().toISOString(),
      uptimeSeconds: Math.floor(process.uptime()),
      database: {
        status: dbStatus,
        latencyMs: dbLatency,
      },
      memory: {
        heapUsedMb: (memoryUsage.heapUsed / 1024 / 1024).toFixed(2),
        heapTotalMb: (memoryUsage.heapTotal / 1024 / 1024).toFixed(2),
        rssMb: (memoryUsage.rss / 1024 / 1024).toFixed(2),
      },
      environment: process.env.NODE_ENV || "development",
      version: "1.0.0",
      responseTimeMs: Date.now() - startTime,
    },
    { status: dbStatus === "healthy" ? 200 : 503 }
  );
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest } from "@/lib/utils";
import { Prisma } from "@prisma/client";
import { BulkInvoiceCreateSchema } from "@/lib/validations";

interface StudentRecord {
  id: string;
  fullName: string;
}

interface ExistingInvoiceRecord {
  studentId: string;
}

export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (
    ctx.session.user.role !== "ACCOUNTANT" &&
    ctx.session.user.role !== "ADMIN" &&
    ctx.session.user.role !== "PRINCIPAL"
  ) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const json = await request.json().catch(() => ({}));
  const parsed = BulkInvoiceCreateSchema.safeParse(json);
  if (!parsed.success) {
    return badRequest(parsed.error.issues[0]?.message || "Invalid bulk invoice data");
  }

  const { feeStructureId, sectionId, classId, dueDate, discountAmount } = parsed.data;

  // Validate feeStructure exists
  const feeStructure = await ctx.db.feeStructure.findUnique({
    where: { id: feeStructureId },
  });
  if (!feeStructure) {
    return badRequest("Fee structure not found");
  }

  // Find target students
  const studentWhere: any = { isActive: true };
  if (sectionId) {
    studentWhere.sectionId = sectionId;
  } else if (classId) {
    studentWhere.section = { classId };
  } else {
    return badRequest("Either sectionId or classId must be provided");
  }

  const students = await ctx.db.student.findMany({
    where: studentWhere,
    select: { id: true, fullName: true },
  });

  if (students.length === 0) {
    return badRequest("No active students found in the selected class/section");
  }

  const discount = new Prisma.Decimal(discountAmount || 0);
  const amountDue = feeStructure.amount.sub(discount);

  if (amountDue.lessThan(0)) {
    return badRequest("Discount cannot exceed fee structure amount");
  }

  const due = new Date(dueDate);

  // Check if invoice for this feeStructure already exists for each student to avoid accidental duplication
  const existingInvoices = (await ctx.db.feeInvoice.findMany({
    where: {
      feeStructureId,
      studentId: { in: (students as StudentRecord[]).map((s: StudentRecord) => s.id) },
    },
    select: { studentId: true },
  })) as ExistingInvoiceRecord[];
  const existingStudentIdSet = new Set(existingInvoices.map((inv: ExistingInvoiceRecord) => inv.studentId));

  const eligibleStudents = (students as StudentRecord[]).filter((s: StudentRecord) => !existingStudentIdSet.has(s.id));
  if (eligibleStudents.length === 0) {
    return badRequest("All students in this section already have an invoice for this fee structure");
  }

  const invoicesData = eligibleStudents.map((s: StudentRecord) => ({
    studentId: s.id,
    feeStructureId,
    amountDue,
    discountAmount: discount,
    dueDate: due,
    status: "UNPAID" as const,
  }));

  const db = ctx.db;
  const result = await (db as any).$transaction(async (tx: any) => {
    return tx.feeInvoice.createMany({
      data: invoicesData,
    });
  });

  return NextResponse.json(
    {
      message: `Successfully created ${result.count} invoice(s)`,
      createdCount: result.count,
      skippedCount: existingInvoices.length,
    },
    { status: 201 }
  );
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest, forbidden, hasRole } from "@/lib/utils";
import { Prisma, Payment } from "@prisma/client";

type InvoiceWithRelations = Prisma.FeeInvoiceGetPayload<{
  include: {
    student: true;
    feeStructure: true;
    payments: true;
  };
}>;

export async function GET(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const role = ctx.session.user.role;
  const { searchParams } = new URL(request.url);
  const status = searchParams.get("status");
  const studentId = searchParams.get("studentId");

  const where: any = {};
  if (status) where.status = status;

  if (role === "PARENT") {
    const parent = await ctx.db.parent.findFirst({
      where: { userId: ctx.session.user.id },
      include: { students: { select: { studentId: true } } },
    });
    const childIds = parent?.students.map((c: any) => c.studentId) || [];

    if (studentId) {
      if (!childIds.includes(studentId)) {
        return forbidden("You can only view invoices for your linked children");
      }
      where.studentId = studentId;
    } else {
      where.studentId = { in: childIds };
    }
  } else if (role === "TEACHER") {
    return forbidden("Teachers cannot access fee invoices");
  } else if (studentId) {
    where.studentId = studentId;
  }

  const invoices = await ctx.db.feeInvoice.findMany({
    where,
    include: {
      student: true,
      feeStructure: true,
      payments: { orderBy: { paidAt: "desc" } },
    },
    orderBy: { dueDate: "desc" },
  });

  // Serialize Decimals to strings
  const serialized = (invoices as InvoiceWithRelations[]).map((inv: InvoiceWithRelations) => ({
    ...inv,
    amountDue: inv.amountDue.toFixed(2),
    discountAmount: inv.discountAmount.toFixed(2),
    feeStructure: {
      ...inv.feeStructure,
      amount: inv.feeStructure.amount.toFixed(2),
    },
    payments: inv.payments.map((p: Payment) => ({
      ...p,
      amount: p.amount.toFixed(2),
    })),
  }));

  return NextResponse.json(serialized);
}

export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL", "ACCOUNTANT"])) {
    return forbidden();
  }

  const body = await request.json();
  const { studentId, feeStructureId, discountAmount, dueDate } = body;

  if (!studentId || !feeStructureId || !dueDate) {
    return badRequest("studentId, feeStructureId, and dueDate are required");
  }

  // Verify student belongs to this school
  const student = await ctx.db.student.findUnique({
    where: { id: studentId },
  });
  if (!student) {
    return badRequest("Student not found in this school");
  }

  // Fetch fee structure to get amount — using Decimal arithmetic
  const feeStructure = await ctx.db.feeStructure.findFirst({
    where: { id: feeStructureId },
  });

  if (!feeStructure) {
    return badRequest("Fee structure not found");
  }

  const discount = new Prisma.Decimal(discountAmount || 0);
  const amountDue = feeStructure.amount.sub(discount);

  if (amountDue.lessThan(0)) {
    return badRequest("Discount cannot exceed fee amount");
  }

  const invoice = await ctx.db.feeInvoice.create({
    data: {
      studentId,
      feeStructureId,
      amountDue,
      discountAmount: discount,
      dueDate: new Date(dueDate),
    } as any,
    include: { student: true, feeStructure: true },
  });

  return NextResponse.json(
    {
      ...invoice,
      amountDue: invoice.amountDue.toFixed(2),
      discountAmount: invoice.discountAmount.toFixed(2),
    },
    { status: 201 }
  );
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest, forbidden, hasRole } from "@/lib/utils";

/**
 * GET /api/leave
 * - For TEACHER / ACCOUNTANT: Returns their own leave requests.
 * - For ADMIN / PRINCIPAL: Returns all school leave requests (optional ?status= filter).
 * - For PARENT: Forbidden (no staff leave access).
 */
export async function GET(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const role = ctx.session.user.role;
  if (role === "PARENT") {
    return forbidden("Parents cannot access staff leave records");
  }

  const { searchParams } = new URL(request.url);
  const status = searchParams.get("status") || "";
  const isStaff = role === "TEACHER" || role === "ACCOUNTANT";

  const whereClause: any = {};
  if (isStaff) {
    whereClause.userId = ctx.session.user.id;
  }
  if (status && ["PENDING", "APPROVED", "REJECTED"].includes(status.toUpperCase())) {
    whereClause.status = status.toUpperCase();
  }

  const requests = await ctx.db.leaveRequest.findMany({
    where: whereClause,
    include: {
      user: {
        select: {
          id: true,
          email: true,
          role: true,
          teacherProfile: { select: { fullName: true } },
        },
      },
      approvedByUser: {
        select: { id: true, email: true },
      },
    },
    orderBy: { createdAt: "desc" },
  });

  return NextResponse.json(requests);
}

/**
 * POST /api/leave
 * Staff submits a new leave request.
 */
export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (ctx.session.user.role === "PARENT") {
    return forbidden("Parents cannot submit staff leave requests");
  }

  const body = await request.json().catch(() => ({}));
  const leaveType = typeof body.leaveType === "string" ? body.leaveType.trim() : "Casual";
  const startDate = typeof body.startDate === "string" ? body.startDate.trim() : "";
  const endDate = typeof body.endDate === "string" ? body.endDate.trim() : "";
  const reason = typeof body.reason === "string" ? body.reason.trim() : "";

  if (!startDate || !endDate) return badRequest("Start and end dates are required");
  if (!reason) return badRequest("Reason for leave is required");

  const start = new Date(startDate);
  const end = new Date(endDate);
  if (isNaN(start.getTime()) || isNaN(end.getTime())) {
    return badRequest("Invalid start or end date");
  }
  if (start > end) {
    return badRequest("Start date cannot be after end date");
  }

  const leave = await ctx.db.leaveRequest.create({
    data: {
      userId: ctx.session.user.id,
      leaveType,
      startDate: start,
      endDate: end,
      reason,
      status: "PENDING",
    } as any,
    include: {
      user: {
        select: {
          id: true,
          email: true,
          role: true,
          teacherProfile: { select: { fullName: true } },
        },
      },
    },
  });

  return NextResponse.json(leave, { status: 201 });
}

/**
 * PATCH /api/leave
 * Admin / Principal reviews (approves/rejects) a leave request.
 */
export async function PATCH(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const id = typeof body.id === "string" ? body.id.trim() : "";
  const status = typeof body.status === "string" ? body.status.trim().toUpperCase() : "";
  const adminRemark = typeof body.adminRemark === "string" ? body.adminRemark.trim() : null;

  if (!id) return badRequest("Leave request ID is required");
  if (!["APPROVED", "REJECTED", "PENDING"].includes(status)) {
    return badRequest("Status must be APPROVED, REJECTED, or PENDING");
  }

  const existing = await ctx.db.leaveRequest.findUnique({ where: { id } });
  if (!existing) return badRequest("Leave request not found");

  const updated = await ctx.db.leaveRequest.update({
    where: { id },
    data: {
      status,
      adminRemark,
      approvedByUserId: ctx.session.user.id,
    } as any,
    include: {
      user: {
        select: {
          id: true,
          email: true,
          role: true,
          teacherProfile: { select: { fullName: true } },
        },
      },
      approvedByUser: {
        select: { id: true, email: true },
      },
    },
  });

  return NextResponse.json(updated);
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";

function verifyNexusApiKey(request: Request): boolean {
  const configuredKey = process.env.NEXUS_API_KEY || "nexus-dev-master-api-key";
  const authHeader = request.headers.get("authorization");
  const nexusHeader = request.headers.get("x-nexus-api-key");

  let providedKey: string | null = null;
  if (nexusHeader) {
    providedKey = nexusHeader;
  } else if (authHeader && authHeader.toLowerCase().startsWith("bearer ")) {
    providedKey = authHeader.substring(7).trim();
  }

  if (!providedKey) return false;
  return providedKey === configuredKey;
}

export async function GET(request: Request) {
  try {
    if (!verifyNexusApiKey(request)) {
      return NextResponse.json(
        { success: false, error: "Unauthorized: Invalid or missing NEXUS API Key", code: "NEXUS_UNAUTHORIZED" },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status");
    const search = searchParams.get("search");
    const page = Math.max(1, parseInt(searchParams.get("page") || "1", 10));
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get("limit") || "25", 10)));
    const skip = (page - 1) * limit;

    const where: any = {};
    if (status && status !== "ALL") {
      where.status = status;
    }
    if (search) {
      where.OR = [
        { name: { contains: search, mode: "insensitive" } },
        { affiliationNumber: { contains: search, mode: "insensitive" } },
        { email: { contains: search, mode: "insensitive" } },
      ];
    }

    const [total, schools] = await Promise.all([
      prisma.school.count({ where }),
      prisma.school.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: "desc" },
        include: {
          subscription: {
            include: { plan: true },
          },
          _count: {
            select: { students: true, users: true },
          },
        },
      }),
    ]);

    const formatted = schools.map((s) => ({
      id: s.id,
      name: s.name,
      affiliationNumber: s.affiliationNumber,
      email: s.email,
      phone: s.phone,
      address: s.address,
      status: s.status,
      isActive: s.isActive,
      studentCount: s._count.students,
      userCount: s._count.users,
      createdAt: s.createdAt,
      subscription: s.subscription
        ? {
            id: s.subscription.id,
            status: s.subscription.status,
            planName: s.subscription.plan?.name || "Trial",
            trialEndsAt: s.subscription.trialEndsAt,
            currentPeriodEnd: s.subscription.currentPeriodEnd,
            isExpired:
              s.subscription.status === "EXPIRED" ||
              (s.subscription.trialEndsAt && new Date(s.subscription.trialEndsAt) < new Date()),
          }
        : null,
    }));

    return NextResponse.json({
      success: true,
      data: formatted,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit) || 1,
      },
    });
  } catch (error: unknown) {
    console.error("[NEXUS_API_SCHOOLS] Error:", error);
    return NextResponse.json(
      { success: false, error: "Internal server error querying NEXUS schools", code: "NEXUS_INTERNAL_ERROR" },
      { status: 500 }
    );
  }
}

