import { NextRequest, NextResponse } from "next/server";
import { getTenantDb, unauthorized } from "@/lib/utils";
import { notificationDispatcher } from "@/lib/notifications";
import { checkRateLimit } from "@/lib/rateLimit";
import { z } from "zod";
import { Prisma } from "@prisma/client";

const sendNotificationSchema = z.object({
  channel: z.enum(["WHATSAPP", "SMS", "EMAIL"]),
  audience: z.enum(["ALL_PARENTS", "FEE_DEFAULTERS", "ABSENTEES_TODAY", "CLASS_SECTION", "STAFF"]),
  classId: z.string().optional(),
  sectionId: z.string().optional(),
  template: z.string().min(5, "Template must be at least 5 characters"),
});

export async function POST(req: NextRequest) {
  try {
    const ctx = await getTenantDb();
    if (!ctx) return unauthorized();

    if (
      ctx.session.user.role !== "ADMIN" &&
      ctx.session.user.role !== "PRINCIPAL"
    ) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    // Rate limit: max 10 broadcast attempts per minute per admin
    const rateCheck = checkRateLimit(`broadcast:${ctx.session.user.id}`, 10, 60 * 1000);
    if (!rateCheck.allowed) {
      return NextResponse.json(
        { error: "Broadcast rate limit exceeded. Please wait a minute before sending another batch." },
        { status: 429 }
      );
    }

    const body = await req.json();
    const parsed = sendNotificationSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { channel, audience, classId, sectionId, template } = parsed.data;

    // Fetch school info
    const school = await ctx.db.school.findUnique({
      where: { id: ctx.session.user.schoolId },
      select: { name: true },
    });

    const recipients: Array<{
      phone: string;
      email?: string;
      studentName?: string;
      parentName?: string;
      variables?: Record<string, string>;
    }> = [];

    if (audience === "FEE_DEFAULTERS") {
      // Find students with UNPAID or OVERDUE invoices
      const pendingInvoices = await ctx.db.feeInvoice.findMany({
        where: {
          status: { in: ["UNPAID", "PARTIALLY_PAID", "OVERDUE"] },
        },
        include: {
          student: {
            include: {
              parents: { include: { parent: true } },
            },
          },
          feeStructure: true,
          payments: true,
        },
      });

      for (const inv of pendingInvoices) {
        const student = inv.student;
        const parent = student.parents?.[0]?.parent;
        const phone = parent?.phone || student.emergencyContactPhone;

        let totalPaid = new Prisma.Decimal(0);
        for (const p of inv.payments) {
          totalPaid = totalPaid.add(p.amount);
        }
        const dueAmount = inv.amountDue.sub(totalPaid).toNumber();

        if (phone) {
          recipients.push({
            phone,
            studentName: student.fullName,
            parentName: parent?.fullName || "Parent",
            variables: {
              fee_name: inv.feeStructure.name,
              due_amount: `₹${dueAmount.toLocaleString("en-IN")}`,
              due_date: new Date(inv.dueDate).toLocaleDateString("en-IN"),
            },
          });
        }
      }
    } else if (audience === "ABSENTEES_TODAY") {
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const absentees = await ctx.db.attendance.findMany({
        where: {
          date: today,
          status: "ABSENT",
        },
        include: {
          student: {
            include: {
              parents: { include: { parent: true } },
            },
          },
        },
      });

      for (const record of absentees) {
        const student = record.student;
        const parent = student.parents?.[0]?.parent;
        const phone = parent?.phone || student.emergencyContactPhone;

        if (phone) {
          recipients.push({
            phone,
            studentName: student.fullName,
            parentName: parent?.fullName || "Parent",
            variables: {
              date: new Date().toLocaleDateString("en-IN"),
            },
          });
        }
      }
    } else {
      // CLASS_SECTION or ALL_PARENTS
      const whereClause: any = { isActive: true };
      if (sectionId) {
        whereClause.sectionId = sectionId;
      } else if (classId) {
        whereClause.section = { classId };
      }

      const students = await ctx.db.student.findMany({
        where: whereClause,
        include: {
          parents: { include: { parent: true } },
        },
      });

      for (const student of students) {
        const parent = student.parents?.[0]?.parent;
        const phone = parent?.phone || student.emergencyContactPhone;
        if (phone) {
          recipients.push({
            phone,
            studentName: student.fullName,
            parentName: parent?.fullName || "Parent",
          });
        }
      }
    }

    if (recipients.length === 0) {
      return NextResponse.json(
        { error: "No matching recipients with phone numbers found for the selected audience." },
        { status: 400 }
      );
    }

    const dispatchResult = await notificationDispatcher.dispatch({
      channel,
      recipients,
      template,
      senderName: school?.name || "School Administration",
    });

    const isAllFailed = dispatchResult.successful === 0 && dispatchResult.failed > 0;
    return NextResponse.json({
      success: !isAllFailed,
      message: dispatchResult.simulated > 0
        ? `Development Sandbox: Simulated ${dispatchResult.simulated} notification(s) via ${channel}.`
        : `Dispatched ${dispatchResult.successful} out of ${dispatchResult.total} notifications via ${channel}.`,
      result: dispatchResult,
    }, { status: isAllFailed ? 502 : 200 });
  } catch (error) {
    console.error("Send notification error:", error);
    return NextResponse.json({ error: "Failed to dispatch notifications" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { logAuditEvent } from "@/lib/audit";
import { unauthorized } from "@/lib/utils";

export async function GET() {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || session.user.role !== "PARENT") {
      return unauthorized();
    }

    // Find all parent profiles belonging to this user
    const parents = await prisma.parent.findMany({
      where: { userId: session.user.id },
      select: { id: true },
    });

    const parentIds = parents.map((p) => p.id);

    const requests = await prisma.parentStudentLinkRequest.findMany({
      where: {
        parentId: { in: parentIds },
      },
      include: {
        school: { select: { id: true, name: true } },
        student: { select: { id: true, fullName: true, admissionNo: true } },
      },
      orderBy: { requestedAt: "desc" },
    });

    return NextResponse.json({ success: true, requests });
  } catch (error: unknown) {
    console.error("[PARENT_LINK_REQUESTS] Error fetching requests:", error);
    return NextResponse.json(
      { error: "Failed to retrieve student link requests" },
      { status: 500 }
    );
  }
}

export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || session.user.role !== "PARENT") {
      return unauthorized();
    }

    const body = await request.json();
    const { schoolId, admissionNo, studentDob, relationship = "Parent", notes } = body;

    if (!schoolId || !admissionNo) {
      return NextResponse.json(
        { error: "School and student admission number are required" },
        { status: 400 }
      );
    }

    const cleanSchoolId = schoolId.trim();
    const cleanAdmissionNo = admissionNo.trim();

    // Verify school
    const school = await prisma.school.findUnique({
      where: { id: cleanSchoolId },
    });

    if (!school || !school.isActive) {
      return NextResponse.json(
        { error: "Target school not found or is currently inactive" },
        { status: 404 }
      );
    }

    // Find student in school
    const student = await prisma.student.findFirst({
      where: {
        schoolId: cleanSchoolId,
        admissionNo: cleanAdmissionNo,
        isActive: true,
      },
    });

    if (!student) {
      return NextResponse.json(
        { error: "No active student found matching this admission number in the selected school" },
        { status: 404 }
      );
    }

    // Ensure Parent record exists for this user in this school
    let parent = await prisma.parent.findFirst({
      where: {
        schoolId: cleanSchoolId,
        userId: session.user.id,
      },
    });

    if (!parent) {
      parent = await prisma.parent.create({
        data: {
          schoolId: cleanSchoolId,
          userId: session.user.id,
          fullName: session.user.name || "Parent",
          email: session.user.email,
          phone: (session.user as any).phone || "",
        },
      });
    }

    // Check if already linked
    const existingLink = await prisma.studentParent.findUnique({
      where: {
        studentId_parentId: {
          studentId: student.id,
          parentId: parent.id,
        },
      },
    });

    if (existingLink) {
      return NextResponse.json(
        { error: "This student is already linked to your parent account" },
        { status: 409 }
      );
    }

    // Check if pending request exists
    const existingRequest = await prisma.parentStudentLinkRequest.findFirst({
      where: {
        parentId: parent.id,
        schoolId: cleanSchoolId,
        studentId: student.id,
        status: "PENDING",
      },
    });

    if (existingRequest) {
      return NextResponse.json(
        { error: "A link request for this student is already pending school administrator review" },
        { status: 409 }
      );
    }

    const linkRequest = await prisma.parentStudentLinkRequest.create({
      data: {
        parentId: parent.id,
        schoolId: cleanSchoolId,
        studentId: student.id,
        relationship: relationship || "GUARDIAN",
        proofDocumentUrl: notes || null,
        status: "PENDING",
      },
      include: {
        student: { select: { fullName: true } },
      },
    });

    // Notify School Administrators
    const schoolAdmins = await prisma.user.findMany({
      where: {
        schoolId: cleanSchoolId,
        role: { in: ["ADMIN", "PRINCIPAL"] },
        isActive: true,
      },
      select: { id: true },
    });

    if (schoolAdmins.length > 0) {
      await prisma.notification.createMany({
        data: schoolAdmins.map((admin) => ({
          schoolId: cleanSchoolId,
          userId: admin.id,
          title: "New Student Link Request",
          message: `${session.user.name || "A parent"} requested to link with student ${student.fullName} (Adm: ${cleanAdmissionNo}).`,
          type: "REGISTRATION",
          linkUrl: "/admin/parent-links",
        })),
      });
    }

    await logAuditEvent({
      schoolId: cleanSchoolId,
      userId: session.user.id,
      userEmail: session.user.email,
      action: "PARENT_LINK_REQUEST_SUBMITTED",
      targetType: "ParentStudentLinkRequest",
      targetId: linkRequest.id,
      details: {
        admissionNo: cleanAdmissionNo,
        studentId: student.id,
        studentName: student.fullName,
      },
    });

    return NextResponse.json({
      success: true,
      message: "Student link request submitted successfully. School office will review and approve.",
      request: linkRequest,
    });
  } catch (error: unknown) {
    console.error("[PARENT_LINK_REQUESTS] Error submitting link request:", error);
    return NextResponse.json(
      { error: "Failed to submit student link request" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { unauthorized } from "@/lib/utils";
import { tenantClient } from "@/lib/tenant";
import prisma from "@/lib/prisma";
import { Payment } from "@prisma/client";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getServerSession(authOptions);
  if (!session?.user || session.user.role !== "PARENT") return unauthorized();

  const { id: studentId } = await params;
  if (!studentId) {
    return NextResponse.json({ error: "Student ID is required" }, { status: 400 });
  }

  // Find verified parent profile linked to this user and student
  const verifiedLink = await prisma.studentParent.findFirst({
    where: {
      studentId,
      parent: {
        userId: session.user.id,
      },
    },
    include: {
      student: { select: { schoolId: true, isActive: true } },
      parent: {
        include: {
          school: { select: { id: true, isActive: true, status: true } },
        },
      },
    },
  });

  if (!verifiedLink || !verifiedLink.parent?.school) {
    return NextResponse.json({ error: "Student not found or access denied" }, { status: 404 });
  }

  // Immediate suspension check on the student's school
  if (!verifiedLink.parent.school.isActive || verifiedLink.parent.school.status === "SUSPENDED") {
    return NextResponse.json(
      { error: "Access suspended for this school institution" },
      { status: 403 }
    );
  }

  // Tenant-scoped database query using the verified student's schoolId
  const db = tenantClient(verifiedLink.parent.schoolId);
  const invoices = await db.feeInvoice.findMany({
    where: { studentId },
    include: {
      feeStructure: true,
      payments: { orderBy: { paidAt: "desc" } },
    },
    orderBy: { dueDate: "desc" },
  });

  const serialized = invoices.map((inv: any) => ({
    ...inv,
    amountDue: inv.amountDue.toFixed(2),
    discountAmount: inv.discountAmount.toFixed(2),
    feeStructure: { ...inv.feeStructure, amount: inv.feeStructure.amount.toFixed(2) },
    payments: inv.payments.map((p: Payment) => ({ ...p, amount: p.amount.toFixed(2) })),
  }));

  return NextResponse.json(serialized);
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { unauthorized } from "@/lib/utils";
import prisma from "@/lib/prisma";

/**
 * GET: Returns all students linked to the current parent user.
 * Supports multi-school parents:
 * - Gathers children across all schools where the parent has a verified Parent profile.
 * - Displays each child's school name and affiliation.
 * - Only includes active, verified relationships.
 * - Filters out any suspended or inactive schools.
 */
export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session?.user || session.user.role !== "PARENT") {
    return unauthorized();
  }

  try {
    // Query all parent profiles linked to this authenticated user across all schools
    const parentProfiles = await prisma.parent.findMany({
      where: { userId: session.user.id },
      include: {
        school: {
          select: {
            id: true,
            name: true,
            isActive: true,
            status: true,
          },
        },
        students: {
          include: {
            student: {
              include: {
                section: {
                  include: { class: true },
                },
              },
            },
          },
        },
      },
    });

    if (!parentProfiles || parentProfiles.length === 0) {
      return NextResponse.json([]);
    }

    // Filter out inactive or suspended schools
    const activeProfiles = parentProfiles.filter(
      (p) => p.school && p.school.isActive && p.school.status !== "SUSPENDED"
    );

    const studentsList: any[] = [];
    for (const profile of activeProfiles) {
      for (const sp of profile.students) {
        if (sp.student && sp.student.isActive) {
          studentsList.push({
            id: sp.student.id,
            fullName: sp.student.fullName,
            admissionNo: sp.student.admissionNo,
            academicYear: sp.student.academicYear,
            photoUrl: sp.student.photoUrl,
            relationship: sp.relationship,
            isPrimary: sp.isPrimary,
            schoolId: profile.school.id,
            schoolName: profile.school.name,
            section: sp.student.section
              ? {
                  id: sp.student.section.id,
                  name: sp.student.section.name,
                  class: {
                    id: sp.student.section.class.id,
                    name: sp.student.section.class.name,
                  },
                }
              : null,
          });
        }
      }
    }

    return NextResponse.json(studentsList);
  } catch (error: unknown) {
    console.error("[PARENT_STUDENTS] Error fetching linked students:", error);
    return NextResponse.json({ error: "Failed to load linked students" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { logAuditEvent } from "@/lib/audit";
import { unauthorized, forbidden } from "@/lib/utils";

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || !session.user.schoolId) {
      return unauthorized();
    }

    if (!["ADMIN", "ACCOUNTANT", "SUPER_ADMIN"].includes(session.user.role)) {
      return forbidden();
    }

    const { schoolId } = session.user;
    const { id } = await params;

    if (!id) {
      return NextResponse.json({ error: "Payment ID is required" }, { status: 400 });
    }

    const body = await request.json().catch(() => ({}));
    const reason = body.reason || "Fee payment refund initiated by accounts office.";
    const refundAmount = body.amount ? Number(body.amount) : null;

    const payment = await prisma.payment.findFirst({
      where: { id, schoolId },
      include: {
        invoice: {
          include: {
            student: true,
          },
        },
      },
    });

    if (!payment) {
      return NextResponse.json({ error: "Payment record not found in this school" }, { status: 404 });
    }

    const maxRefundable = Number(payment.amount);
    const amountToRefund = refundAmount ? Math.min(refundAmount, maxRefundable) : maxRefundable;

    if (amountToRefund <= 0) {
      return NextResponse.json({ error: "Refund amount must be greater than 0" }, { status: 400 });
    }

    // Process Razorpay API refund if gateway reference exists
    let gatewayRefundId: string | null = null;
    if (payment.gatewayRef && process.env.RAZORPAY_KEY_ID && process.env.RAZORPAY_KEY_SECRET) {
      try {
        const authHeader = Buffer.from(
          `${process.env.RAZORPAY_KEY_ID}:${process.env.RAZORPAY_KEY_SECRET}`
        ).toString("base64");

        const rzpRes = await fetch(
          `https://api.razorpay.com/v1/payments/${payment.gatewayRef}/refund`,
          {
            method: "POST",
            headers: {
              Authorization: `Basic ${authHeader}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              amount: Math.round(amountToRefund * 100), // paise
              notes: {
                reason,
                schoolId,
                paymentId: payment.id,
                invoiceId: payment.invoiceId,
              },
            }),
          }
        );

        if (rzpRes.ok) {
          const rzpData = await rzpRes.json();
          gatewayRefundId = rzpData.id;
        }
      } catch (err) {
        console.warn("[PAYMENT_REFUND] Razorpay online refund API call failed, recording ledger refund:", err);
      }
    }

    // Update payment record or generate negative refund transaction
    const refundReceipt = `REF-${Date.now()}-${Math.floor(1000 + Math.random() * 9000)}`;

    await prisma.$transaction(async (tx) => {
      // Create negative adjustment payment to keep historical receipt intact
      await tx.payment.create({
        data: {
          schoolId,
          invoiceId: payment.invoiceId,
          amount: -amountToRefund,
          method: "REFUND",
          gatewayRef: gatewayRefundId || `REF-${payment.id}`,
          receiptNumber: refundReceipt,
        },
      });

      // Recalculate invoice status
      const allPayments = await tx.payment.findMany({
        where: { invoiceId: payment.invoiceId },
      });
      const netPaid = allPayments.reduce((sum, p) => sum + Number(p.amount), 0);
      const invoiceAmount = Number(payment.invoice.amountDue);

      let newStatus: any = "UNPAID";
      if (netPaid >= invoiceAmount) newStatus = "PAID";
      else if (netPaid > 0) newStatus = "PARTIALLY_PAID";

      await tx.feeInvoice.update({
        where: { id: payment.invoiceId },
        data: { status: newStatus },
      });

      // Notify parents of the student
      const studentParents = await tx.studentParent.findMany({
        where: { studentId: payment.invoice.studentId },
        include: { parent: true },
      });

      for (const sp of studentParents) {
        if (sp.parent?.userId) {
          await tx.notification.create({
            data: {
              schoolId,
              userId: sp.parent.userId,
              title: "Fee Payment Refund Processed",
              message: `A refund of INR ${amountToRefund.toFixed(2)} for receipt ${payment.receiptNumber} has been processed: ${reason}`,
              type: "PAYMENT",
              linkUrl: `/parent/fees`,
            },
          });
        }
      }
    });

    // Audit Log
    await logAuditEvent({
      schoolId,
      userId: session.user.id,
      userEmail: session.user.email,
      action: "PAYMENT_REFUNDED",
      targetType: "Payment",
      targetId: payment.id,
      details: {
        refundAmount: amountToRefund,
        originalAmount: Number(payment.amount),
        receiptNumber: payment.receiptNumber,
        refundReceipt,
        reason,
        gatewayRefundId,
      },
    });

    return NextResponse.json({
      success: true,
      message: `Successfully processed refund of INR ${amountToRefund.toFixed(2)}.`,
      refundReceipt,
    });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : "Failed to process payment refund";
    console.error("[PAYMENT_REFUND_ERROR] Error:", error);
    return NextResponse.json(
      { error: errorMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest } from "@/lib/utils";
import { razorpayService } from "@/lib/razorpay";
import { checkRateLimit } from "@/lib/rateLimit";
import { z } from "zod";
import { Prisma } from "@prisma/client";

const createOrderSchema = z.object({
  invoiceId: z.string().min(1, "Invoice ID is required"),
  amount: z.number().positive("Amount must be positive"),
});

export async function POST(req: NextRequest) {
  try {
    const ctx = await getTenantDb();
    if (!ctx) return unauthorized();

    // Rate limit: max 15 payment orders per minute per user
    const rateCheck = checkRateLimit(`order:${ctx.session.user.id}`, 15, 60 * 1000);
    if (!rateCheck.allowed) {
      return NextResponse.json(
        { error: "Too many payment attempts. Please wait a minute before trying again." },
        { status: 429 }
      );
    }

    const body = await req.json();
    const parsed = createOrderSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { invoiceId, amount } = parsed.data;

    // Verify invoice belongs to tenant
    const invoice = await ctx.db.feeInvoice.findUnique({
      where: { id: invoiceId },
      include: {
        student: true,
        feeStructure: true,
        payments: true,
      },
    });

    if (!invoice) {
      return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
    }

    let totalPaid = new Prisma.Decimal(0);
    for (const p of invoice.payments) {
      totalPaid = totalPaid.add(p.amount);
    }

    const remainingDue = invoice.amountDue.sub(totalPaid).toNumber();
    if (amount > remainingDue) {
      return NextResponse.json(
        { error: `Amount ₹${amount} exceeds remaining balance of ₹${remainingDue}` },
        { status: 400 }
      );
    }

    // Convert INR to Paise
    const amountInPaise = Math.round(amount * 100);
    const receipt = `RCP_${invoice.id.slice(-6)}_${Date.now().toString().slice(-4)}`;

    const order = await razorpayService.createOrder({
      amountInPaise,
      currency: "INR",
      receipt,
      notes: {
        schoolId: ctx.session.user.schoolId,
        invoiceId: invoice.id,
        studentName: invoice.student.fullName,
        admissionNo: invoice.student.admissionNo,
      },
    });

    return NextResponse.json({
      success: true,
      orderId: order.id,
      amount: order.amount,
      currency: order.currency,
      keyId: order.keyId,
      receipt: order.receipt,
      isMock: order.isMock,
      invoice: {
        id: invoice.id,
        studentName: invoice.student.fullName,
        feeType: invoice.feeStructure.name,
      },
    });
  } catch (error) {
    console.error("Create Razorpay order error:", error);
    return NextResponse.json({ error: "Failed to create payment order" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getTenantDb, unauthorized } from "@/lib/utils";
import { razorpayService } from "@/lib/razorpay";
import { calculateInvoiceStatus } from "@/lib/invoiceStatus";
import { z } from "zod";
import { Prisma } from "@prisma/client";

const verifyPaymentSchema = z.object({
  orderId: z.string().min(1),
  paymentId: z.string().min(1),
  signature: z.string().min(1),
  invoiceId: z.string().min(1),
  amount: z.number().positive(),
});

export async function POST(req: NextRequest) {
  try {
    const ctx = await getTenantDb();
    if (!ctx) return unauthorized();

    const body = await req.json();
    const parsed = verifyPaymentSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { orderId, paymentId, signature, invoiceId, amount } = parsed.data;
    const gatewayRef = `${orderId}|${paymentId}`;

    // Verify cryptographic signature
    const isValid = razorpayService.verifyPaymentSignature({
      orderId,
      paymentId,
      signature,
    });

    if (!isValid) {
      return NextResponse.json(
        { error: "Invalid payment signature verification failed" },
        { status: 400 }
      );
    }

    // Check gatewayRef idempotency before proceeding
    const existingPayment = await ctx.db.payment.findFirst({
      where: { gatewayRef },
      include: { invoice: true },
    });

    if (existingPayment) {
      return NextResponse.json({
        success: true,
        message: "Payment already verified and recorded",
        payment: existingPayment,
        invoice: existingPayment.invoice,
        alreadyProcessed: true,
      });
    }

    // Verify invoice in tenant DB
    const invoice = await ctx.db.feeInvoice.findUnique({
      where: { id: invoiceId },
    });

    if (!invoice) {
      return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
    }

    // If caller is PARENT, verify they own the child linked to this invoice
    if (ctx.session.user.role === "PARENT") {
      const parent = await ctx.db.parent.findFirst({
        where: { userId: ctx.session.user.id },
        include: { students: { select: { studentId: true } } },
      });
      const childIds = parent?.students.map((c: any) => c.studentId) || [];
      if (!childIds.includes(invoice.studentId)) {
        return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
      }
    }

    const paymentAmount = new Prisma.Decimal(amount);
    const receiptNumber = `ONLINE-REC-${Date.now()}-${Math.floor(1000 + Math.random() * 9000)}`;

    // Execute payment record and invoice update in tenant transaction with atomic balance re-calculation
    const result = await (ctx.db as any).$transaction(async (tx: any) => {
      // Re-verify idempotency inside transaction
      const existingInTx = await tx.payment.findFirst({
        where: { gatewayRef },
      });
      if (existingInTx) {
        return { payment: existingInTx, invoice, alreadyProcessed: true };
      }

      // Read current payments inside transaction
      const currentPayments = await tx.payment.findMany({
        where: { invoiceId: invoice.id },
      });

      let totalPaid = new Prisma.Decimal(0);
      for (const p of currentPayments) {
        totalPaid = totalPaid.add(p.amount);
      }
      totalPaid = totalPaid.add(paymentAmount);

      const newStatus = calculateInvoiceStatus(invoice.amountDue, totalPaid);

      const payment = await tx.payment.create({
        data: {
          invoiceId: invoice.id,
          amount: paymentAmount,
          method: "ONLINE",
          receiptNumber,
          gatewayRef,
          paidAt: new Date(),
        },
      });

      const updatedInvoice = await tx.feeInvoice.update({
        where: { id: invoice.id },
        data: {
          status: newStatus,
        },
      });

      return { payment, invoice: updatedInvoice };
    });

    return NextResponse.json({
      success: true,
      message: "Payment verified and recorded successfully",
      payment: result.payment,
      invoice: result.invoice,
    });
  } catch (error) {
    console.error("Verify Razorpay payment error:", error);
    return NextResponse.json({ error: "Failed to process payment verification" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest, forbidden, hasRole } from "@/lib/utils";
import { z } from "zod";

const PeriodInputSchema = z.object({
  label: z.string().min(1, "Period label is required").max(50),
  startTime: z.string().min(1, "Start time is required"),
  endTime: z.string().min(1, "End time is required"),
  isBreak: z.boolean().optional(),
});

/**
 * GET /api/periods
 * Returns all periods for the school, ordered by periodNumber.
 */
export async function GET() {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const periods = await ctx.db.period.findMany({
    orderBy: { periodNumber: "asc" },
  });

  return NextResponse.json(periods);
}

/**
 * POST /api/periods
 * Create a new period.
 */
export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const parsed = PeriodInputSchema.safeParse(body);
  if (!parsed.success) {
    return badRequest(parsed.error.issues[0]?.message || "Invalid period data");
  }

  const { label, startTime, endTime, isBreak } = parsed.data;

  // Auto-assign next periodNumber
  const last = await ctx.db.period.findFirst({
    orderBy: { periodNumber: "desc" },
  });
  const periodNumber = (last?.periodNumber ?? 0) + 1;

  const period = await ctx.db.period.create({
    data: {
      periodNumber,
      label,
      startTime,
      endTime,
      isBreak,
    } as any,
  });

  return NextResponse.json(period, { status: 201 });
}

/**
 * PATCH /api/periods
 * Update an existing period.
 */
export async function PATCH(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const id = typeof body.id === "string" ? body.id.trim() : "";
  if (!id) return badRequest("Period ID is required");

  const existing = await ctx.db.period.findUnique({ where: { id } });
  if (!existing) return badRequest("Period not found");

  const updateData: any = {};
  if (typeof body.label === "string") updateData.label = body.label.trim();
  if (typeof body.startTime === "string") updateData.startTime = body.startTime.trim();
  if (typeof body.endTime === "string") updateData.endTime = body.endTime.trim();
  if (typeof body.isBreak === "boolean") updateData.isBreak = body.isBreak;

  const updated = await ctx.db.period.update({
    where: { id },
    data: updateData,
  });

  return NextResponse.json(updated);
}

/**
 * DELETE /api/periods
 * Delete a period (also cascades timetable slot references — careful).
 */
export async function DELETE(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const { searchParams } = new URL(request.url);
  const id = searchParams.get("id") || "";
  if (!id) return badRequest("Period ID is required");

  const existing = await ctx.db.period.findUnique({ where: { id } });
  if (!existing) return badRequest("Period not found");

  // Delete related timetable slots first
  await ctx.db.timetableSlot.deleteMany({ where: { periodId: id } });
  await ctx.db.period.delete({ where: { id } });

  return NextResponse.json({ success: true });
}

