      phone: true,
      email: true,
      website: true,
      logoUrl: true,
      principalName: true,
      affiliationNumber: true,
      establishedYear: true,
      trustName: true,
      term1StartDate: true,
      term1EndDate: true,
      term2StartDate: true,
      term2EndDate: true,
