export async function PATCH(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const role = ctx.session.user.role;
  if (role !== "ADMIN" && role !== "PRINCIPAL") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const schoolId = ctx.session.user.schoolId;
  const body = await request.json();
  const {
    name,
    boardType,
    address,
    phone,
    email,
    website,
    logoUrl,
    principalName,
    affiliationNumber,
    establishedYear,
    trustName,
    term1StartDate,
    term1EndDate,
    term2StartDate,
    term2EndDate,
  } = body;

  if (name !== undefined && (!name || typeof name !== "string" || name.trim() === "")) {
    return badRequest("School name cannot be empty");
  }

  const updateData: Record<string, any> = {};

  if (name !== undefined) updateData.name = name.trim();
  if (boardType !== undefined) updateData.boardType = boardType.trim() || "CBSE";
  if (address !== undefined) updateData.address = address ? address.trim() : null;
  if (phone !== undefined) updateData.phone = phone ? phone.trim() : null;
  if (email !== undefined) updateData.email = email ? email.trim() : null;
  if (website !== undefined) updateData.website = website ? website.trim() : null;
  if (logoUrl !== undefined) updateData.logoUrl = logoUrl ? logoUrl.trim() : null;
  if (principalName !== undefined) updateData.principalName = principalName ? principalName.trim() : null;
  if (affiliationNumber !== undefined)
    updateData.affiliationNumber = affiliationNumber ? affiliationNumber.trim() : null;
  if (trustName !== undefined) updateData.trustName = trustName ? trustName.trim() : null;
  if (term1StartDate !== undefined)
    updateData.term1StartDate = term1StartDate ? new Date(term1StartDate) : null;
  if (term1EndDate !== undefined)
    updateData.term1EndDate = term1EndDate ? new Date(term1EndDate) : null;
  if (term2StartDate !== undefined)
    updateData.term2StartDate = term2StartDate ? new Date(term2StartDate) : null;
  if (term2EndDate !== undefined)
    updateData.term2EndDate = term2EndDate ? new Date(term2EndDate) : null;

  if (establishedYear !== undefined) {
    if (establishedYear === null || establishedYear === "") {
      updateData.establishedYear = null;
    } else {
      const yr = parseInt(String(establishedYear), 10);
      if (isNaN(yr) || yr < 1800 || yr > new Date().getFullYear() + 1) {
        return badRequest("Invalid established year");
      }
      updateData.establishedYear = yr;
    }
  }

  try {
    const updated = await prisma.school.update({
      where: { id: schoolId },
      data: updateData,
      select: {
        id: true,
        name: true,
        boardType: true,
        address: true,
        phone: true,
        email: true,
        website: true,
        logoUrl: true,
        principalName: true,
        affiliationNumber: true,
        establishedYear: true,
        trustName: true,
        term1StartDate: true,
        term1EndDate: true,
        term2StartDate: true,
        term2EndDate: true,
        createdAt: true,
      },
    });

    return NextResponse.json(updated);
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : "Failed to update school settings";
    return badRequest(errorMsg);
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { checkRateLimit } from "@/lib/rateLimit";
import { logAuditEvent } from "@/lib/audit";

export async function POST(request: Request) {
  try {
    const ip = request.headers.get("x-forwarded-for") || "unknown-ip";
    const rateCheck = checkRateLimit(`verify-email:${ip}`, 10, 5 * 60 * 1000);
    if (!rateCheck.allowed) {
      return NextResponse.json(
        { error: "Too many verification attempts. Please wait a few minutes." },
        { status: 429 }
      );
    }

    const body = await request.json();
    const { email, token } = body;

    if (!email || !token) {
      return NextResponse.json(
        { error: "Email and verification token are required" },
        { status: 400 }
      );
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanToken = token.trim();

    const verification = await prisma.emailVerificationToken.findFirst({
      where: {
        email: cleanEmail,
        token: cleanToken,
        type: "SCHOOL_REGISTRATION",
        usedAt: null,
        expiresAt: { gt: new Date() },
      },
    });

    if (!verification) {
      return NextResponse.json(
        { error: "Invalid, expired, or already used verification token" },
        { status: 400 }
      );
    }

    // Mark token used
    await prisma.emailVerificationToken.update({
      where: { id: verification.id },
      data: { usedAt: new Date() },
    });

    // Mark school registration request email verified
    const updatedRequest = await prisma.schoolRegistrationRequest.updateMany({
      where: {
        adminEmail: cleanEmail,
        status: "PENDING",
      },
      data: {
        emailVerifiedAt: new Date(),
      },
    });

    await logAuditEvent({
      userEmail: cleanEmail,
      action: "SCHOOL_EMAIL_VERIFIED",
      targetType: "SchoolRegistrationRequest",
      details: { email: cleanEmail },
    });

    return NextResponse.json({
      success: true,
      message: "Email verified successfully. Your school registration is now pending review by the platform administrator.",
    });
  } catch (error: unknown) {
    console.error("[SCHOOL_REGISTRATION] Error verifying email:", error);
    return NextResponse.json(
      { error: "Failed to verify email" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest } from "@/lib/utils";
import { encryptPII, decryptPII, maskAadhaar } from "@/lib/security";
import { StudentUpdateSchema } from "@/lib/validations";

/**
 * GET /api/students/[id]
 * Returns full student profile including admission details, section & class,
 * parent linkages, fee invoices with payments, and last 30 attendance records.
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const { id } = await params;
  if (!id) return badRequest("Student ID is required");

  // If role is PARENT, verify parent is linked to this student
  if (ctx.session.user.role === "PARENT") {
    const parentLink = await ctx.db.studentParent.findFirst({
      where: {
        studentId: id,
        parent: { userId: ctx.session.user.id },
      },
    });
    if (!parentLink) {
      return NextResponse.json({ error: "Student not found" }, { status: 404 });
    }
  }

  const student = await ctx.db.student.findFirst({
    where: { id },
    include: {
      section: {
        include: { class: true },
      },
      parents: {
        include: {
          parent: {
            include: {
              user: {
                select: { id: true, email: true, phone: true, role: true },
              },
            },
          },
        },
      },
      invoices: {
        include: {
          feeStructure: true,
          payments: {
            orderBy: { paidAt: "desc" },
          },
        },
        orderBy: { dueDate: "desc" },
      },
      attendance: {
        orderBy: { date: "desc" },
        take: 30,
      },
    },
  });

  if (!student) {
    return NextResponse.json({ error: "Student not found" }, { status: 404 });
  }

  // Handle sensitive PII
  const role = ctx.session.user.role;
  const decryptedAadhaar = decryptPII(student.aadharNumber);
  const decryptedMedical = decryptPII(student.medicalConditions);

  const formattedStudent = {
    ...student,
    aadharNumber:
      role === "ADMIN" || role === "PRINCIPAL"
        ? decryptedAadhaar
        : maskAadhaar(decryptedAadhaar),
    medicalConditions: decryptedMedical,
  };

  return NextResponse.json(formattedStudent);
}

/**
 * PATCH /api/students/[id]
 * Updates editable enrollment and demographic details for a student.
 * admissionNo and schoolId are immutable.
 */
export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (ctx.session.user.role !== "ADMIN" && ctx.session.user.role !== "PRINCIPAL") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const { id } = await params;
  if (!id) return badRequest("Student ID is required");

  // Verify student belongs to this tenant
  const existingStudent = await ctx.db.student.findFirst({
    where: { id },
  });

  if (!existingStudent) {
    return NextResponse.json({ error: "Student not found" }, { status: 404 });
  }

  const body = await request.json().catch(() => ({}));
  const parsed = StudentUpdateSchema.safeParse(body);
  if (!parsed.success) {
    return badRequest(parsed.error.issues[0]?.message || "Invalid student data");
  }

  const data = parsed.data;
  const updateData: any = {};

  if (data.fullName !== undefined) updateData.fullName = data.fullName.trim();
  if (data.dob) {
    const dobDate = new Date(data.dob);
    if (!isNaN(dobDate.getTime())) {
      updateData.dob = dobDate;
    }
  }
  if (data.rollNumber !== undefined) updateData.rollNumber = data.rollNumber ? String(data.rollNumber).trim() : null;
  if (data.sectionId !== undefined) updateData.sectionId = data.sectionId || null;
  if (data.academicYear !== undefined) updateData.academicYear = data.academicYear;
