  if (data.bloodGroup !== undefined) updateData.bloodGroup = data.bloodGroup ? String(data.bloodGroup).trim() : null;
  if (data.aadharNumber !== undefined) {
    updateData.aadharNumber = data.aadharNumber ? encryptPII(String(data.aadharNumber).trim()) : null;
  }
  if (data.category !== undefined) updateData.category = data.category ? String(data.category).trim() : null;
  if (data.photoUrl !== undefined) updateData.photoUrl = data.photoUrl ? String(data.photoUrl).trim() : null;
  if (data.currentAddress !== undefined) updateData.currentAddress = data.currentAddress ? String(data.currentAddress).trim() : null;
  if (data.permanentAddress !== undefined) updateData.permanentAddress = data.permanentAddress ? String(data.permanentAddress).trim() : null;
  if (data.fatherName !== undefined) updateData.fatherName = data.fatherName ? String(data.fatherName).trim() : null;
  if (data.fatherOccupation !== undefined) updateData.fatherOccupation = data.fatherOccupation ? String(data.fatherOccupation).trim() : null;
  if (data.fatherPhone !== undefined) updateData.fatherPhone = data.fatherPhone ? String(data.fatherPhone).trim() : null;
  if (data.motherName !== undefined) updateData.motherName = data.motherName ? String(data.motherName).trim() : null;
  if (data.motherOccupation !== undefined) updateData.motherOccupation = data.motherOccupation ? String(data.motherOccupation).trim() : null;
  if (data.motherPhone !== undefined) updateData.motherPhone = data.motherPhone ? String(data.motherPhone).trim() : null;
  if (data.guardianName !== undefined) updateData.guardianName = data.guardianName ? String(data.guardianName).trim() : null;
  if (data.guardianRelation !== undefined) updateData.guardianRelation = data.guardianRelation ? String(data.guardianRelation).trim() : null;
  if (data.guardianPhone !== undefined) updateData.guardianPhone = data.guardianPhone ? String(data.guardianPhone).trim() : null;
  if (data.previousSchoolName !== undefined) updateData.previousSchoolName = data.previousSchoolName ? String(data.previousSchoolName).trim() : null;
  if (data.previousClass !== undefined) updateData.previousClass = data.previousClass ? String(data.previousClass).trim() : null;
  if (data.transferCertificateNumber !== undefined) updateData.transferCertificateNumber = data.transferCertificateNumber ? String(data.transferCertificateNumber).trim() : null;
  if (data.emergencyContactName !== undefined) updateData.emergencyContactName = data.emergencyContactName ? String(data.emergencyContactName).trim() : null;
  if (data.emergencyContactPhone !== undefined) updateData.emergencyContactPhone = data.emergencyContactPhone ? String(data.emergencyContactPhone).trim() : null;
  if (data.medicalConditions !== undefined) {
    updateData.medicalConditions = data.medicalConditions ? encryptPII(String(data.medicalConditions).trim()) : null;
  }
  if (data.classDesignation !== undefined) updateData.classDesignation = data.classDesignation ? String(data.classDesignation).trim() : null;
  if (data.isActive !== undefined) updateData.isActive = data.isActive;

  const updated = await ctx.db.student.update({
    where: { id },
    data: updateData,
    include: {
      section: {
        include: { class: true },
      },
      parents: {
        include: {
          parent: {
            include: {
              user: {
                select: { id: true, email: true, phone: true, role: true },
              },
            },
          },
        },
      },
      invoices: {
        include: {
          feeStructure: true,
          payments: {
            orderBy: { paidAt: "desc" },
          },
        },
        orderBy: { dueDate: "desc" },
      },
      attendance: {
        orderBy: { date: "desc" },
        take: 30,
      },
    },
  });

  const decryptedAadhaar = decryptPII(updated.aadharNumber);
  const decryptedMedical = decryptPII(updated.medicalConditions);

  return NextResponse.json({
    ...updated,
    aadharNumber: decryptedAadhaar,
    medicalConditions: decryptedMedical,
  });
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized, badRequest } from "@/lib/utils";
import { z } from "zod";

const StudentPromoteSchema = z.object({
  action: z.enum(["PROMOTE", "RETAIN", "GRADUATE"]),
  studentIds: z.array(z.string().min(1)).min(1, "At least one student must be selected"),
  targetSectionId: z.string().optional().nullable(),
  targetAcademicYear: z.string().min(1, "Target academic year is required"),
});

export async function POST(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  if (ctx.session.user.role !== "ADMIN" && ctx.session.user.role !== "PRINCIPAL") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const json = await request.json().catch(() => ({}));
  const parsed = StudentPromoteSchema.safeParse(json);
  if (!parsed.success) {
    return badRequest(parsed.error.issues[0]?.message || "Invalid promotion payload");
  }

  const { action, studentIds, targetSectionId, targetAcademicYear } = parsed.data;

  // If promoting or retaining, targetSectionId is required
  if ((action === "PROMOTE" || action === "RETAIN") && !targetSectionId) {
    return badRequest("Target section is required for promotion or retention");
  }

  // Verify targetSection belongs to tenant if specified
  if (targetSectionId) {
    const targetSec = await ctx.db.section.findUnique({
      where: { id: targetSectionId },
      include: { class: true },
    });
    if (!targetSec) {
      return badRequest("Target section not found in this school");
    }
  }

  // Verify all students belong to current tenant
  const validStudents = await ctx.db.student.findMany({
    where: {
      id: { in: studentIds },
    },
    select: { id: true, fullName: true, academicYear: true, sectionId: true },
  });

  if (validStudents.length !== studentIds.length) {
    return badRequest("One or more selected students do not belong to this school");
  }

  const db = ctx.db;
  const result = await (db as any).$transaction(async (tx: any) => {
    if (action === "GRADUATE") {
      const updated = await tx.student.updateMany({
        where: {
          id: { in: studentIds },
        },
        data: {
          isActive: false,
        },
      });
      return { count: updated.count, action: "GRADUATE" };
    }

    const updated = await tx.student.updateMany({
      where: {
        id: { in: studentIds },
      },
      data: {
        sectionId: targetSectionId,
        academicYear: targetAcademicYear,
        isActive: true,
      },
    });

    return { count: updated.count, action };
  });

  return NextResponse.json({
    message: `Successfully processed ${result.count} student(s) for ${action}`,
    ...result,
  });
}

import { NextResponse } from "next/server";
import { getTenantDb, unauthorized } from "@/lib/utils";

/**
 * GET /api/students/stats
 * Computes live attendance and student counts for today:
 * - totalStudents: count of active students (optionally scoped to sectionId)
 * - presentToday: count of active students marked PRESENT today
 * - absentToday: count of active students marked ABSENT today
 * - notMarkedToday: count of active students who have NO attendance record today
 *   (computed as total active students minus unique students marked today in any status)
 */
export async function GET(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();

  const { searchParams } = new URL(request.url);
  const sectionId = searchParams.get("sectionId");

  const todayStr = new Date().toISOString().split("T")[0];
  const todayDate = new Date(todayStr);

  const studentWhere: any = { isActive: true };
  if (sectionId === "unassigned") {
    studentWhere.sectionId = null;
  } else if (sectionId) {
    studentWhere.sectionId = sectionId;
  }

  // 1. Total active students in this school (or scoped to filtered section)
  const totalStudents = await ctx.db.student.count({
    where: studentWhere,
  });

  // 2. Fetch all attendance records for today for active students in this section/school
  const attendanceWhere: any = {
    date: todayDate,
    student: studentWhere,
  };
  if (sectionId && sectionId !== "unassigned") {
    attendanceWhere.sectionId = sectionId;
  }

  const todayAttendance = await ctx.db.attendance.findMany({
    where: attendanceWhere,
    select: {
      studentId: true,
      status: true,
    },
  });

  let presentToday = 0;
  let absentToday = 0;
  const markedStudentIds = new Set<string>();

  for (const record of todayAttendance) {
    markedStudentIds.add(record.studentId);
    if (record.status === "PRESENT") {
      presentToday++;
    } else if (record.status === "ABSENT") {
      absentToday++;
    }
  }

  // Not Marked Yet = total active students minus all students who have any attendance record today
  const notMarkedToday = Math.max(0, totalStudents - markedStudentIds.size);

  return NextResponse.json({
    totalStudents,
    presentToday,
    absentToday,
    notMarkedToday,
  });
}

import { NextResponse } from "next/server";
import {
  getRestrictedSuperAdminSession,
  getSuperAdminSession,
  unauthorized,
  forbidden,
} from "@/lib/utils";
import prisma from "@/lib/prisma";
import { Role } from "@prisma/client";
import {
  generateTotpSecret,
  generateOtpAuthUrl,
  generateRecoveryCodes,
  verifyTotpCode,
  verifyRecoveryCode,
  encryptSecret,
  decryptSecret,
} from "@/lib/totp";
import { logAuditEvent } from "@/lib/audit";
import bcrypt from "bcryptjs";

/**
 * GET /api/super-admin/mfa
 * Returns current MFA status and remaining recovery code count for Super Admin.
 * Permitted in restricted enrollment-only session.
 */
export async function GET() {
  const session = await getRestrictedSuperAdminSession();
  if (!session) return unauthorized();
  if (session.user.role !== Role.SUPER_ADMIN) return forbidden();

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: {
      email: true,
      mfaEnabled: true,
      mfaRecoveryCodes: true,
    },
  });

  if (!user) return unauthorized();

  return NextResponse.json({
    email: user.email,
    mfaEnabled: user.mfaEnabled,
    remainingRecoveryCodes: user.mfaRecoveryCodes ? user.mfaRecoveryCodes.length : 0,
  });
}

/**
 * POST /api/super-admin/mfa
 * Initiates MFA setup: generates Base32 secret and 8 recovery codes.
 * Stores pending setup securely in EmailVerificationToken for 15 minutes.
 * Permitted in restricted enrollment-only session.
 */
export async function POST() {
  const session = await getRestrictedSuperAdminSession();
  if (!session) return unauthorized();
  if (session.user.role !== Role.SUPER_ADMIN) return forbidden();

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) return unauthorized();

  const secret = generateTotpSecret();
  const { plainCodes, hashedCodes } = generateRecoveryCodes(8);
  const otpAuthUrl = generateOtpAuthUrl({
    issuer: "School ERP",
    accountName: user.email,
    secret,
  });

  // Clean up any stale pending setup tokens for this user
  await prisma.emailVerificationToken.deleteMany({
    where: {
      email: user.email,
      type: "MFA_SETUP_PENDING",
    },
  });

  // Store pending secret + hashed codes in ephemeral token (15m expiry)
  await prisma.emailVerificationToken.create({
    data: {
      email: user.email,
      token: secret,
      type: "MFA_SETUP_PENDING",
      expiresAt: new Date(Date.now() + 15 * 60 * 1000),
      metadata: JSON.stringify({
        hashedCodes,
      }),
    },
  });

  return NextResponse.json({
    success: true,
    secret,
    otpAuthUrl,
    recoveryCodes: plainCodes,
    message: "Save your recovery codes in a secure password manager. Verify a 6-digit authenticator code to activate.",
  });
}

/**
 * DELETE /api/super-admin/mfa
 * Disables MFA: strictly requires full privileged session, current password, and current TOTP or recovery code.
 */
export async function DELETE(request: Request) {
  const session = await getSuperAdminSession();
  if (!session) return unauthorized();
  if (session.user.role !== Role.SUPER_ADMIN) return forbidden();

  try {
    const body = await request.json();
    const { password, code } = body;

    if (!password || !code) {
      return NextResponse.json(
        { error: "Current password and authenticator code are required to disable MFA." },
        { status: 400 }
      );
    }

    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
    });

    if (!user || !user.passwordHash || !user.mfaSecret) {
      return NextResponse.json({ error: "User not found or MFA not active" }, { status: 400 });
    }

    // Verify password
    const passwordValid = await bcrypt.compare(password, user.passwordHash);
    if (!passwordValid) {
      return NextResponse.json({ error: "Incorrect password." }, { status: 403 });
    }

    // Decrypt stored secret and verify TOTP code or emergency recovery code
    const plainSecret = decryptSecret(user.mfaSecret);
    const cleanCode = code.trim();
    let codeValid = verifyTotpCode({ secret: plainSecret, token: cleanCode });

    if (!codeValid && user.mfaRecoveryCodes && user.mfaRecoveryCodes.length > 0) {
      const matchedHash = verifyRecoveryCode(cleanCode, user.mfaRecoveryCodes);
      if (matchedHash) {
        codeValid = true;
      }
    }

    if (!codeValid) {
      return NextResponse.json({ error: "Invalid authenticator code or recovery code." }, { status: 403 });
    }

    // Atomically disable MFA
    await prisma.user.update({
      where: { id: user.id },
      data: {
        mfaEnabled: false,
        mfaSecret: null,
        mfaRecoveryCodes: [],
      },
    });

    await logAuditEvent({
      userId: user.id,
      userEmail: user.email,
      action: "MFA_DISABLED",
      targetType: "User",
      targetId: user.id,
      details: { timestamp: new Date().toISOString() },
    });

    return NextResponse.json({
      success: true,
      message: "Multi-Factor Authentication has been disabled.",
    });
  } catch (error: unknown) {
    console.error("[MFA] Error disabling MFA:", error);
    return NextResponse.json({ error: "Failed to disable MFA" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getSuperAdminSession, unauthorized } from "@/lib/utils";
import { logAuditEvent } from "@/lib/audit";
import { createTrialSubscription } from "@/lib/subscription";
import { Role } from "@prisma/client";

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSuperAdminSession();
  if (!session) {
    return unauthorized();
  }

  const { id } = await params;
  if (!id) {
    return NextResponse.json({ error: "Request ID is required" }, { status: 400 });
  }

  try {
    const regRequest = await prisma.schoolRegistrationRequest.findUnique({
      where: { id },
    });

    if (!regRequest) {
      return NextResponse.json({ error: "Registration request not found" }, { status: 404 });
    }

    if (regRequest.status === "APPROVED") {
      return NextResponse.json({ error: "Request is already approved" }, { status: 400 });
    }

    // Process approval inside a transaction
    const result = await prisma.$transaction(async (tx) => {
      // 1. Create School
      const school = await tx.school.create({
        data: {
          name: regRequest.schoolName,
          boardType: regRequest.boardType || "CBSE",
          email: regRequest.officialEmail,
          phone: regRequest.phone,
          address: regRequest.address,
          principalName: regRequest.principalName,
          affiliationNumber: regRequest.affiliationNo,
          isActive: true,
          status: "APPROVED",
          approvedAt: new Date(),
          approvedByUserId: session.user.id,
        },
      });

      // 2. Setup standard default grading scale for the new school
      const defaultGrades = [
        { grade: "A1", minScore: 91, maxScore: 100 },
        { grade: "A2", minScore: 81, maxScore: 90 },
        { grade: "B1", minScore: 71, maxScore: 80 },
        { grade: "B2", minScore: 61, maxScore: 70 },
        { grade: "C1", minScore: 51, maxScore: 60 },
        { grade: "C2", minScore: 41, maxScore: 50 },
        { grade: "D", minScore: 33, maxScore: 40 },
        { grade: "E", minScore: 0, maxScore: 32 },
      ];

      for (const dg of defaultGrades) {
        await tx.gradingScale.create({
          data: {
            schoolId: school.id,
            grade: dg.grade,
            minScore: dg.minScore,
            maxScore: dg.maxScore,
          },
        });
      }

      // 3. Create or attach school admin user
      let adminUser = await tx.user.findUnique({
        where: { email: regRequest.adminEmail },
      });

      if (!adminUser) {
        adminUser = await tx.user.create({
          data: {
            email: regRequest.adminEmail,
            phone: regRequest.adminPhone,
            passwordHash: regRequest.adminPasswordHash,
            role: Role.ADMIN,
            schoolId: school.id,
            isActive: true,
            status: "ACTIVE",
            emailVerified: regRequest.emailVerifiedAt || new Date(),
          },
        });
      } else {
        // Link existing user to this school as ADMIN if unassigned
        adminUser = await tx.user.update({
          where: { id: adminUser.id },
          data: {
            schoolId: school.id,
            role: Role.ADMIN,
            status: "ACTIVE",
            isActive: true,
          },
        });
      }

      // 4. Update registration request
      const updatedRequest = await tx.schoolRegistrationRequest.update({
        where: { id },
        data: {
          status: "APPROVED",
          approvedAt: new Date(),
          approvedByUserId: session.user.id,
          schoolId: school.id,
        },
      });

      // 5. Automatically provision 30-day trial subscription for new school
      const trialEndsAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
      const starterPlan = await tx.subscriptionPlan.findUnique({
        where: { code: "PROFESSIONAL" },
      });

      await tx.subscription.create({
        data: {
          schoolId: school.id,
          planId: starterPlan?.id || null,
          status: "TRIALING",
          billingCycle: "ANNUAL",
          studentCount: 100,
          amount: 0,
          currency: "INR",
          trialStartsAt: new Date(),
          trialEndsAt,
          currentPeriodStart: new Date(),
          currentPeriodEnd: trialEndsAt,
        },
      });

      // 6. Send welcome notification to school administrator
      await tx.notification.create({
        data: {
          schoolId: school.id,
          userId: adminUser.id,
          title: "Welcome to School ERP!",
          message: `Congratulations! ${school.name} has been approved with a complimentary 30-day trial. Explore all features and configure your academic year.`,
          type: "APPROVAL",
          linkUrl: "/admin/dashboard",
        },
      });

      return { school, adminUser, updatedRequest };
    });

    // 5. Audit Log
    await logAuditEvent({
      schoolId: result.school.id,
      userId: session.user.id,
      userEmail: session.user.email,
      action: "SCHOOL_APPROVED",
      targetType: "School",
      targetId: result.school.id,
      details: {
        schoolName: result.school.name,
        adminEmail: result.adminUser.email,
        requestId: id,
      },
    });

    return NextResponse.json({
      success: true,
      schoolId: result.school.id,
      schoolName: result.school.name,
      adminEmail: result.adminUser.email,
    });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : "Failed to approve registration request";
    console.error("[SUPER_ADMIN] Error approving school registration:", error);
    return NextResponse.json(
      { error: errorMsg },
      { status: 500 }
    );
  }
}

