  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const body = await request.json().catch(() => ({}));
  const sectionId = typeof body.sectionId === "string" ? body.sectionId.trim() : "";
  const dayOfWeek = typeof body.dayOfWeek === "string" ? body.dayOfWeek.trim().toUpperCase() : "";
  const periodId = typeof body.periodId === "string" ? body.periodId.trim() : "";
  const subjectId = typeof body.subjectId === "string" && body.subjectId.trim() ? body.subjectId.trim() : null;
  const teacherId = typeof body.teacherId === "string" && body.teacherId.trim() ? body.teacherId.trim() : null;
  const academicYear = typeof body.academicYear === "string" ? body.academicYear.trim() : "2026-27";

  if (!sectionId) return badRequest("sectionId is required");
  if (!VALID_DAYS.includes(dayOfWeek)) return badRequest("Invalid dayOfWeek. Use MON-SAT");
  if (!periodId) return badRequest("periodId is required");

  // Verify section belongs to current tenant
  const section = await ctx.db.section.findUnique({ where: { id: sectionId } });
  if (!section) return badRequest("Section not found");

  // Verify period exists and is not a break
  const period = await ctx.db.period.findUnique({ where: { id: periodId } });
  if (!period) return badRequest("Period not found");
  if (period.isBreak) return badRequest("Cannot assign subjects to break periods");

  // Verify subject if provided
  if (subjectId) {
    const subject = await ctx.db.subject.findUnique({ where: { id: subjectId } });
    if (!subject) return badRequest("Subject not found");
  }

  // Verify teacher if provided
  if (teacherId) {
    const teacher = await ctx.db.teacher.findUnique({ where: { id: teacherId } });
    if (!teacher) return badRequest("Teacher not found");
  }

  // Timetable Conflict Detection: ensure teacher is not double-booked on same day + period
  if (teacherId) {
    const clash = await ctx.db.timetableSlot.findFirst({
      where: {
        teacherId,
        dayOfWeek,
        periodId,
        academicYear,
        sectionId: { not: sectionId },
      },
      include: {
        section: { include: { class: true } },
        teacher: true,
        period: true,
      },
    });
    if (clash) {
      return badRequest(
        `Teacher conflict: ${clash.teacher?.fullName || "Selected teacher"} is already assigned to ${clash.section.class.name}-${clash.section.name} on ${dayOfWeek} during ${clash.period.label}.`
      );
    }
  }

  const slot = await ctx.db.timetableSlot.upsert({
    where: {
      sectionId_dayOfWeek_periodId_academicYear: {
        sectionId,
        dayOfWeek,
        periodId,
        academicYear,
      },
    },
    create: {
      sectionId,
      dayOfWeek,
      periodId,
      subjectId,
      teacherId,
      academicYear,
    } as any,
    update: {
      subjectId,
      teacherId,
    },
    include: {
      period: true,
      subject: { select: { id: true, name: true } },
      teacher: { select: { id: true, fullName: true } },
    },
  });

  return NextResponse.json(slot);
}

/**
 * DELETE /api/timetable?id=X
 * Remove a timetable slot assignment.
 */
export async function DELETE(request: Request) {
  const ctx = await getTenantDb();
  if (!ctx) return unauthorized();
  if (!hasRole(ctx.session, ["ADMIN", "PRINCIPAL"])) return forbidden();

  const { searchParams } = new URL(request.url);
  const id = searchParams.get("id") || "";
  if (!id) return badRequest("Slot ID is required");

  const existing = await ctx.db.timetableSlot.findUnique({ where: { id } });
  if (!existing) return badRequest("Timetable slot not found");

  await ctx.db.timetableSlot.delete({ where: { id } });
  return NextResponse.json({ success: true });
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import crypto from "crypto";

export async function POST(request: Request) {
  try {
    const signature = request.headers.get("x-razorpay-signature") || "";
    const rawBody = await request.text();
    const webhookSecret = process.env.RAZORPAY_WEBHOOK_SECRET || "";

    // Verify HMAC-SHA256 signature
    if (webhookSecret) {
      const expectedSig = crypto
        .createHmac("sha256", webhookSecret)
        .update(rawBody)
        .digest("hex");

      if (expectedSig !== signature) {
        console.error("[RAZORPAY_WEBHOOK] Invalid signature");
        return NextResponse.json({ error: "Invalid webhook signature" }, { status: 400 });
      }
    } else if (process.env.NODE_ENV === "production") {
      return NextResponse.json({ error: "Webhook secret not configured" }, { status: 500 });
    }

    const payload = JSON.parse(rawBody);
    const eventId = payload.event_id || payload.id || `evt_${Date.now()}`;
    const eventType = payload.event || "unknown";

    // Idempotency: check if event already processed
    const existing = await prisma.webhookEvent.findFirst({
      where: { eventId },
    });

    if (existing) {
      return NextResponse.json({
        success: true,
        message: "Event already processed",
        alreadyProcessed: true,
      });
    }

    // Store the event record
    await prisma.webhookEvent.create({
      data: {
        eventId,
        eventType,
        payload: rawBody,
      },
    });

    // Handle specific events
    if (eventType === "payment.captured") {
      const paymentEntity = payload.payload?.payment?.entity;
      if (paymentEntity) {
        const invoiceId = paymentEntity.notes?.invoiceId;
        const amount = paymentEntity.amount ? paymentEntity.amount / 100 : 0;
        const paymentId = paymentEntity.id;

        if (invoiceId) {
          const invoice = await prisma.feeInvoice.findUnique({
            where: { id: invoiceId },
            include: { payments: true },
          });

          if (invoice) {
            // Check if payment already exists
            const existingPayment = await prisma.payment.findFirst({
              where: { gatewayRef: paymentId },
            });

            if (!existingPayment) {
              const receiptNumber = `WH-REC-${Date.now()}-${Math.floor(1000 + Math.random() * 9000)}`;

              await prisma.payment.create({
                data: {
                  schoolId: invoice.schoolId,
                  invoiceId: invoice.id,
                  amount,
                  method: "CARD",
                  gatewayRef: paymentId,
                  receiptNumber,
                },
              });

              // Recalculate invoice status
              const allPayments = await prisma.payment.findMany({
                where: { invoiceId: invoice.id },
              });
              const totalPaid = allPayments.reduce((s, p) => s + Number(p.amount), 0);
              const invoiceAmount = Number(invoice.amountDue);

              let newStatus = "UNPAID";
              if (totalPaid >= invoiceAmount) newStatus = "PAID";
              else if (totalPaid > 0) newStatus = "PARTIALLY_PAID";

              await prisma.feeInvoice.update({
                where: { id: invoice.id },
                data: { status: newStatus as any },
              });
            }
          }
        }
      }
    } else if (eventType === "refund.processed" || eventType === "refund.created") {
      const refundEntity = payload.payload?.refund?.entity;
      if (refundEntity) {
        const paymentId = refundEntity.payment_id;
        const refundAmount = refundEntity.amount ? refundEntity.amount / 100 : 0;
        const refundId = refundEntity.id;

        const originalPayment = await prisma.payment.findFirst({
          where: { gatewayRef: paymentId },
          include: { invoice: true },
        });

        if (originalPayment && refundAmount > 0) {
          const existingRefund = await prisma.payment.findFirst({
            where: { gatewayRef: refundId },
          });

          if (!existingRefund) {
            const refundReceipt = `WH-REF-${Date.now()}-${Math.floor(1000 + Math.random() * 9000)}`;

            await prisma.$transaction(async (tx) => {
              await tx.payment.create({
                data: {
                  schoolId: originalPayment.schoolId,
                  invoiceId: originalPayment.invoiceId,
                  amount: -refundAmount,
                  method: "REFUND",
                  gatewayRef: refundId,
                  receiptNumber: refundReceipt,
                },
              });

              const allPayments = await tx.payment.findMany({
                where: { invoiceId: originalPayment.invoiceId },
              });
              const netPaid = allPayments.reduce((s, p) => s + Number(p.amount), 0);
              const invoiceAmount = Number(originalPayment.invoice.amountDue);

              let newStatus: any = "UNPAID";
              if (netPaid >= invoiceAmount) newStatus = "PAID";
              else if (netPaid > 0) newStatus = "PARTIALLY_PAID";

              await tx.feeInvoice.update({
                where: { id: originalPayment.invoiceId },
                data: { status: newStatus },
              });
            });
          }
        }
      }
    } else if (eventType === "payment.failed") {
      console.warn("[RAZORPAY_WEBHOOK] Payment failed:", payload.payload?.payment?.entity?.id);
    }

    return NextResponse.json({ success: true, eventId });
  } catch (error: unknown) {
    console.error("[RAZORPAY_WEBHOOK] Error processing webhook:", error);
    return NextResponse.json(
      { error: "Webhook processing failed" },
      { status: 500 }
    );
  }
}

