            </div>
          </form>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import Link from "next/link";
import { CheckCircle2, AlertCircle, ArrowRight, Mail } from "lucide-react";

function VerifyEmailForm() {
  const searchParams = useSearchParams();
  const initialType = searchParams.get("type") === "parent" ? "parent" : "school";
  const initialEmail = searchParams.get("email") || "";
  const initialToken = searchParams.get("token") || "";

  const [type, setType] = useState<"school" | "parent">(initialType);
  const [email, setEmail] = useState(initialEmail);
  const [token, setToken] = useState(initialToken);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState<string | null>(null);

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const endpoint = type === "parent" ? "/api/parent/verify-email" : "/api/schools/verify-email";
      const res = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), token: token.trim() }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Verification failed");
      }

      setSuccess(data.message || "Email verified successfully!");
    } catch (err: any) {
      setError(err.message || "Verification failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: "480px", margin: "0 auto" }}>
      <div style={{ textAlign: "center", marginBottom: "28px" }}>
        <div
          style={{
            width: "48px",
            height: "48px",
            borderRadius: "10px",
            backgroundColor: "var(--brand-primary)",
            color: "#fff",
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            marginBottom: "12px",
          }}
        >
          <Mail size={24} />
        </div>
        <h1 style={{ fontSize: "24px", fontWeight: 700, color: "var(--text-primary)", margin: "0 0 6px 0" }}>
          Verify Your Email
        </h1>
        <p style={{ fontSize: "14px", color: "var(--text-secondary)", margin: 0 }}>
          Confirm your email verification token to activate your account.
        </p>
      </div>

      {error && (
        <div
          style={{
            backgroundColor: "#fef2f2",
            border: "1px solid #fecaca",
            color: "#b91c1c",
            padding: "12px 16px",
            borderRadius: "8px",
            marginBottom: "20px",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "13.5px",
          }}
        >
          <AlertCircle size={18} />
          <span>{error}</span>
        </div>
      )}

      {success ? (
        <div
          style={{
            backgroundColor: "#ffffff",
            border: "1px solid var(--border-color)",
            borderRadius: "12px",
            padding: "32px",
            textAlign: "center",
          }}
        >
          <div
            style={{
              width: "56px",
              height: "56px",
              borderRadius: "50%",
              backgroundColor: "#ecfdf5",
              color: "#059669",
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
              marginBottom: "16px",
            }}
          >
            <CheckCircle2 size={30} />
          </div>
          <h2 style={{ fontSize: "20px", fontWeight: 700, color: "var(--text-primary)", marginBottom: "8px" }}>
            Verification Complete
          </h2>
          <p style={{ fontSize: "14px", color: "var(--text-secondary)", marginBottom: "24px" }}>
            {success}
          </p>

          <Link
            href="/login"
            className="btn btn-primary"
            style={{ padding: "10px 24px", textDecoration: "none", display: "inline-flex", alignItems: "center", gap: "8px" }}
          >
            <span>Proceed to Login</span>
            <ArrowRight size={16} />
          </Link>
        </div>
      ) : (
        <form
          onSubmit={handleVerify}
          style={{
            backgroundColor: "#ffffff",
            border: "1px solid var(--border-color)",
            borderRadius: "12px",
            padding: "28px",
          }}
        >
          <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
            <div>
              <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                Account Type
              </label>
              <div style={{ display: "flex", gap: "12px" }}>
                <label style={{ display: "flex", alignItems: "center", gap: "6px", fontSize: "13px", cursor: "pointer" }}>
                  <input
                    type="radio"
                    name="accountType"
                    value="school"
                    checked={type === "school"}
                    onChange={() => setType("school")}
                  />
                  School Registration
                </label>
                <label style={{ display: "flex", alignItems: "center", gap: "6px", fontSize: "13px", cursor: "pointer" }}>
                  <input
                    type="radio"
                    name="accountType"
                    value="parent"
                    checked={type === "parent"}
                    onChange={() => setType("parent")}
                  />
                  Parent Account
                </label>
              </div>
            </div>

            <div>
              <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                Email Address *
              </label>
              <input
                type="email"
                required
                placeholder="name@example.com"
                className="form-input"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>

            <div>
              <label className="form-label" style={{ display: "block", fontSize: "13px", fontWeight: 500, marginBottom: "4px" }}>
                Verification Token *
              </label>
              <input
                type="text"
                required
                placeholder="Paste your verification token here"
                className="form-input"
                value={token}
                onChange={(e) => setToken(e.target.value)}
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="btn btn-primary"
            style={{
              width: "100%",
              height: "42px",
              marginTop: "20px",
              fontSize: "14px",
              fontWeight: 600,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "8px",
            }}
          >
            {loading ? "Verifying Token..." : "Verify & Confirm"}
            <ArrowRight size={16} />
          </button>

          <div style={{ marginTop: "16px", textAlign: "center", fontSize: "13px" }}>
            <Link href="/login" style={{ color: "var(--brand-primary)", fontWeight: 500, textDecoration: "none" }}>
              Back to Login
            </Link>
          </div>
        </form>
      )}
    </div>
  );
}

export default function VerifyEmailPage() {
  return (
    <div style={{ minHeight: "100vh", backgroundColor: "var(--bg-main)", padding: "40px 16px" }}>
      <Suspense fallback={<div style={{ textAlign: "center", padding: "40px" }}>Loading verification portal...</div>}>
        <VerifyEmailForm />
      </Suspense>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Printer, Download, X, FileText, Loader2 } from "lucide-react";

interface CertificateData {
  type: "BONAFIDE" | "TC" | "CHARACTER";
  student: {
    fullName: string;
    admissionNo: string;
    dob: string;
    gender?: string | null;
    fatherName?: string | null;
    motherName?: string | null;
    academicYear: string;
    section?: { name: string; className: string } | null;
  };
  school: {
    name: string;
    address?: string | null;
    phone?: string | null;
    email?: string | null;
    logoUrl?: string | null;
    principalName?: string | null;
    affiliationNumber?: string | null;
    trustName?: string | null;
  };
  fields: Record<string, string | undefined>;
}

interface Props {
  data: CertificateData;
  onClose?: () => void;
}

const CERT_TITLES: Record<string, string> = {
  BONAFIDE: "BONAFIDE CERTIFICATE",
  TC: "TRANSFER CERTIFICATE",
  CHARACTER: "CHARACTER CERTIFICATE",
};

function formatCertDate(d: string | undefined): string {
  if (!d) return "—";
  try {
    const date = new Date(d);
    return date.toLocaleDateString("en-IN", { day: "2-digit", month: "long", year: "numeric" });
  } catch {
    return d;
  }
}

export default function CertificateView({ data, onClose }: Props) {
  const { type, student, school, fields } = data;
  const [downloadingPdf, setDownloadingPdf] = useState(false);

  const handlePrint = () => window.print();

  const handleDownloadPdf = async () => {
    try {
      setDownloadingPdf(true);
      const html2pdf = (await import("html2pdf.js")).default;
      const element = document.getElementById("printable-certificate");
      if (!element) return;

      const nameClean = (student.fullName || "Student").replace(/[^a-zA-Z0-9_-]/g, "_");
      const filename = `${nameClean}_${type}_Certificate.pdf`;

      const opt = {
        margin: [10, 10, 10, 10] as [number, number, number, number],
        filename,
        image: { type: "jpeg", quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, letterRendering: true, logging: false },
        jsPDF: { unit: "mm", format: "a4", orientation: "portrait" as const },
      };

      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("Failed to generate PDF:", err);
    } finally {
      setDownloadingPdf(false);
    }
  };

  return (
    <div className="report-card-wrapper">
      {/* Action Bar */}
      <div className="report-card-actions no-print">
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <span style={{ fontSize: "13px", fontWeight: 600, color: "var(--text-secondary)" }}>
            {CERT_TITLES[type]}
          </span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <button
            type="button"
            className="btn btn-secondary btn-sm"
            onClick={handleDownloadPdf}
            disabled={downloadingPdf}
            style={{ gap: "6px" }}
          >
            {downloadingPdf ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
            <span>{downloadingPdf ? "Generating PDF..." : "Download PDF"}</span>
          </button>
          <button
            type="button"
            className="btn btn-secondary btn-sm"
            onClick={handlePrint}
            style={{ gap: "6px" }}
          >
            <Printer size={14} />
            <span>Print</span>
          </button>
          {onClose && (
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={onClose}
              style={{ padding: "6px" }}
              aria-label="Close"
            >
              <X size={16} />
            </button>
          )}
        </div>
      </div>

      {/* Certificate Sheet */}
      <div className="certificate-sheet" id="printable-certificate">
        {/* Decorative border */}
        <div className="cert-border-outer">
          <div className="cert-border-inner">
            {/* Header */}
            <div className="cert-header">
              {school.logoUrl ? (
                <div className="cert-logo-wrap">
                  <img src={school.logoUrl} alt={school.name} className="cert-logo" />
                </div>
              ) : (
                <div className="cert-logo-placeholder">
                  <FileText size={32} color="#991b1b" />
                </div>
              )}
              <div className="cert-school-info">
                {school.trustName && <div className="cert-trust">{school.trustName}</div>}
                <h1 className="cert-school-name">{school.name}</h1>
                {school.address && <div className="cert-address">{school.address}</div>}
                {school.affiliationNumber && (
                  <div className="cert-affiliation">Affiliation No: {school.affiliationNumber}</div>
                )}
              </div>
              <div className="cert-header-line" />
            </div>

            {/* Certificate Title */}
            <div className="cert-title">{CERT_TITLES[type]}</div>
            {type === "TC" && fields.tcNumber && (
              <div className="cert-serial">TC No: {fields.tcNumber}</div>
            )}

            {/* Certificate Body */}
            <div className="cert-body">
              {type === "BONAFIDE" && (
                <div className="cert-text">
                  <p>This is to certify that <strong className="cert-highlight">{student.fullName}</strong>,
                    {student.gender ? ` ${student.gender === "Male" ? "son" : student.gender === "Female" ? "daughter" : "ward"}` : " ward"}
                    {" "}of <strong>{student.fatherName || "—"}</strong>
                    {student.motherName ? ` and ${student.motherName}` : ""},
                    is a bonafide student of this institution.</p>
                  <div className="cert-detail-grid">
                    <div className="cert-detail-row">
                      <span className="cert-label">Admission No:</span>
                      <span className="cert-value">{student.admissionNo}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Class & Section:</span>
                      <span className="cert-value">
                        {student.section ? `${student.section.className} — ${student.section.name}` : "—"}
                      </span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Academic Year:</span>
                      <span className="cert-value">{student.academicYear}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Date of Birth:</span>
                      <span className="cert-value">{formatCertDate(student.dob)}</span>
                    </div>
                    {fields.purpose && (
                      <div className="cert-detail-row" style={{ gridColumn: "1 / -1" }}>
                        <span className="cert-label">Purpose:</span>
                        <span className="cert-value">{fields.purpose}</span>
                      </div>
                    )}
                  </div>
                  <p style={{ marginTop: "18px" }}>
                    This certificate is issued on request for the purpose of{" "}
                    <strong>{fields.purpose || "official use"}</strong>.
                  </p>
                </div>
              )}

              {type === "TC" && (
                <div className="cert-text">
                  <p>This is to certify that <strong className="cert-highlight">{student.fullName}</strong>,
                    {student.gender ? ` ${student.gender === "Male" ? "son" : student.gender === "Female" ? "daughter" : "ward"}` : " ward"}
                    {" "}of <strong>{student.fatherName || "—"}</strong>
                    {student.motherName ? ` and ${student.motherName}` : ""},
                    was a student of this institution and is hereby granted this Transfer Certificate.</p>
                  <div className="cert-detail-grid">
                    <div className="cert-detail-row">
                      <span className="cert-label">Admission No:</span>
                      <span className="cert-value">{student.admissionNo}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Date of Birth:</span>
                      <span className="cert-value">{formatCertDate(student.dob)}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Class & Section:</span>
                      <span className="cert-value">
                        {student.section ? `${student.section.className} — ${student.section.name}` : "—"}
                      </span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Academic Year:</span>
                      <span className="cert-value">{student.academicYear}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Last Attendance:</span>
                      <span className="cert-value">{formatCertDate(fields.lastAttendanceDate)}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Reason for Leaving:</span>
                      <span className="cert-value">{fields.reasonForLeaving}</span>
                    </div>
                    <div className="cert-detail-row" style={{ gridColumn: "1 / -1" }}>
                      <span className="cert-label">Conduct & Character:</span>
                      <span className="cert-value">{fields.conductRemark || "Good"}</span>
                    </div>
                  </div>
                  <p style={{ marginTop: "18px" }}>
                    The student&apos;s character and conduct during the stay in this institution were found to be{" "}
                    <strong>{fields.conductRemark || "Good"}</strong>.
                  </p>
                </div>
              )}

              {type === "CHARACTER" && (
                <div className="cert-text">
                  <p>This is to certify that <strong className="cert-highlight">{student.fullName}</strong>,
                    {student.gender ? ` ${student.gender === "Male" ? "son" : student.gender === "Female" ? "daughter" : "ward"}` : " ward"}
                    {" "}of <strong>{student.fatherName || "—"}</strong>
                    {student.motherName ? ` and ${student.motherName}` : ""},
                    is/was a student of this institution.</p>
                  <div className="cert-detail-grid">
                    <div className="cert-detail-row">
                      <span className="cert-label">Admission No:</span>
                      <span className="cert-value">{student.admissionNo}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Class & Section:</span>
                      <span className="cert-value">
                        {student.section ? `${student.section.className} — ${student.section.name}` : "—"}
                      </span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Academic Year:</span>
                      <span className="cert-value">{student.academicYear}</span>
                    </div>
                    <div className="cert-detail-row">
                      <span className="cert-label">Date of Birth:</span>
                      <span className="cert-value">{formatCertDate(student.dob)}</span>
                    </div>
                  </div>
                  <p style={{ marginTop: "18px" }}>
                    During the period of study, the student&apos;s character and conduct were found to be{" "}
                    <strong>{fields.conductRemark || "Good"}</strong>. We wish the student all the best in future endeavours.
                  </p>
                </div>
              )}
            </div>

            {/* Date & Signatures */}
            <div className="cert-footer">
              <div className="cert-date">
                Date: {formatCertDate(fields.issueDate)}
              </div>
              <div className="cert-signatures">
                <div className="cert-sig-col">
                  <div className="cert-sig-line" />
                  <div className="cert-sig-label">Class Teacher</div>
                </div>
                <div className="cert-sig-col">
                  {school.principalName && (
                    <div className="cert-principal-name">{school.principalName}</div>
                  )}
                  <div className="cert-sig-line" />
                  <div className="cert-sig-label">Principal</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
